INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(12818, 'koKR', 'Sprzątanie', 'Do rzeczy... Ricket poprosiła mnie o skonstruowanie mocniejszych min lądowych, ale kończą mi się części.$B$BTuż na zachód od osady znajdziesz szczątki naszych ostatnich sań rakietowych... Ricket trochę się podekscytowała przy tankowaniu, ale chyba powinienem był pomyśleć, żeby nie montować wlewu tuż nad wydechem. Człowiek uczy się na błędach, co?$B$BWokół zniszczonych sań powinno leżeć sporo części zamiennych... może przegonisz tych padlinożerców i zgarniesz dla mnie trochę tego złomu?', 'Jeer Sparksocket z K3 chce 10 kawałków zwęglonego wraku.', '', 'Wróć do Jeera Sparksocketa w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12819, 'koKR', 'Tuż za rogiem', 'Do licha! Gdzie są moje narzędzia? Przed chwilą je tu miałem.$B$BO! Pewnie zostawiłem je, kiedy rozstawiałem to pole minowe na zachodzie. Trochę to kłopotliwe. Byłbym bardzo wdzięczny, gdybyś mi je $gprzyniósł:przyniosła;. Tylko uważaj, gdzie stawiasz nogi... powinno ci się udać wyjść tą samą ścieżką, którą ja wyszedłem.$B$BA, i nawet nie próbuj tam wlatywać... Miałem na tyle oleju w głowie, żeby rozstawić wieżyczki, które zestrzelą wszystko, co lata, a one nie są zbyt wybredne w doborze celów.', 'Jeer Sparksocket z K3 chce, żebyś $godzyskał:odzyskała; narzędzia Sparksocketa z jego pola minowego.', '', 'Wróć do Jeera Sparksocketa w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12820, 'koKR', 'Delikatny dotyk', 'Czekam na te miny od wieków! No, przynajmniej od kilku dni. Czemu mu to tyle zajęło?$B$BSłuchaj, kolego, sprawa wygląda tak... jest tu banda paskudnych magnataurów – no wiesz, wielkich, włochatych i wyjątkowo szpetnych – i bardzo im zależy, żeby zagarnąć K3 dla siebie.$B$BNic z tego.$B$BNa ich drodze, na północny wschód stąd, rozstawiliśmy trochę umocnień. Niestety nasze wieżyczki laserowe mają dość ograniczone zasilanie... i tu wkraczają te miny! Idź tam i porządnie ich wysadź!', 'Ricket z K3 chce, żebyś $gużył:użyła; ulepszonych min lądowych przy Zgubie Garma, by odeprzeć 12 napastników z Garm. Liczą się zarówno najeźdźcy z Garm, jak i wyznawcy Śnieżnej Ślepoty.', '', 'Wróć do Ricket w K3 na Burzowych Szczytach.', 'Zabici napastnicy z Garm', '', '', '', 0),
(12821, 'koKR', 'Otwieranie tylnych drzwi', 'Oddział saperów jest gotowy. To znaczy, że zaczyna się zabawa, $gmój drogi:moja droga;!$B$BTylko jedno powstrzymuje nas przed zmasowanym atakiem na Garm! Wysłałam gońca, żeby ustawił teleporter za Garm – z powodzeniem, dodam – a on wrócił po ogniwo zasilające, bez którego teleporter nie działa. Teleporter wciąż nie działa... co znaczy, że ogniwo tam nie dotarło.$B$BPoszukaj tego ogniwa zasilającego tuż po drugiej stronie Zguby Garma. Kiedy je znajdziesz, zanieś je dalej na wschód, na Wzniesienie Garma, i uruchom teleporter.', 'Ricket z K3 chce, żebyś $godnalazł:odnalazła; ogniwo zasilające transportera i $guruchomił:uruchomiła; nim platformę teleportacyjną na Wzniesieniu Garma.', 'Teleporter Garma uruchomiony', 'Wróć do Ricket w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12822, 'koKR', 'Bez strachu', 'Teraz, kiedy teleporter jest otwarty, mój plan jest dość złożony... ma kilka etapów i wymaga nienagannej koordynacji. Trzeba zebrać zapasy! Zwerbować oddziały! Pewnie też czekają nas tygodnie ciężkiej harówki!$B$BHa, ha, $gnabrałeś:nabrałaś; się na chwilę, co? Dasz radę, młody. Wskakuj do teleportera i zanieś im walkę pod same drzwi! Nasi saperzy będą cię wspierać... nie będą mieli dokąd uciec.', 'Ricket z K3 chce, żebyś $gzabił:zabiła; 6 wartowników z Garm i 8 czcicieli Śnieżnej Ślepoty.', '', 'Wróć do Ricket w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12823, 'koKR', 'Plan bez skazy', 'Hej! Zgaduję, że dołączasz do szturmu?$B$BMam dla ciebie specjalne zadanie... zawalimy im całą jaskinię na łby! W głębi jaskini znajdziesz Ołtarz Mroźnobrzucha. Zakradnij się i podłóż ten ubity ładunek wybuchowy gdzieś blisko niego.$B$BKiedy ładunek będzie na miejscu, zostań tylko tak długo, żeby się upewnić, że Mroźnobrzuch wyzionie ducha, a potem szybko uciekaj! Nie wiadomo, jak długo jaskinia wytrzyma, kiedy to cudo wybuchnie!', 'Gino na Wzniesieniu Garma chce, żebyś $gpodłożył:podłożyła; ubity ładunek wybuchowy przy Ołtarzu Mroźnobrzucha, $gzabił:zabiła; Tormara Mroźnobrzucha, a potem $guciekł:uciekła; z jaskini, zanim się na ciebie zawali.', '', 'Wróć do Gina na Wzniesieniu Garma na Burzowych Szczytach.', 'Podłóż ładunek wybuchowy', '', '', '', 0),
(12824, 'koKR', 'Wyjątkowy specjalista od wyburzeń', 'Szybkie masz nogi, $gsynku:dziewczyno;! Dzięki za pomoc z materiałami wybuchowymi... od dawna czekałem, żeby porządnie przetestować ten wynalazek!$B$BIdź i powiedz Ricket, że front magnataurów mamy już chyba z głowy... moi saperzy wykończą resztę tych drani.$B$BJeszcze raz dzięki!', 'Wróć do Ricket w K3.', '', '', '', '', '', '', 0),
(12825, 'koKR', 'Wyrazy wdzięczności', '', '', '', '', '', '', '', '', 0),
(12826, 'koKR', 'Lekko niestabilne', 'Świetnie wyglądają!$B$BNie, nie ty – moje nowe miny. Trochę za bardzo jesteś z siebie $gzadowolony:zadowolona;, co? Za to ja jestem absolutnie genialny! Mój intelekt nie ma sobie równych.$B$BO czym to mówiliśmy? A tak, o moich nowych minach! Nowe i ulepszone... gotowe do jakiegokolwiek podstępnego użytku, jaki wymyśliła Ricket.$B$BBądź $gdobrym chłopcem:laleczką; i zanieś je Ricket, dobrze? Jest tuż obok... to na pewno będzie epicka wyprawa. Tylko uważaj, ona ma lekko nie po kolei w głowie.', 'Dostarcz ulepszone miny lądowe Jeera Ricket w K3.', '', 'Wróć do Ricket w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12827, 'koKR', 'Odzyskane racje', 'Hej, hej! Nowa twarz! Pomożesz Ricket?$B$BMamy dość niespodziewany problem – brak jedzenia. Wiem, wiem... powinniśmy byli to przewidzieć, ale nie rozumiesz. Nasz oddział saperów dość szybko się tu zmienia, więc zwykle nie musimy się martwić o długoterminowe żarcie. Ale stare, dobre K3 zrobiło się popularne.$B$BWygodne rozwiązanie? Na zachodzie są obozy gnoli, a sporo gnoli kręci się po okolicy i grzebie w odpadkach, jak to gnole. Może zgarniesz trochę ich racji?', 'Ricket z K3 chce, żebyś $godebrał:odebrała; 16 suszonych racji gnoli pobliskim gnolom z Dzikiego Wzgórza.', '', 'Wróć do Ricket w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12828, 'koKR', 'Obfita inspiracja', 'Fuj! To świństwo jest obrzydliwe. Nie żebym liczyła na gust gnoli czy coś, ale myślałam, że to, co mają, będzie przynajmniej... jadalne?$B$BWykażmy się większą kreatywnością.$B$BTore ma dozownik materiałów wybuchowych na północ od osady... niedaleko wielkiego wejścia do pieczary, nie przegapisz go. Pewnie przeznacza je do jakichś celów górniczych, ale ja mam lepszy pomysł.$B$BWeź jedno z tych urządzeń i pędź z nim do któregoś z pobliskich mamutów... większość jest na zachodzie. Zbierz mięso i przynieś je tutaj.', 'Ricket z K3 chce, żebyś $gwziął:wzięła; U.D.E.D., $gwysadził:wysadziła; nim mamuta i $gprzyniósł:przyniosła; 8 kawałków pożywnego mięsa mamuta.', '', 'Wróć do Ricket w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12829, 'koKR', 'Wprowadzamy się', 'Hejka! Jestem Tore. Kieruję tutejszymi pracami górniczymi w K3... a przynajmniej niedługo będę!$B$BTa jaskinia jest pełna pełzającego paskudztwa. Przydałoby się, żeby przed przeprowadzką było tu trochę mniej pająków – co o tym myślisz?', 'Tore Rumblewrench przed Pieczarą Kryształowej Sieci chce, żebyś $gzabił:zabiła; 12 pająków Kryształowej Sieci.', '', 'Wróć do Tore Rumblewrench przy Pieczarze Kryształowej Sieci na Burzowych Szczytach.', 'Zabite pająki Kryształowej Sieci', '', '', '', 0),
(12830, 'koKR', 'Przejęcie rudy', 'Wprowadzamy się!$B$BKiedy tu przybyliśmy, były tu jakieś snoboldy... wygląda jednak na to, że ich wydobycie spotkał jakiś niefortunny los. Nieważne – i tak niedługo mieliśmy to przejąć.$B$BWysłałam tam kilku naszych górników po próbki rudy, żebym mogła skalibrować maszyny do jej przerobu, ale nie wrócili.$B$BMożesz tam wejść i zdobyć dla mnie te próbki zamiast nich? Snoboldy pewnie mają trochę przy sobie, choć spodziewam się, że większość z nich już nie żyje.', 'Tore Rumblewrench przed Pieczarą Kryształowej Sieci chce, żebyś $gzdobył:zdobyła; 5 próbek zanieczyszczonej rudy saronitu.', '', 'Wróć do Tore Rumblewrench przy Pieczarze Kryształowej Sieci na Burzowych Szczytach.', '', '', '', '', 0),
(12831, 'koKR', 'Tylko częściowo zapomniany', 'Ojej... czuję się, jakbym miał śmigło w żołądku.$B$BChyba mogę iść, ale coś paskudnego dostało mi się do krwi, kiedy coś mnie ugryzło w głębi jaskini. Było większe niż inne pająki... i jaskrawo ubarwione.$B$BRicket pewnie zrobi mi odtrutkę, ale potrzebowałaby woreczka jadowego tego, co mnie ugryzło. Znajdziesz go dla mnie? Chyba Tore po mnie nie przyjdzie.$B$BA ja tu sobie poudaję trupa i może dadzą mi spokój.', 'Ranny gobliński górnik w Pieczarze Kryształowej Sieci chce, żebyś $gprzyniósł:przyniosła; woreczek jadowy pełzacza lodowego grotu.', '', 'Wróć do rannego goblińskiego górnika w Pieczarze Kryształowej Sieci na Burzowych Szczytach.', '', '', '', '', 0),
(12832, 'koKR', 'Gorzkie pożegnanie', 'Ojej – dziękuję! Byłem pewien, że skończę jako przekąska dla pająków. Chociaż może trochę za wcześnie się cieszę – zwiewajmy stąd!$B$BDaj znać, jak tylko będziesz $ggotów:gotowa; do drogi... i pospiesz się.', 'Wyeskortuj rannego goblińskiego górnika z Pieczary Kryształowej Sieci, a potem porozmawiaj z Ricket w K3.', 'Wyeskortuj rannego goblińskiego górnika do K3.', 'Wróć do Ricket w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12833, 'koKR', 'Nadmiar zapasów', 'Znowu cześć! Nie $guciekłeś:uciekłaś; jak wszyscy inni poszukiwacze przygód? No, jesteś po prostu skarbem, co? Już zaczynałam myśleć, że dziwnie pachnę albo coś!$B$BWciąż przydałaby się nam tu pomoc, a ty masz akurat odpowiednie doświadczenie. Pamiętasz te magnataury? No więc jaskinia chyba nie zawaliła się do końca... wciąż zostało ich całkiem sporo. Tyle, jeśli chodzi o to, że Gino się nimi zajął, co?$B$BNa szczęście Jeer zrobił min aż nadto. Dasz radę!', 'Ricket z K3 chce, żebyś $gużył:użyła; ulepszonych min lądowych przy Zgubie Garma, by odeprzeć napastników z Garm. Liczą się zarówno najeźdźcy z Garm, jak i wyznawcy Śnieżnej Ślepoty.', '', 'Wróć do Ricket w K3 na Burzowych Szczytach.', 'Zabici najeźdźcy z Garm', '', '', '', 0),
(12834, 'koKR', 'Ani deszcz, ani śnieg, ani wybuchający samolot', '', '', '', '', '', '', '', '', 0),
(12835, 'koKR', 'Całkiem dorosły', '', '', '', '', '', '', '', '', 0),
(12836, 'koKR', 'Wyraz wdzięczności', 'Mam idealną robotę dla $gchętnego nowicjusza:chętnej nowicjuszki;! Mamy problem z gnolami. Można by nawet powiedzieć, że plagę gnoli! Uciążliwe stworzenia. Podchodzą coraz bliżej, a teraz są już pod naszym progiem i kradną nam części! Nie do pomyślenia.$B$BWszystko zaczyna się i kończy na ich zarozumiałym przywódcy, Sękatej Skórze. Chcę, żebyś $gzajął:zajęła; się tym „kończy”. Złóż mu wizytę w jego obozie, daleko na zachodzie, na Wzgórzach Śnieżnej Ślepoty.$B$BA kiedy mówię „złóż mu wizytę”, to jest eufemizm na „zabij go boleśnie”. Jasne? Jasne!', 'Ricket z K3 chce, żebyś $gzabił:zabiła; Sękatą Skórę.', '', 'Wróć do Ricket w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12837, 'koKR', 'Tore ma towar', '', '', '', '', '', '', '', '', 0),
(12841, 'koKR', 'Układ ze staruchą', 'Tak, to na pewno zielonoskórego więźnia szukasz... Może zdołamy sobie nawzajem pomóc.$B$BSiłą nie wydostaniesz stąd tego goblina. W każdym razie nie żywego.$B$BWśród mego ludu jestem znana jako Yrkvinn, mistrzyni iluzji. Jak widzisz, Hyldnir uczyniły mnie swoją więźniarką.$B$BGdybym miała swoje runy, mogłabym sprawić, że przejdziesz między nimi niezauważenie. Głębiej w środku, patrolując kopalnie, znajdziesz nadzorczynię o imieniu Syra. To ona ma moje runy. Odzyskaj je, a wtedy porozmawiamy dalej.', 'Lok\'lira Starucha w Opuszczonej Kopalni chce, żebyś $godebrał:odebrała; runy Yrkvinn nadzorczyni Syrze.', '', 'Wróć do Lok\'liry Staruchy w Opuszczonej Kopalni na Burzowych Szczytach.', '', '', '', '', 0),
(12843, 'koKR', 'Porwały naszych mężczyzn!', 'Musisz nam pomóc! Byliśmy w trakcie wyprawy w góry, żeby postawić wieżę przekaźnikową, kiedy nas zaatakowano.$B$BWyglądały jak wrykule, tylko miały niebieską skórę pokrytą warstwą szronu... i wszystkie były kobietami! Zabrały wszystkich mężczyzn z wyprawy, a nas, kobiety, puściły wolno. Proszę, $N! Sądzimy, że trzymają ich w Sifreldar, wiosce górującej nad K3.', 'Gretchen Fizzlespark chce, żebyś $gudał:udała; się do Wioski Sifreldar i $guwolnił:uwolniła; 5 goblińskich więźniów.', '', 'Wróć do Gretchen Fizzlespark w K3 na Burzowych Szczytach.', 'Uwolnieni goblińscy więźniowie', '', '', '', 0),
(12844, 'koKR', 'Odzyskiwanie sprzętu', 'Proszę, $N. Kiedy Hyldnir porwały naszych mężczyzn, zabrały też cały nasz sprzęt. Oczywiście ważniejsze jest, żeby odzyskać naszych chłopców, ale jeśli natrafisz na jakiś nasz sprzęt, byłabym bardzo wdzięczna, gdybyś go nam $godniósł:odniosła;.$B$BIch wioskę znajdziesz tuż nad nami, na północy.', 'Gretchen Fizzlespark chce, żebyś $gzdobył:zdobyła; 8 sztuk sprzętu K3 w Wiosce Sifreldar na północ od K3.', '', 'Wróć do Gretchen Fizzlespark w K3 na Burzowych Szczytach.', '', '', '', '', 0),
(12846, 'koKR', 'Nie zostawiamy goblinów', 'Wszyscy nasi chłopcy wrócili... dzięki tobie, $N! No... prawie wszyscy.$B$BWedług pozostałych mój brat Zeev wciąż tam jest. Podobno mają jakąś kopalnię, w której każą pracować więźniom. Wejdź tam i sprawdź, czy uda ci się czegoś dowiedzieć.', 'Znajdź wejście do Opuszczonej Kopalni w północnej części Wioski Sifreldar i poszukaj wskazówek, gdzie może być Zeev Fizzlespark.', '', '', '', '', '', '', 0),
(12851, 'koKR', 'Na niedźwiedzim grzbiecie', 'Próba czeka, kobieto!$b$bCzy masz serce królowej wojowniczek? Czy może serce chlipiącej szwaczki?$b$bJeden smak wojny i poznasz odpowiedź.$b$bMożesz okłamać matkę, siostry, a nawet samą siebie, ale pole bitwy zawsze obnaża prawdziwą naturę.$b$bKiedy się przygotujesz, dosiądź Lodowego Kła i ruszaj do boju. Z jej grzbietu musisz spuścić na naszych wrogów deszcz śmierci.', 'Brijana w Wiosce Brunnhildar chce, żebyś $gdosiadł:dosiadła; Lodowego Kła i $gzestrzelił:zestrzeliła; 7 mroźnych worgów oraz 15 mroźnych olbrzymów w Dolinie Pradawnych Zim.', '', 'Wróć do Brijany w Dolinie Pradawnych Zim na Burzowych Szczytach.', 'Spalone mroźne worgi', 'Spalone mroźne olbrzymy', '', '', 0),
(12853, 'koKR', 'Luksusowy wypoczynek!', 'Hej, $gkolego:koleżanko;!$B$BLubisz emocje i wybuchy?! A kto nie lubi? Znam idealne miejsce dla ciebie. W luksusowym K3 ciągle powstają nowatorskie wynalazki i zupełnie nowe sposoby, żeby coś wysadzić! Brzmi ekscytująco, prawda? Jeśli chcesz być częścią tej zabawy, wpadnij tam jeszcze dziś i porozmawiaj z Jeerem Sparksocketem!$B$BObowiązkowe zastrzeżenie: udział we wspomnianych „emocjach” może wymagać pracy fizycznej.', 'Porozmawiaj z Jeerem Sparksocketem w K3 na Burzowych Szczytach.', '', '', '', '', '', '', 0),
(12854, 'koKR', 'Śladem Branna', 'Od czasu odkrycia dziennika Branna na Wzgórzach Grizli dostaliśmy od niego tylko jedną wiadomość. Do siedziby Ligi Odkrywców w Żelaznej Kuźni trafił tajemniczy liścik, bez żadnej wskazówki, skąd pochodzi. Było w nim tylko tyle, że mamy się spotkać z Brannem w jego obozie i pomóc mu w poszukiwaniach.$B$BZ tego, co mogę wywnioskować, obóz powinien leżeć na północny wschód stąd, za Rzeką Oddechu Bora, u stóp jakichś ruin na Ścieżce Tytanów.', 'Odzyskaj liścik owinięty w jutę z obozu Branna i zanieś go archeologowi Andorinowi w Mroźnej Warowni.', '', 'Wróć do archeologa Andorina w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12855, 'koKR', 'Na tropie sprawcy', 'Ton liściku Branna sugeruje, że chciał razem z nim zakopać coś jeszcze, może jakiś plecak. Na pewno nic więcej nie $gznalazłeś:znalazłaś;?$B$BDobrze, dam ci jednego z tych mroźnych ogarów. Mroźnorodni używają ich do tropienia. Zaprowadź go do zniszczonego obozu i pozwól mu złapać trop Branna.$B$BPowinien przynajmniej zaprowadzić cię tam, gdzie są zaginione rzeczy, a jeśli dopisze nam szczęście – do samego Branna.', 'Użyj obroży mroźnego ogara w Porzuconym Obozie, aby wytropić tego, kto zabrał rzeczy Branna. Kiedy je odzyskasz, użyj urządzenia komunikacyjnego i porozmawiaj z tym, z kim uda ci się połączyć.', '', 'Użyj urządzenia komunikacyjnego i porozmawiaj z tym, z kim uda ci się połączyć.', 'Wytrop złodzieja', '', '', '', 0),
(12856, 'koKR', 'Zimne serce', 'Zginąć honorowo na polu bitwy to chwała dla nas wszystkich. Zostać zamrożoną w bryle lodu i bez końca wyszydzaną – już nie...$b$bPolecisz do miasta mroźnych olbrzymów, Dun Niffelem, na wschód od Doliny Pradawnych Zim, i uwolnisz uwięzioną samicę protosmokowca. Z jej pomocą uwolnisz nasze siostry z lodowych okowów i bezpiecznie przywieziesz trzy z nich do domu.$b$bStrzeż się maczug olbrzymów, siostro, byś sama nie znalazła się wśród uwięzionych.', 'Brijana, tuż na wschód od Wioski Brunnhildar, chce, żebyś $gpoleciał:poleciała; do Dun Niffelem, a następnie $guwolnił:uwolniła; 3 uwięzione protosmokowce i $gocalił:ocaliła; 9 więźniarek z Brunnhildar.', '', 'Wróć do Brijany w Dolinie Pradawnych Zim na Burzowych Szczytach.', 'Ocalone więźniarki z Brunnhildar', 'Uwolnione protosmokowce', '', '', 0),
(12858, 'koKR', 'Kawałki układanki', 'Dzięki Światłości, że ktoś dostał moją wiadomość. Teraz, kiedy jestem bezpieczny przed żelaznymi krasnoludami, muszę cię prosić o pomoc. Wpadłem na trop zwornika Norgannona, który strzeże dostępu do archiwów Ulduaru, ale tytani podzielili go na dwie części i ukryli je.$B$BJedna z nich, skorupa zwornika, znajduje się w Bibliotece Wynalazcy na północnym wybrzeżu, na południe od samego Ulduaru. Najpierw musisz zdobyć fragmenty dysku dostępu od strażników biblioteki.', 'Zbierz 6 fragmentów dysku Wynalazcy i złóż z nich Dysk Wynalazcy.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z archeologiem Andorinem w Mroźnej Warowni, aby dostać nowy.', '', '', '', '', 0),
(12860, 'koKR', 'Wydobywanie danych', 'Ten dysk, który $gzłożyłeś:złożyłaś;... jest pusty! Ten przebiegły Mimir musiał ukryć informacje gdzie indziej. Rozejrzyj się po Bibliotece Wynalazcy – widzisz tam jakieś banki danych?$B$BMożliwe, że właśnie do tego masz użyć dysku. Spróbuj go użyć w pobliżu tych banków danych. Może jest ustawiony tak, żeby pobierać z nich informacje i je przechowywać. Kiedy już spróbujesz, skontaktuj się ze mną znowu i daj znać, co $gznalazłeś:znalazłaś;. Tymczasem ja spróbuję wytropić drugą połowę klucza do archiwum.', 'Użyj Dysku Wynalazcy, aby pobrać 7 porcji ukrytych danych z banków danych.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z archeologiem Andorinem w Mroźnej Warowni, aby dostać nowy.', 'Zebrane ukryte dane', '', '', '', 0),
(12862, 'koKR', 'Gdy wszystko inne zawiedzie', 'No więc... chyba nie uda nam się porządnie zadomowić w tych górach.$B$BUwierz mi, nie poddaję się łatwo... ale między zamarzającymi silnikami, paskudnymi wrykulskimi babami, terytorialnymi niby-smokami i z pół tuzina innych paskudztw, które tu osiadły, to po prostu się nie uda.$B$BAle niech cię to nie zniechęca! To, że my nie możemy się tam zadomowić, nie znaczy, że cię tam nie dostarczymy... bilety w jedną stronę to w gruncie rzeczy prosta sprawa.$B$B<Ricket kiwa głową w stronę pobliskich rakiet.>', 'Porozmawiaj z Ricket, aby skorzystać z napędowego urządzenia dostawczego D16 Ricket i przedostać się dalej w głąb Burzowych Szczytów.', '', '', '', '', '', '', 0),
(12863, 'koKR', 'Wyrazy podziękowania', 'Ach! Dzięki, że $gprzyszedłeś:przyszłaś; tu na górę, $gchłopcze:dziewczyno;.$B$BSądząc po twoich szeroko otwartych oczach i drżących rękach, zgaduję, że jesteś tu $gnowy:nowa;. W takim razie dobrze by było, żebyś $gpoznał:poznała; naszych łaskawych gospodarzy!$B$BMamy trochę zapasowych środków medycznych... prawdę mówiąc, nie spodziewaliśmy się, że będziemy tu mieć tak wygodne warunki. Zanieś tę skrzynię Glorthalowi, o tam, i pomóż im trochę, jeśli możesz. Nie chcemy, żeby pomyśleli, że nie doceniamy ich gościnności.', 'Zanieś skrzynię z zapasami medycznymi Glorthalowi Sztywnobrodemu w Mroźnej Warowni.', '', 'Wróć do Glorthala Sztywnobrodego w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12864, 'koKR', 'Zaginieni zwiadowcy', 'Skoro już tu jesteś, przydałaby mi się pomoc w pewnej sprawie.$B$BKilku naszych zwiadowców mocno spóźnia się z powrotem. Szczyty są surowe... ale ci chłopcy wiedzą, co robią.$B$BIdź na wschód... wzdłuż doliny Oddechu Bora i w okolice Upadku Bora... powinni być gdzieś w tamtym kierunku. Jeśli znajdziesz jakikolwiek ślad któregoś z nich, natychmiast przynieś mi wieści. Mamy w okolicy kilku wrogów – jeśli któryś z nich zaczyna się stawiać, im wcześniej się dowiemy, tym lepiej.', 'Glorthal z Mroźnej Warowni poprosił cię o przeszukanie doliny Oddechu Bora i Upadku Bora w poszukiwaniu śladów zaginionych mroźnorodnych zwiadowców.', 'Odnajdź zaginionego zwiadowcę', 'Wróć do Glorthala Sztywnobrodego w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12865, 'koKR', 'Wierni towarzysze', 'Świeża krew! Miło cię poznać! Mam trochę roboty, jeśli masz trochę czasu.$B$BNa wschodzie leżą Stepy Podnóża... dość surowa kraina, ale pasie się tam całkiem spore stado nosorożców. Nasze ptaki uwielbiają mięso nosorożców, ale polowanie zawsze jest dla nich dość niebezpieczne, bo w okolicy gnieżdżą się protosmokowce.$B$BJeśli masz ochotę, wybierz się tam, zdobądź trochę mięsa nosorożca, przynieś je na szczyty nad nami i nakarm nim kilka gnieżdżących się tam orłów.', 'Fjorlin Mroźnobrwy z Mroźnej Warowni chce, żebyś $gzdobył:zdobyła; 8 płatów świeżego mięsa lodowego nosorożca i $gnakarmił:nakarmiła; nim orły z Burzowego Grzbietu nad osadą.', '', 'Wróć do Fjorlina Mroźnobrwego w Mroźnej Warowni na Burzowych Szczytach.', 'Nakarmione orły z Burzowego Grzbietu', '', '', '', 0),
(12866, 'koKR', 'Powstrzymanie napastników', 'Przeklęte harpie. Już nie pamiętam, ile razy dawaliśmy tej bandzie takie baty, że się uspokajała... i po każdej potyczce przez jakiś czas jest cicho. Tym razem myślałem, że może wreszcie do nich dotarło.$B$BNajwyraźniej nie.$B$BPamięć mają może krótką, ale jeśli dość się je przetrzebi, trzymają się z daleka. Idź do dolin na północy i wschodzie i wybij spory kawał tego stada, dobrze?', 'Glorthal Sztywnobrody z Mroźnej Warowni chce, żebyś $gzabił:zabiła; 8 skrzekaczek Mroźnego Pióra i 8 wiedźm Mroźnego Pióra.', '', 'Wróć do Glorthala Sztywnobrodego w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12867, 'koKR', 'Złodziejki piskląt', 'Jeszcze kilka tygodni temu, gdy spojrzało się w górę, widać było dziesiątki tych pięknych orłów szybujących po niebie. Teraz ledwie kilka, jeśli w ogóle. Niemal cały czas siedzą teraz przy gniazdach, bo harpie kradną im jaja.$B$BWygląda na to, że harpie zasmakowały w orlim mięsie... te chore kreatury pilnują jaj tylko tak długo, aż będą mogły się napchać pisklętami. Idź do dolin na północy albo wschodzie i znajdź te jaja... przynieś je tutaj, a ja odniosę je do gniazd.', 'Fjorlin Mroźnobrwy z Mroźnej Warowni chce, żebyś $gprzyniósł:przyniosła; 15 jaj orłów z Burzowego Grzbietu.', '', 'Wróć do Fjorlina Mroźnobrwego w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12868, 'koKR', 'Sirana Lodowy Wrzask', 'Wygląda na to, że ta Sirana Lodowy Wrzask to ta, która podjudza harpie do większej agresji. Jeśli ją zabijemy, podejrzewam, że ich ataki niedługo potem ustaną.$B$BJeden z naszych burzowych jeźdźców twierdzi, że widział, jak krąży wokół szczytu tuż na północny zachód stąd. Znajdź tę jędzę i ją zabij. Załatwmy to.', 'Glorthal Sztywnobrody z Mroźnej Warowni chce, żebyś $gzabił:zabiła; Siranę Lodowy Wrzask.', '', 'Wróć do Glorthala Sztywnobrodego w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12869, 'koKR', 'Za daleko', '$GByłeś:Byłaś; tam przy Lokenie, prawda? Żelazne krasnoludy pojmały Veranus, Matkę Lęgu protosmokowców. Smokom ani trochę się to nie podoba... zrobiły się bardzo agresywne.$B$BWdarły się na terytorium orłów z Burzowego Grzbietu i orły toczą z nimi wojnę na całego. Czas się odwdzięczyć. Lecimy na Stepy Podnóża, żeby je tam wyrżnąć.$B$BKról Burzowe Serce zostawił mi ten młot – zrób z niego dobry użytek i dopilnuj, żebym go odzyskał.', 'Fjorlin Mroźnobrwy z Mroźnej Warowni chce, żebyś $gpoleciał:poleciała; na orle z Burzowego Grzbietu i $gzabił:zabiła; 16 żmijów z Burzowych Szczytów na Stepach Podnóża.', '', 'Wróć do Fjorlina Mroźnobrwego w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12870, 'koKR', 'Pradawne relikty', 'A witajże!$B$BZanim ruszysz na swoje wielkie zadania i przygody, mógłbym cię prosić o malutką przysługę, $gchłopcze:dziewczyno;?$B$BTe góry są pełne cennych reliktów i świecidełek... to miejsce to spełnienie marzeń dla Ligi. Byłbym bardzo zobowiązany, gdybyś mi $gprzynosił:przynosiła; wszelkie takie skarby, na które się natkniesz. W zamian możesz się nawet napić mojego piwa! Wierz mi, $gchłopcze:dziewczyno;, to świetny interes!', 'Przynieś 10 reliktów Ulduaru Rorkowi Szpicbródce w Mroźnej Warowni.', '', 'Wróć do Rorka Szpicbródki w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12871, 'koKR', 'Pomoc od Ligi Odkrywców', 'Ciekawe. Nie widzę na skorupie żadnych mechanizmów zamykających. To mi podpowiada, że do złożenia zwornika może być potrzebne coś więcej niż tylko znalezienie drugiej części.$B$BZanieś skorupę przywódcy wyprawy, Lagnusowi, do Mroźnej Warowni. Kiedy już ochłonie z zachwytu, powinien na podstawie skorupy wywnioskować, jak wygląda rdzeń, a może uda im się nakłonić mroźnorodnych do pomocy w jego poszukiwaniach.$B$BJa spróbuję się dowiedzieć, jak połączyć obie części. Spotkamy się, kiedy obaj zrobimy jakieś postępy.', 'Zanieś Skorupę Norgannona Lagnusowi w Mroźnej Warowni.', '', 'Wróć do Lagnusa w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12872, 'koKR', 'Skorupa Norgannona', 'Ładowanie dysku Wynalazcy.$B$BŁadowanie dysku zakończone.$B$BPrzygotowywanie protokołu awaryjnego gamma.$B$BProtokół awaryjny załadowany. Użyj naładowanego dysku, aby aktywować strażnika Skorupy Norgannona, archiwistę Mechatona. Archiwista wyda skorupę po zweryfikowaniu twojej tożsamości.$B$BŻyczymy przyjemnego tysiąclecia.', 'Odbierz Skorupę Norgannona archiwiście Mechatonowi.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z archeologiem Andorinem w Mroźnej Warowni, aby dostać nowy.', '', '', '', '', 0),
(12873, 'koKR', 'Król mroźnorodnych', 'Zdecydowanie... dokładnie widzę, jak musi wyglądać rdzeń. Jeśli któryś z mroźnorodnych go widział, na pewno rozpozna go po opisie.$B$BNie ma czasu do stracenia, przejdźmy od razu do rzeczy. Idź do króla Burzowe Serce i poproś go o pomoc... na pewno zna kogoś, kto pomoże nam znaleźć rdzeń. I bądź przy tym $guprzejmy:uprzejma;, dobrze? Tutaj bardzo go szanują.', 'Porozmawiaj z Yorgiem Burzowe Serce w Mroźnej Warowni.', '', '', '', '', '', '', 0),
(12874, 'koKR', 'Żar Mroźnorodnych', 'Chętnie użyczę schronienia i domu podróżnym w potrzebie, ale nie palę się zbytnio, żeby wciągać mój lud w wasze sprawy.$B$BPowiem ci tak... mój lud to wojownicy, prości i prawi. W dniu, w którym mroźnorodny staje się mężczyzną, musi się wykazać w boju. Musi nam pokazać, że nie pozwoli, by wzrost go ograniczał.$B$BPokaż mi, żeś $grównie silny i zawzięty:równie silna i zawzięta; jak któryś z moich ludzi, a każę im użyczyć ci ucha albo ostrza. Pomów z Fjorlinem przy tamtym urwisku na południu, a on podda cię próbie.', 'Yorg Burzowe Serce z Mroźnej Warowni poprosił, żebyś $gporozmawiał:porozmawiała; z Fjorlinem Mroźnobrwym, aby zdobyć wierzchowca i stawić czoła próbie.', '', 'Wróć do Yorga Burzowe Serce w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12875, 'koKR', 'Doświadczony przewodnik', 'Nie wiem, gdzie się ukrywa ten rdzeń, ale to już wiesz. Powiedziałem jednak, że pomogę, i tak też zrobię.$B$BJest taki pustelnik, Drom Mroźny Chwyt, który mieszka w jaskini na północ stąd... w dole, w dolinie. My sami trochę oddaliliśmy się od tytanów, bo tak niewielu ich zostało, ale Drom jest wierny dawnym zwyczajom... pilnuje ich najcenniejszych miejsc i często rozmawia ze strażnikiem Creteusem.$B$BNa pewno znajdziesz go w głębi jaskini... powiedz mu, że to ja cię przysłałem, a pomoże ci.', 'Odnajdź Droma Mroźny Chwyt.', '', '', '', '', '', '', 0),
(12876, 'koKR', 'Nieproszeni goście', 'Nasi zwiadowcy wypatrzyli żelazne krasnoludy w dolinie na północ stąd. Słyszałem, jak król Burzowe Serce wysyła cię do Droma, i przyznaję, że trochę się o niego martwię.$B$BJeśli natkniesz się tam na jakieś żelazne krasnoludy, rozpraw się z nimi szybko i twardo, dobra? Nie sądzę, żeby już wiedziały, gdzie dokładnie jesteśmy albo jak się tu dostać, i wolałbym, żeby tak zostało.', 'Fjorlin Mroźnobrwy z Mroźnej Warowni chce, żebyś $gzabił:zabiła; 10 burzowiernych intruzów.', '', 'Wróć do Fjorlina Mroźnobrwego w Mroźnej Warowni na Burzowych Szczytach.', 'Zabici burzowierni intruzi', '', '', '', 0),
(12877, 'koKR', 'Samotny wartownik', 'Nigdy nie znalazłem rdzenia... ale często rozmawiałem ze strażnikiem Creteusem, a to, co przemilcza, zdradza go. Znajdziesz Creteusa za górami na wschodzie, na Stepach Podnóża, gdzie pilnuje Machiny Twórców. Rdzeń może być właśnie tam, ale musisz zyskać przychylność Creteusa.$B$BŻelazne krasnoludy były tu i czegoś szukały... może właśnie rdzenia. Zabrały mój pierścień. Znajdź ich przywódcę, odzyskaj pierścień i pokaż go Creteusowi, żeby wiedział, że to ja cię przysłałem.', 'Odzyskaj Sygnet Mroźnego Chwytu od dozorcy żelaznych krasnoludów, a następnie zanieś go Creteusowi na Stepy Podnóża.', '', 'Wróć do Creteusa na Stepach Podnóża na Burzowych Szczytach.', '', '', '', '', 0),
(12878, 'koKR', 'Ukryty relikt', 'Podczas twojej nieobecności miałem zaszczyt pertraktować z krasnoludem Brannem Miedziobrodym. Krasnolud ten wyjawił, w jakim celu poszukuje zwornika, i jestem przekonany, że jego zamiary są należyte... Sądzę, że ten krasnolud może być istotą, dla której zwornik stworzono.$B$BRdzeń Norgannona znajduje się w Lodowatym Grobowcu na południowym wschodzie. Jego strażnicy to pradawne istoty z lodu i nie przyjmą twojej obecności życzliwie. Pokonaj tych strażników i odbierz zwornik z moim błogosławieństwem, $N.', 'Creteus ze Stepów Podnóża przekazał ci informacje, dzięki którym odnajdziesz Rdzeń Norgannona.', '', '', '', '', '', '', 0),
(12879, 'koKR', 'Furia króla mroźnorodnych', '<Gdy wyjmujesz rdzeń ze skrzyni, słyszysz dudnienie ciężkich kroków pędzących ku tobie korytarzem. W oddali słychać przytłumione odgłosy walki.>', 'Zanieś Rdzeń Norgannona z powrotem Creteusowi na Stepy Podnóża.', '', 'Wróć do Creteusa na Stepach Podnóża na Burzowych Szczytach.', '', '', '', '', 0),
(12880, 'koKR', 'Mistrz odkrywców', 'Do połączenia zwornika potrzebne będzie Spojenie Norgannona – urządzenie znajdujące się w Machinie Twórców, wielkim zagłębieniu obok nas. Brann powinien już tam być z drugą połową zwornika. Pouczyłem go, jak używać urządzenia. Oczekuje twojego przybycia.$B$BZrobię, co w mojej mocy, by zająć czymś żelazne krasnoludy, ale nie jestem pewien, czy długo zdołam je powstrzymać. Król Burzowe Serce wkrótce wraca z częścią swoich ludzi, by bronić Mroźnej Warowni. Proszę, pospiesz się, $N.', 'Zanieś Rdzeń Norgannona Brannowi Miedziobrodemu do Machiny Twórców.', '', 'Wróć do Branna Miedziobrodego przy Machinie Twórców na Burzowych Szczytach.', '', '', '', '', 0),
(12881, 'koKR', 'Bracia Miedziobrodzi', '', '', '', '', '', '', '', '', 0),
(12882, 'koKR', 'Pradawne relikty', 'Witaj w górach.$B$BMam prostą prośbę, zanim wyruszysz na jakąkolwiek wielką wyprawę, którą sobie $gzaplanowałeś:zaplanowałaś;. Po tych górach rozsiane są relikty i skarby starożytnego Ulduaru. Większość z nich jest zapewne w posiadaniu różnych rozumnych ras.$B$BPrzynoś mi wszystkie, które znajdziesz, a odpowiednio cię wynagrodzę. Może nawet pozwolę ci skosztować moich licznych mocnych piw.', 'Przynieś 10 reliktów Ulduaru Olutowi Piwnemu Brzuchowi w Miejscu Katastrofy Grom\'arsha.', '', 'Wróć do Oluta Piwnego Brzucha w Miejscu Katastrofy Grom\'arsha na Burzowych Szczytach.', '', '', '', '', 0),
(12885, 'koKR', 'Wygnańcy z Ulduaru', 'Burzowe Szczyty to fascynujące miejsce, ale jest tu znacznie więcej niż ruiny tytanów. Ludom, które tu żyją, grozi straszliwe niebezpieczeństwo ze strony Lokena i jego sług.$B$BWysłał swoje ulubione sługi, żelazne krasnoludy, na brutalną kampanię przeciwko wszystkim istotom z kamienia. Wypędził ziemnych z Ulduaru, zmuszając ich do szukania schronienia w Schronieniu Bouldercraga, na zboczu góry na zachód od Biblioteki Wynalazcy. Bouldercrag i jego bracia są tam oblegani przez żelazne krasnoludy. Odnajdź ich i pomóż im, $N.', 'Porozmawiaj z Bouldercragiem Kształtującym Skały w Schronieniu Bouldercraga.', '', '', '', '', '', '', 0),
(12886, 'koKR', 'Drakkensryd', 'To już to. $GPrzeszedłeś:Przeszłaś; wszystkie próby Hyldsmeet... wszystkie z wyjątkiem jednej. $GWzniosłeś:Wzniosłaś; się ponad najlepsze i najbardziej zażarte z naszych sióstr.$B$BNadszedł czas ostatniej próby. Drakkensryd – prawdziwy sprawdzian wartości i wojowniczego ducha Hyldnir. Będziesz ty, twój smok, harpun na łańcuchu i dwadzieścia twoich sióstr walczących o prym.$B$BNie okazuj litości. Nikt jej nie oczekuje.', 'Użyj harpuna Hyldnir, aby pokonać 10 smoczych jeźdźczyń z Hyldsmeet przy Świątyni Burz. Użyj harpuna Hyldnir na ozdobie kolumny, aby opuścić Drakkensryd, a po zwycięstwie porozmawiaj z Thorimem.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', 'Pokonane smocze jeźdźczynie z Hyldsmeet', '', '', '', 0),
(12888, 'koKR', 'ZŁOM-E', 'Ta karta pozwala użytkownikowi uzyskać dostęp do panelu sterowania złomobota oznaczonego jako ZŁOM-E, aby przeprowadzić konserwację i przeprogramować jego dyrektywy.$B$BZŁOM-E jest najwyraźniej przydzielony do wnętrza budynku w Bibliotece Wynalazcy. Karta wyświetla listę uszkodzonych podzespołów i zawodzących układów robota. Z odpowiednimi częściami można przywrócić go do sprawności.', 'Zanieś kartę dostępu ZŁOM-E wraz z 4 garściami kobaltowych śrub i 5 przeładowanymi kondensatorami do ZŁOM-E w Bibliotece Wynalazcy.', '', 'Wróć do ZŁOM-E w Bibliotece Wynalazcy na Burzowych Szczytach.', '', '', '', '', 0),
(12889, 'koKR', 'Konsola prototypu', 'Oznaczenie: ZŁOM-E.$B$BDyrektywa: konserwacja konsol i baz danych Biblioteki Wynalazcy podczas nieobecności Opiekuna Mimira.$B$BCzas od ostatniego cyklu konserwacji: 489 dni.$B$BStan danych schematów: nieznany.$B$BBieżące zadania: naprawa konsoli prototypu.', 'Użyj konsoli prototypu w Bibliotece Wynalazcy.', '', '', '', '', '', '', 0),
(12890, 'koKR', 'Gdyby rozmiar miał znaczenie...', '', '', '', '', '', '', '', '', 0),
(12895, 'koKR', 'Zaginiony Miedziobrody', 'Przed wyruszeniem dostałem akta, które zwiadowca Vor\'takh zebrał o tym Brannie Miedziobrodym. Z wpisów w jego dzienniku i znalezisk na Wzgórzach Grizli nie ma wątpliwości, że Brann zmierzał na Burzowe Szczyty. Zanim się rozbiliśmy, dostrzegłem obozowisko na południe stąd, za Stepami Podnóża, z widokiem na zamarzniętą Rzekę Oddechu Bora.$B$BJeśli Branna tam nie ma, przeszukaj obóz i okolicę w poszukiwaniu jakichkolwiek wskazówek, dokąd mógł się podziać ten przeklęty krasnolud. Przynieś wszystko, co znajdziesz.', 'Odzyskaj liścik owinięty w jutę z obozu Branna i zanieś go Boktarowi Krwawej Furii w Miejscu Katastrofy Grom\'arsha.', '', 'Wróć do Boktara Krwawej Furii w Miejscu Katastrofy Grom\'arsha na Burzowych Szczytach.', '', '', '', '', 0),
(12900, 'koKR', 'Uprząż', 'A więc chcesz jeździć? Cóż, skoro zaszłaś tak daleko, ktoś musi uważać, że masz szansę w Hyldsmeet.$B$BNajpierw najważniejsze: trzeba ci zrobić uprząż.$B$BNa urwiskach na południu znajdziesz rozproszone grupy yeti. Ich skóry są wytrzymałe i mają akurat odpowiednią grubość. Przynieś mi kilka, a zaczniemy twoją drogę jeźdźczyni niedźwiedzi.', 'Astrid Bjornrittar z Wioski Brunnhildar chce, żebyś $gzdobył:zdobyła; 3 skóry yeti Lodowej Grzywy.', '', 'Wróć do Astrid Bjornrittar w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12905, 'koKR', 'Mildred Okrutna', 'Umowa stoi, $N. Pomożesz mi uwolnić się z tych łańcuchów, a ja pomogę ci odnaleźć twojego małego zielonego przyjaciela.$B$BHyldnir, która zarządza tą kopalnią, zwie się Mildred Okrutna – i nie bez powodu.$B$BPowiedz jej, że przysłano cię do pomocy w kopalniach. Rób wszystko, o co poprosi, aż zaufa ci na tyle, by powierzyć ci klucze do moich kajdan.', 'Porozmawiaj z Mildred Okrutną w Opuszczonej Kopalni.', '', '', '', '', '', '', 0),
(12906, 'koKR', 'Dyscyplina', 'Zacznijmy od czegoś prostego. Wrykulscy mężczyźni, którzy pracują dla nas w kopalniach, robią to wbrew swojej woli... wyłącznie ze strachu przed naszymi ostrzami.$B$BCo jakiś czas któryś z nich traci motywację. Znajdź nieskorych do współpracy wrykulów i przywołaj ich do porządku.$B$BWeź ten pręt dyscyplinujący. Masz zadawać ból, nie śmierć. No, przynajmniej przez większość czasu.', 'Mildred Okrutna z Opuszczonej Kopalni chce, żebyś $gużył:użyła; pręta dyscyplinującego na 6 wyczerpanych wrykulach.', '', 'Wróć do Mildred Okrutnej w Opuszczonej Kopalni na Burzowych Szczytach.', 'Zdyscyplinowani wyczerpani wrykule', '', '', '', 0),
(12907, 'koKR', 'Trzeba dać przykład', 'Każda akcja wywołuje przeciwną reakcję, siostro. W przypadku naszego nacisku na mężczyzn oznacza to świeżo rozpuszczone plotki o buncie.$B$BTa brodata świnia, która podburza motłoch, nazywa się Garhal. Skończ z nim... i dopilnuj, żeby inni mężczyźni widzieli jego zgon. Muszą się nauczyć, że niesubordynacja nie będzie tolerowana.', 'Mildred Okrutna z Opuszczonej Kopalni chce, żebyś $gzabił:zabiła; Garhala.', '', 'Wróć do Mildred Okrutnej w Opuszczonej Kopalni na Burzowych Szczytach.', '', '', '', '', 0),
(12908, 'koKR', 'Pewna więźniarka', 'Jesteś bezlitosna. Świetnie sobie poradzisz w tych stronach.$B$BMam do ciebie kolejną prośbę. Jest tu wrykulska więźniarka, która przysparza więcej kłopotów, niż się spodziewałam.$B$BMiała czelność domagać się prawa do udziału w Hyldsmeet, naszych świętych zawodach siły i sprawności bojowej.$B$BOto klucz do jej kajdan. Zrób to możliwie bezboleśnie. W końcu to kobieta, nawet jeśli nie jedna z nas.', 'Zanieś klucz Mildred Lok\'lirze Starusze w Opuszczonej Kopalni.', '', 'Wróć do Lok\'liry Staruchy na Tarasie Śnieżnej Ślepoty na Burzowych Szczytach.', '', '', '', '', 0),
(12909, 'koKR', 'Nos wie najlepiej', 'Żeby wytropić Branna, potrzebujemy stworzenia z dobrym węchem i talentem do tropienia. Na zeppelinie nie było żadnych psów, ale chyba mam coś w zamian.$B$BPo katastrofie wysłałem Khaliisi wschodnim zboczem góry, żeby zaczęła polować na jedzenie. Jej kotka, Odmrożenie, doskonale tropi zwierzynę na śniegu. Powiedz jej, że będzie musiała rozstać się ze swoją towarzyszką, przynajmniej na jakiś czas. Może polować sama, a my nie mamy innego sposobu, żeby dogonić Branna Miedziobrodego.', 'Porozmawiaj z Khaliisi u stóp góry na wschód od Miejsca Katastrofy Grom\'arsha.', '', '', '', '', '', '', 0),
(12910, 'koKR', 'Na tropie sprawcy', 'Tym razem niech Boktarowi będzie, ale oczekuję, że mi to wynagrodzi. Nie patrz tak na mnie. Boktar może i dowodzi, ale nikt nie mówi łowcy, co ma robić.$B$B„Schowaj tę bestię” – mówi. „Niech przestanie warczeć”.$B$BA tu nagle zmienia zdanie, kiedy mu to pasuje. Następnym razem, jak zacznie narzekać, Odmrożenie trochę go podgryzie. Nie martw się, świetnie wytropi twoją zdobycz. Kiedy już namierzy cel, $gsam:sama; musisz sobie radzić z żelaznymi krasnoludami, Brannem czy czymkolwiek, co znajdziesz.', 'Dosiądź Odmrożenia i podążaj nią do źródła zapachu z liściku Branna. Następnie odzyskaj komunikator Branna i użyj go, aby nawiązać kontakt z Brannem Miedziobrodym.', '', 'Użyj komunikatora Branna, aby porozmawiać z Brannem Miedziobrodym.', 'Wytrop źródło zapachu', '', '', '', 0),
(12913, 'koKR', 'Mów po orczemu, człowieku!', '<Brann zaczyna dziko gestykulować i paplać w swoim ojczystym języku.>$B$BRuk MogOth red a mogoth ta eft Thros-garE Haldir.$B$BKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.$B$BA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.$B$B Gar Ruk dagUm loch angor-magi ta har ruk!$B$B<Po kilku chwilach dociera do ciebie, że ta rozmowa do niczego nie prowadzi. Może szaman Moteha Zrodzony z Wiatru z Miejsca Katastrofy Grom\'arsha będzie wiedział, co robić.>', 'Porozmawiaj z Motehą Zrodzonym z Wiatru w Miejscu Katastrofy Grom\'arsha.', '', '', '', '', '', '', 0),
(12915, 'koKR', 'Naprawianie relacji', 'Jeśli mam nadzieję wydrzeć bratu władzę nad Świątynią Twórców, muszę pojednać się z dawnymi sojusznikami.$b$bByć może eliminując wspólnego wroga, zrobimy choć krok ku odnowieniu mojej przyjaźni z mroźnymi olbrzymami.$b$bFjorn oblega Dun Niffelem z olbrzymami z żelaza. Musisz go pokonać przy Kowadle Fjorna, daleko na wschód stąd, i osłabić jego siły na tyle, by Synowie Hodira zwyciężyli.$b$bWeź ten amulet, $n. Użyj go, by wezwać moich ziemnych na pomoc.', 'Thorim w Świątyni Burz chce, żebyś $gzabił:zabiła; Fjorna i 5 burzowiernych żelaznych olbrzymów przy Kowadle Fjorna, na wschód od Dun Niffelem.$b$bUżycie Amuletu ziemi Thorima przywoła jego ziemnych, którzy będą walczyć u twego boku. Amulet wymaga granitowego głazu z pobliskiego Kowadła Fjorna.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', 'Fjorn zabity', 'Zabite burzowierne żelazne olbrzymy', '', '', 0),
(12917, 'koKR', 'Rozmowa głosem wiatru', 'Chyba nie powinniśmy byli się spodziewać, że tak łatwo znajdziemy Branna, nie przy naszym szczęściu. Jeśli zrozumiemy, co mówi Brann, zdołasz go przekonać, żeby zdradził, gdzie jest.$B$BMoc wiatru jest w tych górach silna i może okazać się dla nas wielkim dobrodziejstwem. Biegły szaman słyszy we wietrze brzmienie wszystkich języków świata.$B$BNa północnym zachodzie, na Równinach Zasp, znajdziesz istoty zrodzone z wiatru – burzowych jeźdźców. Pochwyć ich głosy i przynieś je mnie.', 'Przynieś 5 głosów wiatru Motesze Zrodzonemu z Wiatru w Miejscu Katastrofy Grom\'arsha.', '', 'Wróć do Motehy Zrodzonego z Wiatru w Miejscu Katastrofy Grom\'arsha na Burzowych Szczytach.', '', '', '', '', 0),
(12920, 'koKR', 'Doganiając Branna', 'Na co czekasz? Dzięki Motesze bariera językowa została przełamana. Skontaktuj się z Brannem Miedziobrodym i dowiedz się wszystkiego, co się da, o tym, gdzie się ukrywa i za czym się ugania.$B$BMoże jeszcze uda się coś uratować z tej katastrofy.', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym i z nim porozmawiać, a następnie porozmawiaj z Boktarem Krwawą Furią w Miejscu Katastrofy Grom\'arsha.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z Motehą Zrodzonym z Wiatru w Miejscu Katastrofy Grom\'arsha.', '', 'Wróć do Boktara Krwawej Furii w Miejscu Katastrofy Grom\'arsha na Burzowych Szczytach.', 'Porozmawiaj z Brannem', '', '', '', 0),
(12921, 'koKR', 'Zmiana otoczenia', 'Doskonale. We wschodnim krańcu kopalni jest wyjście prowadzące do Wioski Brunnhildar. Idź nim, a spotkamy się na miejscu.$B$BNie mogą nas widzieć razem, żeby nikt nie podejrzewał, że mi $gpomogłeś:pomogłaś;. Zmienię swój wygląd za pomocą magii. Nie martw się, $N – w mig znajdziemy twojego przyjaciela.', 'Spotkaj się ponownie z Lok\'lirą Staruchą w Wiosce Brunnhildar.', '', '', '', '', '', '', 0),
(12922, 'koKR', 'Ogień oczyszczający', 'Pod porowatą powierzchnią ta bryła metalu lśni tajemniczym blaskiem.$b$bCzujesz, że rozsądnie byłoby wypalić żużel przy Kowadle Fjorna.$b$bGdy zastanawiasz się, gdzie na tym zamarzniętym pustkowiu znaleźć coś dość gorącego do tego zadania, drogę przecina ci ognista zjawa...$B', 'Musisz zebrać 10 wściekłych iskier od kipiących zjaw nad Jeziorem Mroźnego Pola, a następnie użyć kowadła przy Kowadle Fjorna.', '', 'Wróć do Kowadła Fjorna w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(12924, 'koKR', 'Wykuwanie przymierza', '<Thorim po raz pierwszy od waszego spotkania się uśmiecha.>$b$bTo wszystko zaczyna trącić ręką przeznaczenia, $N.$b$bTo, co $godkryłeś:odkryłaś;, to resztki mojej zbroi, dawno temu porzuconej w przypływie żalu i wystawionej na pastwę żywiołów. Tylko synowie Hodira są w stanie przekuć ją na nowo, bo to oni ją niegdyś stworzyli.$b$bByć może $gzrobiłeś:zrobiłaś; dość, by złagodzić ich nienawiść do mnie. Odszukaj ich króla, Jokkuma, jeśli jeszcze oddycha.$b$bZyskaj jego przychylność i błagaj go o pomoc.', 'Masz udać się do Dun Niffelem i poprosić króla Jokkuma o zgodę na przekucie zbroi Thorima. Po wykonaniu zadania Jokkuma porozmawiaj z Njormeldem w Dun Niffelem.', '', 'Wróć do Njormelda w Dun Niffelem na Burzowych Szczytach.', '', 'Kowadło Fjorna dostarczone do Dun Niffelem', '', '', 0),
(12925, 'koKR', 'Wynaturzenia', 'Król Lisz trzykrotnie przysyłał do nas posłów. Wszystkich trzech natychmiast poćwiartowano.$B$BNasze siostry w Valkyrionie nie były tak oddane naszym tradycjom i przyjęły zaloty Plagi. Teraz, zamiast chwytać smoki na wolności, wychowują je z zarazy i plugastwa, w którym tarza się Plaga.$B$BZabierz olej mrozu, który noszą przy sobie Hyldnir z Valkyrionu, i zamroź nim wszystkie zarażone jaja, jakie znajdziesz. Plotki mówią o cuchnącej sadzawce zarazy, w której trzymane są jaja.', 'Thyra Kvinnshal z Wioski Brunnhildar chce, żebyś $gudał:udała; się do Valkyrionu i $gzdobył:zdobyła; fiolki oleju mrozu od kandydatek z Valkyrionu. Użyj fiolek oleju mrozu, aby zniszczyć 30 zarażonych jaj protosmokowców.', '', 'Wróć do Thyry Kvinnshal w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12926, 'koKR', 'Kawałki układanki', 'Widzieliśmy, jak żelazne krasnoludy i ich konstrukty toczą wojnę z istotami z kamienia, które Brann nazywa ziemnymi, oraz z ich sprzymierzeńcami olbrzymami. Skontaktuj się z nim i pomóż mu, jak tylko możesz, i pamiętaj, że wszystko, czego się dowiemy z jego poszukiwań, może nam pomóc w walce z żelaznymi krasnoludami i ich panem.', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym i dowiedzieć się, co robić dalej.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z Motehą Zrodzonym z Wiatru w Miejscu Katastrofy Grom\'arsha, aby dostać nowy.', '', '', '', '', 0),
(12927, 'koKR', 'Wydobywanie danych', 'Ten dysk, który $gzłożyłeś:złożyłaś;... jest pusty! Opiekun Mimir, majsterkowicz, który zbudował tę bibliotekę, musiał ukryć informacje gdzie indziej. Rozejrzyj się po Bibliotece Wynalazcy – widzisz tam jakieś banki danych?$B$BMożliwe, że właśnie do tego służy dysk. Spróbuj go użyć w pobliżu tych banków danych. Może jest ustawiony tak, żeby pobierać z nich informacje i je przechowywać. Kiedy już spróbujesz, skontaktuj się ze mną znowu i daj znać, co $gznalazłeś:znalazłaś;. Tymczasem ja spróbuję wytropić drugą połowę klucza do archiwum.', 'Użyj Dysku Wynalazcy, aby pobrać 7 porcji ukrytych danych z banków danych.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z Motehą Zrodzonym z Wiatru w Miejscu Katastrofy Grom\'arsha, aby dostać nowy.', 'Zebrane ukryte dane', '', '', '', 0),
(12928, 'koKR', 'Skorupa Norgannona', 'Ładowanie dysku Wynalazcy.$B$BŁadowanie dysku zakończone.$B$BPrzygotowywanie protokołu awaryjnego gamma.$B$BProtokół awaryjny załadowany. Użyj naładowanego dysku, aby aktywować strażnika Skorupy Norgannona, archiwistę Mechatona. Archiwista wyda skorupę po zweryfikowaniu twojej tożsamości.$B$BŻyczymy przyjemnego tysiąclecia.', 'Odbierz Skorupę Norgannona archiwiście Mechatonowi.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z Motehą Zrodzonym z Wiatru w Miejscu Katastrofy Grom\'arsha, aby dostać nowy.', '', '', '', '', 0),
(12929, 'koKR', 'Ziemni z Ulduaru', 'Ziemni, którzy niegdyś zamieszkiwali, budowali i utrzymywali Ulduar, zostali wypędzeni ze swojego domu, gdy Loken przejął miasto. Od tamtej pory jego zwolennicy, żelazne krasnoludy, bezustannie atakują wygnańców.$B$BSchronili się w starej budowli tytanów, którą nazywają teraz Schronieniem Bouldercraga, na zboczu góry na zachód od Biblioteki Wynalazcy. Bouldercrag i jego bracia walczą, by żelaźni nie zajęli ich przystani, ale długo nie utrzymają pozycji. Odnajdź ich i pomóż im, $N.', 'Porozmawiaj z Bouldercragiem Kształtującym Skały w Schronieniu Bouldercraga.', '', '', '', '', '', '', 0),
(12930, 'koKR', 'Rzadka ziemia', 'Wydaje się, że tak dawno temu te młoty kuły i ciosały kamień, a nie żelazo. Po wygnaniu z Ulduaru najsłabsi z nas zginęli, a najsilniejsi z naszych rzemieślników odrodzili się jako wojownicy.$B$BA gdy żelaźni spychają nas coraz dalej, nawet najsilniejszym zaczyna brakować sił.$B$BNiewiele możemy zrobić dla rannych, chyba że mamy zapas zaczarowanej ziemi. Wydobywaliśmy ją ze złóż na stromym urwisku na północnym zachodzie, ale nieustanna walka nie pozwala nam uzupełnić zapasów. Pomożesz?', 'Użyj kilofa górniczego ziemnych, aby wydobyć 7 grud zaczarowanej ziemi. Zanieś ziemię i 5 mroźnych tkanin Bouldercragowi Kształtującemu Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', '', '', '', '', 0),
(12931, 'koKR', 'Kontratak', 'Obrońcy schronienia robią, co mogą, by osłabić ataki żelaznych krasnoludów, ale piędź po piędzi tracimy teren. Moi ludzie są wytrzymali, ale nie niestrudzeni. Bez posiłków to tylko kwestia czasu, aż nas zmiotą.$B$BCzy użyczysz swoich umiejętności do obrony schronienia? To bardzo podniosłoby morale obrońców i dało im – i mnie – nadzieję na kontratak.$B$BZabijaj wszystkich burzowiernych i ich twory, jakie napotkasz przed schronieniem.', 'Bouldercrag Kształtujący Skały chce, żebyś $gzabił:zabiła; 10 burzowiernych napastników i $gwrócił:wróciła; do niego do Schronienia Bouldercraga. Możesz zabijać burzowiernych najeźdźców lub burzowiernych łupieżców.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Zabici burzowierni napastnicy', '', '', '', 0),
(12937, 'koKR', 'Ulga dla poległych', 'Obrońcy schronienia walczą dzielnie, ale nie nadążają za żelazną nawałą.$B$BZ ziemi, którą $gzebrałeś:zebrałaś;, mogę zrobić opatrunki, które pomogą zaleczyć rany niektórych poległych. Im więcej obrońców zdołamy opatrzyć, tym dłużej się tam utrzymamy.$B$BWeź te okłady i użyj ich, by uleczyć rany poległych obrońców przed schronieniem. Przywróć do walki tylu, ilu się da, $N. Każda ofiara to o jedna za dużo.', 'Użyj tellurycznego okładu, aby uleczyć 8 poległych ziemnych obrońców, a następnie wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Uleczeni polegli ziemni obrońcy', '', '', '', 0),
(12942, 'koKR', 'Precz z ich czarnymi skrzydłami', 'Zdrajczynie. My, Hyldnir, nie darzymy ich miłością.$B$BMieszkanki Valkyrionu zbyt długo pozostawały bezkarne. Podczas gdy my pozostałyśmy wierne Thorimowi, one stały się pieskami Króla Lisza!$B$BTe, które otrzymują jego dar, nazywają val\'kyriami. Latają na pierzastych skrzydłach, jak harpie, którymi są.$B$BValkyrion znajdziesz daleko na północnym zachodzie, za Świątynią Burz. Zabij te skrzydlate wilczyce, siostro. Zabij je, a nagrodzę cię jednym z moich najcenniejszych skarbów.', 'Iva Mściwa z Wioski Brunnhildar chce, żebyś $gudał:udała; się do Valkyrionu i $gzabił:zabiła; 12 rodzących się val\'kyrii.', '', 'Wróć do Ivy Mściwej w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12953, 'koKR', 'Valkyrion musi spłonąć', 'Skrzynia jest pełna zapalających harpunów. Przypominasz sobie, że na zewnątrz $gwidziałeś:widziałaś; wyrzutnie harpunów i suche stogi siana.$B$BByć może Iva doceni dodatkowy wysiłek i odpowiednio cię nagrodzi.', 'Użyj wyrzutni harpunów z Valkyrionu, aby podpalić 6 suchych stogów siana.', '', 'Wróć do Ivy Mściwej w Wiosce Brunnhildar na Burzowych Szczytach.', 'Wzniecone pożary', '', '', '', 0),
(12956, 'koKR', 'Iskra nadziei', 'To oczywiście coś więcej niż zwykła bryła metalu.$b$bNie przypomina żadnej znanej ci rudy: jest twarda, ale nie krucha, znacznie lżejsza, niż się wydaje, i świeci nawet wtedy, gdy jest zimna.$b$bPrzyglądając się bliżej, dostrzegasz pod powierzchnią lśniącą runę Thorima...', 'Masz zanieść oczyszczoną lśniącą rudę Thorimowi w Świątyni Burz.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', '', '', '', '', 0),
(12957, 'koKR', 'Niewolnicy burzowiernych', 'Na południowym zachodzie, w zachodniej części Równin Zasp, żelazne krasnoludy wykopały w zboczu kopalnię. Wykorzystują tam do wydobycia rudy uwięzione mechagnomy, sługi Opiekuna Mimira.$B$BNie wiem, skąd się wzięły te mechagnomy ani co by zrobiły z wolnością, ale może uda nam się pozyskać ich pomoc.$B$BIdź do Zamarzniętej Kopalni, $N, i uwolnij te istoty z niewoli. Zapytaj je, czy stanęłyby z nami do walki z tyranią żelaznych krasnoludów.', 'Bouldercrag Kształtujący Skały ze Schronienia Bouldercraga chce, żebyś $guwolnił:uwolniła; 6 uwięzionych mechagnomów i $gzabił:zabiła; 3 burzowiernych nadzorców.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Spróbuj uwolnić uwięzionego mechagnoma', '', '', '', 0),
(12964, 'koKR', 'Ciemna ruda', 'W Zamarzniętej Kopalni, w zachodniej części Równin Zasp, burzowierne żelazne krasnoludy zbudowały kopalnię obsadzoną niewolnikami.$B$BLeży daleko za linią frontu, więc niewiele udało nam się dowiedzieć o tym, co się tam dzieje, ale moi zwiadowcy donoszą, że wywożą stamtąd całe wózki ciemnej, chorobliwie wyglądającej rudy.', 'Przynieś 5 próbek rudy Bouldercragowi Kształtującemu Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', '', '', '', '', 0),
(12965, 'koKR', 'Dary Lokena', 'Tym, który dowodzi burzowiernymi żelaznymi krasnoludami, jest wieszcz run Valduran. Choć sam nigdy ich nie widziałem, mówi się, że jego pan, Opiekun Loken, który przejął Ulduar, dał Valduranowi potężne artefakty tytanów.$B$BTo by tłumaczyło siłę i zajadłość, jaką moi ludzie widzą u burzowiernych wojowników.$B$BBaza Valdurana, Nidavelir, leży na południowym zachodzie, za Równinami Zasp. Idź tam, $N, i zniwecz jego moc. Zniszcz te dary Lokena i pomóż nam osłabić jego zwolenników.', 'Zniszcz Furię Lokena, Moc Lokena i Łaskę Lokena, a następnie wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Furia Lokena zniszczona', 'Moc Lokena zniszczona', 'Łaska Lokena zniszczona', '', 0),
(12966, 'koKR', 'Nie da się go przeoczyć', '<Jokkum cierpliwie wysłuchuje twojej prośby, a potem starannie ją rozważa, zanim odpowie.>$b$bA więc to tobie zawdzięczamy upadek Fjorna?$b$bTo prawda, że $gpomogłeś:pomogłaś; nam w potrzebie, ale wiele jeszcze trzeba zrobić, by naprawić nasze stosunki z Thorimem.$b$bNa razie pozwolę Njormeldowi przekuć zbroję, którą przed wiekami podarowaliśmy Władcy Burz. Uznaj to za zapłatę za pomoc w walce z Fjornem.$b$bNjormeld został wysłany, by odzyskać kowadło Fjorna. Tam go znajdziesz.', 'Król Jokkum w Dun Niffelem chce, żebyś $godnalazł:odnalazła; Njormelda przy Kowadle Fjorna.', '', '', '', '', '', '', 0),
(12967, 'koKR', 'Walka z żywiołami', 'Snorri był niegdyś dumą naszego narodu. Potężny wojownik, od jego maczugi padło wielu wrogów.$b$bCzcimy go, choć nie jest już tym, kim był. Wiek zrobił swoje, stępił jego zmysły i odebrał mu siłę. Mimo to wciąż jest dumny jak zawsze i nie przepuści żadnej okazji, by stanąć do walki.$b$bSkoro mowa o walce, chłodzimy kowadło Fjorna, żeby można je było zabrać do domu. Pozostałe ogniste zjawy stawiają pewien opór. Pomóż Snorriemu przeżyć na nowo dni chwały, $N. Poprowadź go przeciwko temu wrogowi.', 'Njormeld chce, żebyś $gtowarzyszył:towarzyszyła; Snorriemu przy Kowadle Fjorna i $gpomógł:pomogła; mu zabić 10 kipiących zjaw.', '', 'Wróć do Njormelda przy Kowadle Fjorna na Burzowych Szczytach.', 'Zabite kipiące zjawy', '', '', '', 0),
(12968, 'koKR', 'Szaleństwo Yuldy', 'Wiedźma, od której wszystko się zaczęło, Yulda Głos Burzy, przybyła do samej naszej wioski. Śmiała znieważyć nasze szlachetne tradycje i wygłaszała jadowite obietnice mocy od Króla Lisza.$B$BPowinna była odejść z mieczem w brzuchu, ale jej magia była silna i zdołała uciec.$B$BSzukaj jej w Valkyrionie, w największym domostwie, i pokaż jej, że z nami się nie igra.', 'Iva Mściwa z Wioski Brunnhildar chce, żebyś $gzabił:zabiła; Yuldę Głos Burzy w Valkyrionie.', '', 'Wróć do Ivy Mściwej w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12969, 'koKR', 'Czy to twój goblin?', 'Sądzę, że to ten mały zielony, którego szukasz. Na twoim miejscu wkroczyłabym, zanim ta Hyldnir przepołowi go.$B$B$GTrafiłeś:Trafiłaś; w sam środek Hyldsmeet, więc uczestniczki muszą przyjąć każde wyzwanie. Nic nie stoi na przeszkodzie, żebyś $gzajął:zajęła; miejsce swojego zielonego przyjaciela.', 'Wyzwij Agnettę Tyrsdottar, aby ocalić Zeeva Fizzlesparka. Po zwycięstwie wróć do Lok\'liry Staruchy w Wiosce Brunnhildar.', '', 'Wróć do Lok\'liry Staruchy w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12970, 'koKR', 'Hyldsmeet', 'Czy to zauważyłaś, czy nie, pokonując w walce wręcz swoją pierwszą Hyldnir, przystąpiłaś do Hyldsmeet – wielkich zawodów, w których Hyldnir walczą z Hyldnir, by wyłonić tę, która będzie rządzić u boku Thorima.$B$BTo z powodu Hyldsmeet mnie uwięziono, bo chciałam wziąć udział w zawodach, choć byłam zbyt stara i słaba, by dorównać Hyldnir.$B$BJeśli zechcesz posłuchać, mam dla ciebie propozycję.', 'Wysłuchaj propozycji Lok\'liry Staruchy.', '', 'Wróć do Lok\'liry Staruchy w Wiosce Brunnhildar na Burzowych Szczytach.', 'Wysłuchaj propozycji Lok\'liry', '', '', '', 0),
(12971, 'koKR', 'Przeciw wszystkim pretendentkom', 'Zaczynajmy. Dobra wiadomość jest taka, że pokonując Agnettę, zapewniłaś sobie miejsce w następnej rundzie pojedynków.$B$BZła wiadomość jest taka, że wszystkie twoje przeciwniczki też kogoś pokonały w pierwszej rundzie. Nie spodziewaj się łatwych przeciwników.', 'Lok\'lira Starucha z Wioski Brunnhildar chce, żebyś $gpokonał:pokonała; 6 zwycięskich pretendentek.', '', 'Wróć do Lok\'liry Staruchy w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12972, 'koKR', 'Przyda ci się niedźwiedź', 'Przeszłaś pierwsze rundy Hyldsmeet. Aby awansować dalej, potrzebujesz własnego niedźwiedzia bojowego.$B$BNiestety Hyldnir nie dają ich byle komu. Musisz zwyciężyć w prawdziwej bitwie, a nie tylko w walce na arenie.$B$BHyldnir z Brunnhildar toczą obecnie spór z Synami Hodira, dawnymi sojusznikami Thorima. Porozmawiaj z Brijaną tuż za wioską i dowiedz się, jak możesz im pomóc, a przy okazji się wykazać.', 'Porozmawiaj z Brijaną przed Wioską Brunnhildar.', '', '', '', '', '', '', 0),
(12973, 'koKR', 'Bracia Miedziobrodzi', 'No i jest! Wreszcie mamy zwornik... Jest piękny! Objechałem świat nie raz, ale przez to cudo znowu aż się trzęsę z podniecenia. Chyba jednak nie pora teraz stać i podziwiać – musimy się stąd zmywać.$B$BWskakuj do mojej fruwającej maszyny i osłaniaj nas przed tymi żelaznymi krasnoludami, kiedy będziemy się stąd wydostawać!', 'Towarzysz Brannowi Miedziobrodemu i jego fruwającej maszynie w drodze do Mroźnej Warowni.', 'Towarzysz Brannowi Miedziobrodemu w drodze do Mroźnej Warowni.', 'Wróć do Veloga Lodowego Ryku w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(12975, 'koKR', 'Ku pamięci', 'Thorim z pewnością opowiedział ci o tragedii, która nas dzieli.$b$bTe wydarzenia rozegrały się w Gromospadzie, na północny wschód stąd. Zamarznięte skamieliny, które tam są, przypominają o tamtym mrocznym dniu, podobnie jak duchy nawiedzające to miejsce.$b$bJeśli mój lud ma wybaczyć Thorimowi, coś musi zająć miejsce tamtych obrazów. Trzeba wznieść pomnik, który przyniesie spokój naszym sercom.$b$bUdaj się tam, $N. Zbierz fragmenty Rogu Hodira, który tamtego dnia został roztrzaskany.', 'Król Jokkum w Dun Niffelem chce, żebyś $gzebrał:zebrała; 8 fragmentów rogu w Gromospadzie.', '', 'Wróć do króla Jokkuma w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(12976, 'koKR', 'Pomnik poległych', 'Zanieś te fragmenty Njormeldowi. Użyje kawałków tej świętej relikwii do budowy potężnego pomnika.$b$bNiech ukoi ból i zaleczy blizny, które mój lud nosi od tylu lat.$b$bNiech jego obecność pomoże nadejść nowej erze, w której znów staniemy do chwalebnej walki u boku Thorima.$b$bIdź już, $N. Njormeld na ciebie czeka.', 'Król Jokkum chce, żebyś $gzaniósł:zaniosła; fragmenty Rogu Hodira Njormeldowi w Dun Niffelem.', '', 'Wróć do Njormelda w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(12977, 'koKR', 'Zadęcie w Róg Hodira', '$GOddałeś:Oddałaś; wielką przysługę olbrzymom z Dun Niffelem. Bez twojej pomocy ten pomnik by nie powstał.$b$bGdy w milczeniu rozważasz jego znaczenie, twoje serce zaczynają zalewać uczucia. Wypełniają ci umysł myślami i obrazami... a także poczuciem, że trzeba się spieszyć.$b$bDoznania gasną i zostawiają cię ze świadomością tego, co musisz zrobić. Niespokojne duchy w Gromospadzie muszą zaznać spokoju.$b$bGdy ruszasz w drogę, odkrywasz, że w dłoniach trzymasz eteryczny róg.', 'Pokonaj 5 praojców z Niffelem i 5 niespokojnych mroźnorodnych w Gromospadzie. Następnie zadmij w Róg Hodira nad ich zwłokami i wróć do Rogu Hodira w Dun Niffelem.', '', 'Wróć do króla Jokkuma w Dun Niffelem na Burzowych Szczytach.', 'Uwolniony praojciec z Niffelem', 'Uwolniony niespokojny mroźnorodny', '', '', 0),
(12978, 'koKR', 'Stawić czoła burzy', 'Tak jak Bouldercrag, niegdyś służyłem Opiekunom jako rzemieślnik w Ulduarze, ale po zdradzie Lokena zwróciłem swój młot przeciwko nowym wrogom.$B$BGdy tylko mogliśmy wysłać ludzi, prowadziłem wypady na Nidavelir, żeby odciążyć naszych obrońców, ale nasze linie są bliskie załamania.$B$B$GDowiodłeś:Dowiodłaś;, że $gjesteś sprawnym wojownikiem:jesteś sprawną wojowniczką; i $gniezłomnym sojusznikiem:niezłomną sojuszniczką;. Może zechcesz ponieść nasz sztandar i zanieść walkę do Nidaveliru, twierdzy żelaznych krasnoludów na południowym zachodzie, za Równinami Zasp.', 'Bruor Zguba Żelaza w Schronieniu Bouldercraga chce, żebyś $gzabił:zabiła; 10 burzowiernych z Nidaveliru. Możesz zabijać burzowiernych czempionów, burzowiernych magusów lub burzowierne golemy bojowe.', '', 'Wróć do Bruora Zguby Żelaza w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Zabici burzowierni z Nidaveliru', '', '', '', 0),
(12979, 'koKR', 'Pancerz ciemności', 'Ta płyta pancerna jest gruba i za duża w porównaniu z resztą osłon golema. Szybkie oględziny jego szczątków pokazują, że cięższą płytę przykręcono chyba dopiero później, jako prowizoryczne ulepszenie.$B$BPo co żelazne krasnoludy miałyby dokładać swoim golemom bojowym ten zbędny, niedopasowany pancerz?$B$BMoże Bruor Zguba Żelaza by wiedział, gdyby mógł obejrzeć kilka takich płyt zdjętych z burzowiernych golemów bojowych.', 'Przynieś 4 próbki ciemnego pancerza Bruorowi Zgubie Żelaza w Schronieniu Bouldercraga.', '', 'Zamelduj się u Bruora Zguby Żelaza w Schronieniu Bouldercraga na Burzowych Szczytach.', '', '', '', '', 0),
(12980, 'koKR', 'Tajemnice pancerza', 'Bliskość tej płyty pancernej mąci zmysły, ale musimy się z niej dowiedzieć wszystkiego, co się da. Może to być część któregoś z planów Valdurana.$B$BWłożył niezwykle dużo wysiłku w wydobycie, oczyszczanie, kucie i testowanie tego metalu.$B$BNa wschodzie, wzdłuż północnego zbocza gór, stoi budowla zwana Warsztatem Mimira. Od dawna nikt z niej nie korzysta, ale przy odrobinie szczęścia niektórzy z jej asystentów wciąż działają. Zanieś tam płytę pancerną i dowiedz się o niej, ile zdołasz.', 'Zanieś ciemną płytę pancerną do Warsztatu Mimira i poproś asystenta Tocka, żeby ją zbadał. Potem wróć do Bruora Zguby Żelaza w Schronieniu Bouldercraga.', '', 'Wróć do Bruora Zguby Żelaza w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Zbadana płyta pancerna', '', '', '', 0),
(12981, 'koKR', 'Na gorąco i na zimno', 'Gdy wpatrujesz się w kowadło, na nowo przeżywasz swoje niedawne dokonania, zwłaszcza te, dzięki którym ten artefakt spoczął właśnie tutaj.$b$bNagle uświadamiasz sobie, że wiele jeszcze zostało do zrobienia. Na wschodzie krajobraz zaśmiecają tlące się szczątki – odłamki z bitwy, która się tam rozegrała.$b$bGdyby dało się je jakoś ostudzić i zebrać, mroźne olbrzymy miałyby pod dostatkiem metalu, a okolica zostałaby oczyszczona z tych pozostałości wojny.', 'Udaj się nad Jezioro Mroźnego Pola, zabij tamtejsze kruche zjawy i użyj esencji lodu na tlącym się złomie. Następnie zbierz 6 kawałków zamarzniętego złomu żelaza i wróć do Kowadła Fjorna w Dun Niffelem.', '', 'Wróć do Kowadła Fjorna w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(12983, 'koKR', 'Ostatnia ze swego rodu', 'Odkąd pamiętam, najlepsze niedźwiedzie sprowadzaliśmy z Pieczary Zimowego Snu na wschodzie.$B$BTe czasy chyba w końcu minęły. Pieczarę opanowały wygłodniałe jormungary, a dzikie niedźwiedzie prawie całkiem wyginęły.$B$BGdyby jednak udało ci się znaleźć ocalałą matriarchę, gwarantuję, że walczyłaby lepiej niż którykolwiek z tych niedźwiedzi urodzonych w niewoli.$B$BZabierz tę uprząż do Pieczary Zimowego Snu i uratuj ocalałą matriarchę. Powodzenia w szukaniu.', 'Astrid Bjornrittar z Wioski Brunnhildar chce, żebyś $guratował:uratowała; matriarchę lodopysków w Pieczarze Zimowego Snu.', '', 'Wróć do Astrid Bjornrittar w Wiosce Brunnhildar na Burzowych Szczytach.', 'Uratowana matriarcha lodopysków', '', '', '', 0),
(12984, 'koKR', 'Valduran Zrodzony z Burzy', 'Nie mamy wyboru, $N. To, czego $gdowiedziałeś:dowiedziałaś; się w Warsztacie Mimira, oznacza, że musimy działać, zanim Valduran ukończy swoją nową broń i ją uwolni.$B$BNawet teraz obrońcy schronienia walczą, żeby kupić nam czas na rozprawę z Valduranem Zrodzonym z Burzy.$B$BMusisz udać się do Nidaveliru, za Równinami Zasp na południowym zachodzie, a potem odnaleźć Valdurana i stawić mu czoła. Ale nie będziesz $gsam:sama;. Weź ze sobą ten róg wojenny i zadmij w niego, gdy przygotujesz się do starcia z przywódcą naszych wrogów. Bruor i ja pomożemy ci w tej bitwie.', 'Użyj rogu wojennego Bouldercraga, gdy odnajdziesz Valdurana Zrodzonego z Burzy. Pokonaj Valdurana Zrodzonego z Burzy i wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', '', '', '', '', 0),
(12985, 'koKR', 'Wykuwanie głowy', 'Witaj.$b$bMam zadanie, do którego według króla Jokkuma się nadajesz, o ile nadal zabiegasz o przychylność naszego ludu.$b$bOpracowałem plany kolejnego artefaktu, który obdarzy naszą twierdzę ochronnym błogosławieństwem Hodira. Mam niemal wszystko, czego potrzebuję do jego budowy. Pozostało tylko zebrać oczy naszych poległych wrogów.$b$bWeź to narzędzie i wydobądź oczy z truchła żelaznych olbrzymów, które zaścielają nasze pola.', 'Njormeld z Dun Niffelem potrzebuje, żebyś $gużył:użyła; kilofa z diamentowym ostrzem na martwych żelaznych olbrzymach nad Jeziorem Mroźnego Pola i $gwrócił:wróciła; do niego, gdy zbierzesz 8 burzowiernych oczu.', '', 'Wróć do Njormelda w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(12986, 'koKR', 'Los tytanów', 'Rdzenia Norgannona nie ma w tym miejscu. Nie wiem, dlaczego go szukasz, i równie mało jestem pewien, czy naprawdę znasz przeznaczenie tego, czego szukasz.$B$BChciałbym, abyś mi $gpomógł:pomogła;, zanim rozważę udzielenie ci pomocy. Niedawno natrafiłem na wiedzę o obserwatorze Thorimie. Jego siedziba władzy jest przedmiotem sporu, a jego los wciąż pozostaje niepewny. Niepokoi mnie to, gdyż nic nie wiem o pozostałych obserwatorach. Użyj tego banku danych, by zbadać ich świątynie na północnym wschodzie, i przynieś mi zdobytą wiedzę.', 'Creteus na Stepach Podnóża prosi, żebyś $gudał:udała; się do Świątyni Wynalazków, Świątyni Zimy, Świątyni Życia i Świątyni Porządku i $gzbadał:zbadała; każde z tych miejsc za pomocą banku danych.', '', 'Wróć do Creteusa na Stepach Podnóża na Burzowych Szczytach.', 'Zbadana Świątynia Wynalazków', 'Zbadana Świątynia Zimy', 'Zbadana Świątynia Życia', 'Zbadana Świątynia Porządku', 0),
(12987, 'koKR', 'Umieszczenie Hełmu Hodira', 'Hełm został wykuty.$b$bTwoje wysiłki nie pozostały niezauważone, $gmaleńki:maleńka;. Choć wiele jeszcze zostało do zrobienia, my, synowie Hodira, jesteśmy wdzięczni za twoje dokonania.$b$bW zamian daję ci możliwość zaprezentowania hełmu Hodira naszemu królowi i naszym braciom.$b$bPoleć na lśniący czubek małego lodowego szpikulca przede mną i odczytaj naszemu ludowi tekst z tych tablic.$b$bCiesz się tym przywilejem, $N. Nigdy dotąd żaden obcy nie dostąpił takiego zaszczytu!', 'Njormeld chce, żebyś $gpoleciał:poleciała; na czubek północnego lodowego szpikulca w Dun Niffelem i $gużył:użyła; tablic obwieszczeń.', '', 'Wróć do Njormelda w Dun Niffelem na Burzowych Szczytach.', 'Umieszczony Hełm Hodira', '', '', '', 0),
(12988, 'koKR', 'Zniszczyć kuźnie!', 'W swojej głupocie sądziłem, że przedsięwzięcie Valdurana w Kolebce Narvira, wielkim placu budowy na południu, to nic więcej niż groteskowy pomnik okrucieństwa „Opiekuna” Lokena.$B$BTeraz znamy prawdę: miało posłużyć jako broń przeciwko nam i naszym sojusznikom. Nie możemy pozwolić, by ten żelazny kolos został ukończony, $N, bo oznaczałoby to koniec schronienia.$B$BIdź do Kolebki Narvira, znajdź piorunowe kuźnie, których używają burzowierni rzemieślnicy, i unieszkodliw je.', 'Zniszcz Północną piorunową kuźnię, Centralną piorunową kuźnię i Południową piorunową kuźnię bombami Bouldercraga, a następnie wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Uszkodzona Północna piorunowa kuźnia', 'Uszkodzona Centralna piorunowa kuźnia', 'Uszkodzona Południowa piorunowa kuźnia', '', 0),
(12989, 'koKR', 'Pełzająca ciemność', 'Podłe jormungary opanowały większość Pieczary Zimowego Snu. To odrażające istoty... dzieci Lokena, tego parszywego brata Thorima.$B$BJako słudzy Thorima jesteśmy to sobie winni, by zabijać te szumowiny, gdziekolwiek je znajdziemy. Pieczarę znajdziesz tuż na wschód stąd, za wioską.', 'Astrid Bjornrittar chce, żebyś $gzabił:zabiła; 8 wygłodniałych jormungarów w Pieczarze Zimowego Snu na wschód od Wioski Brunnhildar.', '', 'Wróć do Astrid Bjornrittar w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12991, 'koKR', 'Uderz tam, gdzie boli', 'Bouldercrag ma dobry plan, by pokrzyżować wysiłki żelaznych krasnoludów w Kolebce Narvira, a ja mam własny pomysł. Prace nad żelaznym kolosem staną, jeśli zabraknie rzemieślników.$B$BKolebka Narvira leży po południowej stronie wzgórza, które osłania Schronienie Bouldercraga. Idź tam i zabij wszystkich burzowiernych artefaktorów, którzy staną ci na drodze. Może nie różnią się od tego, czym my kiedyś byliśmy, ale budują broń, która zagraża nam wszystkim.', 'Zabij 10 burzowiernych artefaktorów i wróć do Bruora Zguby Żelaza w Schronieniu Bouldercraga.', '', 'Wróć do Bruora Zguby Żelaza w Schronieniu Bouldercraga na Burzowych Szczytach.', '', '', '', '', 0),
(12993, 'koKR', 'Kolosalne zagrożenie', 'Świetnie ci poszło opóźnianie prac nad żelaznym kolosem, ale obawiam się, że burzowierni są teraz jeszcze bardziej zdeterminowani, by ukończyć broń.$B$BNawet teraz sprowadzają nowych robotników, a nadzorcy wyciskają z nich ostatnie siły. Może mimo wszystko nie zdołamy powstrzymać ich przed uruchomieniem kolosa. Wróć do Kolebki Narvira na południu i znajdź dokumenty opisujące zdolności ofensywne i obronne kolosa. Powinny leżeć przy namiotach i kuźniach na najniższym poziomie.', 'Zdobądź specyfikację ataku kolosa i specyfikację obrony kolosa i przynieś je Bouldercragowi Kształtującemu Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', '', '', '', '', 0),
(12994, 'koKR', 'Łowca szpiegów', 'Więź, którą $gnawiązałeś:nawiązałaś; z mieszkańcami Dun Niffelem, przyniosła kilka nieoczekiwanych odkryć.$b$bNa przykład jakimś cudem rozumiesz gardłowe warknięcia i ostre pomruki matki legowiska – a przynajmniej tak ci się wydaje.$b$bWygląda na to, że wyczuwa niebezpieczeństwo poza twierdzą i chce, żebyś coś z tym $gzrobił:zrobiła;.$b$bPrzednią łapą zdejmuje z szyi łańcuch i upuszcza go u twoich stóp. Gdy go podnosisz, zauważasz przymocowany do niego stary kieł...', 'Musisz pokonać 3 burzowiernych szpiegów w Dolinie Pradawnych Zim.$b$bUżycie kła eterycznego worga przy zwłokach poległego worga przywoła eterycznego mroźnego worga, który zdemaskuje ukrytych wrogów. Gdy dolina zostanie oczyszczona ze szpiegów, wróć do matki legowiska mroźnych worgów w Dun Niffelem.', '', 'Wróć do matki legowiska mroźnych worgów w Dun Niffelem na Burzowych Szczytach.', 'Zabici burzowierni infiltratorzy', '', '', '', 0),
(12996, 'koKR', 'Rozgrzewka', 'Masz wielkie szczęście, siostro. To matriarcha, jakiej nie widziano od lat.$B$BDobry niedźwiedź na niewiele ci się zda, jeśli nie umiesz na nim jeździć.$B$BPoćwiczysz kilka ruchów na Kirgaraaku. To największy yeti, jakiego kiedykolwiek udało nam się schwytać, więc uważaj. Nie bój się wycofać, jeśli spuści ci lanie... nie bez powodu trzymamy go na łańcuchu.', 'Astrid Bjornrittar z Wioski Brunnhildar chce, żebyś $gpokonał:pokonała; Kirgaraaka przy użyciu wodzy matriarchy niedźwiedzi bojowych.', '', 'Wróć do Astrid Bjornrittar w Wiosce Brunnhildar na Burzowych Szczytach.', 'Pokonany Kirgaraak', '', '', '', 0),
(12997, 'koKR', 'Do Czeluści', 'Pokonanie przywiązanego przeciwnika to jedno. Walka z innymi jeźdźcami niedźwiedzi na równych warunkach to co innego.$B$BUdaj się do Czeluści Kła i wykorzystaj to, czego się $gnauczyłeś:nauczyłaś;, by pokonać przeciwników. Powodzenia, siostro.$B$BJeśli ci się uda, czeka cię chwała.', 'Astrid Bjornrittar z Wioski Brunnhildar chce, żebyś $gużył:użyła; wodzy matriarchy niedźwiedzi bojowych w Czeluści Kła i $gpokonał:pokonała; 6 niedźwiedzi bojowych z Hyldsmeet.', '', 'Wróć do Astrid Bjornrittar w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(12998, 'koKR', 'Serce Burzy', 'Według dokumentów, które $gzdobyłeś:zdobyłaś; w Kolebce Narvira, żelazny kolos jest gotowy, brakuje mu tylko jednego kluczowego elementu – Serca Burzy.$B$BBez niego broń żelaznego kolosa byłaby znacznie słabsza, niż przewiduje projekt. Jeśli nie dopuścimy, by nadzorca Narvir zdobył serce, będziemy mogli pokonać kolosa!$B$BZ notatek na znalezionych przez ciebie dokumentach wynika, że serce znajduje się w Uldis, obiekcie tytanów daleko na południu. Wejście leży po południowej stronie wysokiej góry, która wznosi się nad Rzeką Oddechu Bora.', 'Bouldercrag Kształtujący Skały w Schronieniu Bouldercraga chce, żebyś $gudał:udała; się do Uldis i $gspróbował:spróbowała; nie dopuścić, by nadzorca Narvir zdobył Serce Burzy.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Próba zabezpieczenia Serca Burzy', '', '', '', 0),
(13000, 'koKR', 'Środki nadzwyczajne', 'Zimno w tych górach jest bezlitosne. Za dzień lub dwa spalimy całe drewno z wraku.$B$BW jaskini tuż na wschód stąd widzieliśmy worgi. Musisz odnaleźć tę jaskinię i zdobyć trochę futer. Może to niewiele, ale może przesądzić o tym, czy zamarzniemy na śmierć, czy przeżyjemy kolejny dzień.$B$BWorgi nie polują w pojedynkę, więc dam ci flarę. Powinna dać ci trochę czasu, jeśli przeciwników okaże się za dużo.', 'Strażniczka krwi Lorga chce, żebyś $gudał:udała; się do Nory Gimoraka na wschodzie i $gzdobył:zdobyła; 6 futer worga.', '', 'Wróć do strażniczki krwi Lorgi na Miejscu Katastrofy Grom\'arsha na Burzowych Szczytach.', '', '', '', '', 0),
(13001, 'koKR', 'Wzniesienie Włóczni Hodira', 'Nadszedł czas, $gmaleńki:maleńka;. Gwiazdy przepowiedziały ten dzień.$b$bOtrzymałem wizję od samego potężnego Hodira, która odsłoniła tajemnicę stworzenia wielkiego artefaktu.$b$bMusimy być posłuszni! Gdybyśmy nie przyjęli tego daru, z pewnością spotkałaby nas zguba.$b$bWzywam cię, byś $gpomógł:pomogła; mi w tym świętym przedsięwzięciu.$b$bPrzejdź przez dolinę, zapuść się w głąb Pieczary Zimowego Snu i zbierz wiecznolodowe odłamki z tamtejszego lodowego krateru, a potem zdobądź skóry mamutów żyjących przed pieczarą.', 'Wiedzący Randvir z Dun Niffelem chce, żebyś $gzebrał:zebrała; 3 wiecznolodowe odłamki z głębin Pieczary Zimowego Snu i 3 skóry niewzruszonych mamutów w Dolinie Pradawnych Zim.', '', 'Wróć do Wiedzącego Randvira w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(13003, 'koKR', 'Pchnięcie Włócznią Hodira', 'Włócznia Hodira to symbol wielkiej waleczności w boju.$b$bSama jej obecność budzi głęboki głód chwały w każdym, kto przybywa do Dun Niffelem. Właściwie już samo przebywanie w jej pobliżu skłoniło cię do sprawdzenia własnych umiejętności.$b$bGdy przeczesujesz wzrokiem horyzont, dostrzegasz dzikiego żmija przelatującego w pobliżu.$b$bPostanowione. Z was dwojga tylko jedno ujrzy kolejny wschód słońca...', 'Użyj Włóczni Hodira, by wyzwać dzikiego żmija w Dolinie Pradawnych Zim. Gdy już pochwyci cię w szpony, walcz na śmierć i życie.', '', 'Wróć do Włóczni Hodira w Dun Niffelem na Burzowych Szczytach.', 'Zabity dziki żmij', '', '', '', 0),
(13005, 'koKR', 'Przysięga ziemnych', 'Przez lata zaniedbywałem swoje obowiązki, poddając się klęsce i użalaniu nad sobą.$B$BNie to co dzielni ziemni. Ich przysięga, by bronić tych ziem własnym życiem, pozostała niezłomna.$B$BNawet teraz ofiarnie walczą z zepsuciem żelaza, czekając na chwilę, w której szala się przechyli.$B$BTa chwila nadeszła. Musimy zebrać to, co zostało z ziemnych obrońców, i poprowadzić ich do chwalebnego zwycięstwa. Zadmij w Róg szczytów, by wezwać ich do siebie, i odbij Taras Twórców.', 'Thorim na Tarasie Twórców chce, żebyś $gużył:użyła; Rogu szczytów i $gwezwał:wezwała; ziemnych, by pokonać 20 żelaznych krasnoludów i 7 żelaznych wartowników.', '', 'Wróć do Thorima na Tarasie Twórców na Burzowych Szczytach.', 'Zabity żelazny wartownik', 'Zabity napastnik żelaznych krasnoludów', '', '', 0),
(13006, 'koKR', 'Polerowanie hełmu', 'Gdy zbliżasz się do hełmu, zauważasz, że mroźne otoczenie już odciska piętno na powierzchni artefaktu. To, co teraz jest jedynie cienką warstewką lodu, z pewnością rozrośnie się i pokryje go całkowicie.$b$bNie zamierzasz pozwolić, by twój ciężki trud poszedł na marne, więc postanawiasz przeczesać okolicę w poszukiwaniu rozwiązania.$b$bGdy tylko ruszasz, oczy hełmu rozbłyskują, a w twoim umyśle pojawia się obraz pobliskiej Pieczary Zimowego Snu.', 'Wejdź do Pieczary Zimowego Snu na zachód od Dun Niffelem i zbierz 5 porcji lepkiego oleju z tamtejszych lepkich olejów.$b$bNastępnie wróć do Dun Niffelem i nałóż olej na Hełm Hodira.', '', 'Wróć do Hełmu Hodira w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(13007, 'koKR', 'Żelazny kolos', 'Nie zdołaliśmy zapobiec ukończeniu żelaznego kolosa, $N, więc nie mamy wyboru – musimy stawić mu czoła w bitwie.$B$BBruor wymyślił plan, jak wykorzystać jedyną słabość kolosa.$B$BNiezależnie od tego, jak wytrzymały jest jego pancerz, wciąż jest podatny na kwas jormungara. Przejmij kontrolę nad jednym z nich za pomocą kul wzdłuż północnego skraju Równin Zasp, a potem użyj go do walki z żelaznym kolosem na Równinach Zasp. Jeśli potrzebujesz pomocy w kierowaniu stworzeniem, porozmawiaj z którymś z pobliskich treserów.', 'Użyj oswojonego jormungara, by pokonać żelaznego kolosa, i wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga.', '', 'Wróć do Bouldercraga Kształtującego Skały w Schronieniu Bouldercraga na Burzowych Szczytach.', '', '', '', '', 0),
(13009, 'koKR', 'Nowy początek', 'Nie wiadomo, czy nasz lud zdoła kiedykolwiek na nowo rozpalić uczucie, którym niegdyś darzył Thorima.$b$bNiech ta zbroja przynajmniej przypomni mu czasy, gdy staliśmy razem w honorze, niezwyciężeni.', 'Njormeld chce, żebyś $gzaniósł:zaniosła; przekutą zbroję Thorimowi do Świątyni Burz.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', '', '', '', '', 0),
(13010, 'koKR', 'Krolmir, Młot Burz', 'Zostało jeszcze jedno zadanie, zanim będę mógł odzyskać swój dom na Tarasie Twórców.$b$bTrzeba odnaleźć Krolmira.$b$bTamtego pamiętnego dnia cisnąłem go o ziemię z całą mocą i wściekłością, jaką w sobie miałem. Nastąpił potężny wybuch.$b$bPrzez wszystkie te lata uważałem go za utracony, ale teraz muszę mieć pewność.$b$bWróć do króla Jokkuma i dowiedz się, co – jeśli w ogóle cokolwiek – wie o losie mojego młota.', 'Thorim chce, żebyś $gporozmawiał:porozmawiała; z królem Jokkumem w Dun Niffelem i $gdowiedział:dowiedziała; się, co wie o Krolmirze.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', 'Poznany los Krolmira', '', '', '', 0),
(13011, 'koKR', 'Jormuttar jest taaaka gruba...', 'Mam dla ciebie okazję, która pomoże ci zyskać uznanie mojego ludu, o ile zwyciężysz.$b$bZ jormungarami najlepiej rozprawić się szybko. Jeśli da się im choć chwilę wytchnienia, mnożą się jak zające i szerzą jak ogień.$b$bPojawiły się na południowy zachód stąd, w Pieczarze Zimowego Snu. Jeśli matka tego pomiotu nie zginie wkrótce, zadomowią się w naszej okolicy.$b$bOna nie potrafi odmówić jedzenia. Weź ten nóż i wytnij udziec z truchła niedźwiedzia w ich jaskini. Połóż go przy jej kraterze i zabij ją, gdy będzie się pożywiać.', 'Król Jokkum z Dun Niffelem chce, żebyś $gzabił:zabiła; Jormuttar w Pieczarze Zimowego Snu.', '', 'Wróć do króla Jokkuma w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(13015, 'koKR', 'Nestor Fargal', '', '', '', '', '', '', '', '', 0),
(13020, 'koKR', 'Nestor Kamiennobrody', '', '', '', '', '', '', '', '', 0),
(13028, 'koKR', 'Nestor Szarogrzywy', '', '', '', '', '', '', '', '', 0),
(13032, 'koKR', 'Nestor Muraco', '', '', '', '', '', '', '', '', 0),
(13034, 'koKR', 'Świadek i bohater', 'Gdy rozpoczynałem wędrówkę po Północnej Grani, odwiedziłem Boreańską Tundrę i po raz pierwszy spotkałem taunka. Tam poskromicielka wiatru Barah opowiedziała mi historię Burzokopytego i jego walki z Północnym Wiatrem, odwiecznym wrogiem ich ludu.$B$BWyruszyłem na Burzowe Szczyty, by dowiedzieć się więcej o tym bohaterze, ale dziwnym trafem mieszkańcy Tunka\'lo zdają się nic o nim nie wiedzieć.$B$BByć może zapiski samego obozu pozwolą nam lepiej to zrozumieć. Odszukaj i przeczytaj zwoje historii przechowywane w obozie, a potem powiedz mi, czego się $gdowiedziałeś:dowiedziałaś;.', 'Xarantaur w Obozie Tunka\'lo chce, żebyś $gprzeczytał:przeczytała; pierwszy, drugi i trzeci zwój historii.', '', 'Wróć do Xarantaura w Obozie Tunka\'lo na Burzowych Szczytach.', 'Przeczytany pierwszy zwój historii', 'Przeczytany drugi zwój historii', 'Przeczytany trzeci zwój historii', '', 0),
(13035, 'koKR', 'Sługusi Lokena', 'Atak na Taras Twórców nie był połowicznym posunięciem mojego brata. Wysłał legion żelaznych krasnoludów i kilku swoich najpotężniejszych poruczników.$B$BUżyj Rogu szczytów, by wezwać do siebie ziemnych, i pokonaj sługi Lokena.$B$BOlbrzyma Eisenfausta znajdziesz w Sali Kształtującego na północy. Pozostałych znajdziesz głębiej na Tarasie Twórców, za schodami na północnym zachodzie.', 'Thorim chce, żebyś $gzabił:zabiła; Eisenfausta w Sali Kształtującego oraz Halefnira Zrodzonego z Wiatru i Duronna Runokutego na Tarasie Twórców.', '', 'Wróć do Thorima na Tarasie Twórców na Burzowych Szczytach.', '', '', '', '', 0),
(13037, 'koKR', 'Wspomnienia o Burzokopytym', 'Gdy Brązowe Stado obdarzyło mnie nieśmiertelnością i skierowało na ścieżkę świadka, Nozdormu powierzył mi Młot Wiedzy.$B$BReakcja młota na twoje odkrycia oznacza, że czas został tu zaburzony, a naszym obowiązkiem jest przywrócić prawdziwą linię czasu.$B$BMusimy ją odnaleźć. Na północnym zachodzie leży Głębia Kry, pradawna jaskinia grobowa wojowników z Tunka\'lo. Odszukaj ducha wodza Szybkiej Włóczni, brata Burzokopytego. Zapytaj go, co pamięta z walki swojego brata z Północnym Wiatrem.', 'Porozmawiaj z wodzem Szybką Włócznią w Głębi Kry, a potem wróć do Xarantaura w Obozie Tunka\'lo.', '', 'Wróć do Xarantaura w Obozie Tunka\'lo na Burzowych Szczytach.', 'Zapytaj wodza Szybką Włócznię o jego wspomnienia', '', '', '', 0),
(13038, 'koKR', 'Zakłócenia w czasie', 'Ten grobowiec wojowników z Tunka\'lo miał być miejscem spokoju, wolnym od grozy żywiołów.$B$BDo Głębi Kry wdarła się dziwna siła, która niepokoi duchy poległych i zaciera moje wspomnienia o własnym życiu.$B$BTo tak, jakby nasze czyny i wspomnienia były wymazywane z historii.$B$BZa życia ten totem był symbolem mojej władzy. To ostatnia prawdziwa więź, jaka łączy mnie z tym światem. Weź go, przywróć nim spokój w grobowcu, a potem zanieś go do Obozu Tunka\'lo.', 'Użyj totemu wodza, by zamknąć 4 szczeliny kry, a potem zanieś totem Xarantaurowi w Obozie Tunka\'lo.', '', 'Wróć do Xarantaura w Obozie Tunka\'lo na Burzowych Szczytach.', 'Zamknięte szczeliny kry', '', '', '', 0),
(13046, 'koKR', 'Karmienie Arngrima', 'Głód Arngrima był legendarny.$b$bNawet po śmierci na jego twarzy maluje się wygłodniałe pożądanie. Samo patrzenie na niego sprawia, że burczy ci w brzuchu.$b$bPowiadają, że przez całe życie nigdy nie był naprawdę syty i że nie było niczego, czego by nie zjadł. Zastanawiasz się, czy nie dałoby się jakoś nakarmić starego króla.$b$bLedwie ta myśl przychodzi ci do głowy, jeden z ogromnych zamarzniętych zębów wypada z głowy Arngrima, odbija się od jego brody i ląduje w twojej dłoni.', 'Nakarm Arngrima 5 bezcielesnymi jormungarami, a potem wróć do zamarzniętego wizerunku Arngrima w Dun Niffelem.$b$bUdaj się do Doliny Pradawnych Zim i użyj zęba Arngrima na tamtejszych wędrujących jormungarach. Gdy stracą ciała, walcz z nimi, aż osłabną.', '', 'Wróć do Arngrima Nienasyconego w Dun Niffelem na Burzowych Szczytach.', 'Nakarmiony duch Arngrima', '', '', '', 0),
(13047, 'koKR', 'Rozliczenie', 'Loken zabił moją żonę, obrócił mnie i moich wyznawców przeciwko sobie. Odebrał mi wszystko, co miałem, ale dziś... to się zmieni.$B$BDziś odzyskamy nasze święte ziemie. Dziś... Loken zginie.$B$BSpotkajmy się na moście przy Świątyni Mądrości, tuż na południowy zachód od Ulduaru. Tak czy inaczej, skończę z tym.$B$BPotrzebuję cię tam jako świadka. Nie pomożesz mi – to sprawa osobista.$B$BGdy będzie po wszystkim, przekaż wieści Jokkumowi, królowi mroźnych olbrzymów. To dobry przyjaciel i będzie wiedział, co robić.', 'Spotkaj się z Thorimem przy Świątyni Mądrości. Przekaż królowi Jokkumowi w Dun Niffelem, jak zakończyła się walka.', 'Świadek rozliczenia', 'Wróć do króla Jokkuma w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(13048, 'koKR', 'Tam, gdzie czas zboczył z drogi', 'Młot Wiedzy może pomóc nam naprawić szkody w linii czasu, ale tylko wtedy, gdy odkryjemy, gdzie pierwotnie wypaczono historię.$B$BZ tego, co powiedział wódz Szybka Włócznia, i z twoich odkryć w Głębi Kry wiemy, że zmiana nastąpiła mniej więcej w czasie śmierci Burzokopytego.$B$BTeraz musisz udać się do Wyjącej Kotliny, na północ od obozu, i zbadać groby, które słudzy Północnego Wiatru już zniszczyli. Młot Wiedzy zareaguje na artefakty z epoki Burzokopytego i dostroi się do właściwego czasu.', 'Użyj Młota Wiedzy na reliktach taunka, by dostroić go do czasów Burzokopytego. Gdy dostroi się do 6 reliktów z czasów Burzokopytego, wróć do Xarantaura w Obozie Tunka\'lo.', '', 'Wróć do Xarantaura w Obozie Tunka\'lo na Burzowych Szczytach.', 'Młot Wiedzy dostrojony do czasów Burzokopytego', '', '', '', 0),
(13049, 'koKR', 'Oręż bohatera', 'Nie wszystkie zapiski obozu zostały już wypaczone. Mój kostur pomógł mi znaleźć te, które odzwierciedlają prawdziwą linię czasu.$B$BWszystkie zgodnie podają, że Burzokopyty został z honorami pochowany wśród starszyzny wioski na najniższym poziomie Wyjącej Kotliny, na północy.$B$BWiększość tamtejszych grobów została już zniszczona, a ich zawartość zabrali jako trofea poddani Północnego Wiatru. Idź do kotliny i spróbuj odzyskać włócznię i zbroję Burzokopytego od potomków burzy, którzy je sobie przywłaszczyli.', 'Odzyskaj włócznię Burzokopytego i kolczugę Burzokopytego i zanieś je Xarantaurowi w Obozie Tunka\'lo.', '', 'Wróć do Xarantaura w Obozie Tunka\'lo na Burzowych Szczytach.', '', '', '', '', 0),
(13050, 'koKR', 'Veranus', 'Jeśli mam przypuścić atak na armię mojego brata, będę potrzebował czegoś, czym mógłbym się przemieszczać.$B$BLata temu wypuściłem na wolność smoczycę, na której latałem. Veranus była wspaniała. Przewodziła własnemu lęgowi – do którego teraz wróciła.$B$BOdnalezienie jej będzie trudne, ale może jest sposób. Z czystej dumy wciąż pilnuje swojego starego, pustego gniazda. Jest matką lęgu tylko z nazwy, bo dawno minął jej czas składania jaj.$B$BPrzynieś mi małe jaja z innych gniazd w pobliżu Brunnhildar. Chyba mam pewien pomysł.', 'Thorim w Świątyni Burz chce, żebyś $gzdobył:zdobyła; 5 małych jaj protosmokowca ze szczytów w pobliżu Wioski Brunnhildar.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', '', '', '', '', 0),
(13051, 'koKR', 'Naruszenie terytorium', 'Veranus jest dumna jak żadna inna bestia, jaką znam. Wciąż pilnuje swojego starego gniazda i dba o to, by żaden z młodszych protosmokowców go nie zajął.$B$BWeź zebrane jaja i połóż je w jej gnieździe. Znajdziesz je na szczycie niewielkiej góry, tuż na południowy wschód stąd.$B$BPowinienem zdołać przejąć nad nią kontrolę, zanim zabije cię w przypływie furii. Mam nadzieję.', 'Połóż skradzione jaja protosmoka w Gnieździe Matki Lęgu i wróć do Thorima w Świątyni Burz.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', 'Zwabiona Veranus', '', '', '', 0),
(13053, 'koKR', 'Poszukiwanie ocalałych', 'Gretchen Fizzlespark chce użyć mojej fruwającej maszyny, żeby poszukać ocalałych ze swojej wyprawy. Najwyraźniej sądzi, że są przetrzymywani w wiosce na północy.$B$BJest tylko jeden problem: nie mam drugiego pilota. Jeśli się zgodzisz, chętnie nauczę cię kilku sztuczek.$B$BCo ty na to, $N? Umowa stoi?', 'Pomóż Zakowi Wobblesprocketowi ukończyć lot próbny.', 'Lot próbny', 'Wróć do „Uczciwego” Maxa przy Upadku Bora na Burzowych Szczytach.', '', '', '', '', 0),
(13054, 'koKR', 'Zaginiony tropiciel', 'Nie mogę z czystym sumieniem posłać cię do jaskini worgów, nie ostrzegając, że poprzedni, kogo tam wysłaliśmy, nie wrócił.$B$BJesteśmy przygotowani na najgorsze, ale może jest szansa, że żyje. Bylibyśmy wdzięczni, gdybyś $gpomógł:pomogła; mu wrócić – tropiciel Val\'zij to jeden z nielicznych łowców, jakich mamy.', 'Poszukaj tropiciela Val\'zija w Norze Gimoraka, na południowy wschód od Miejsca Katastrofy Grom\'arsha.', '', '', '', '', '', '', 0),
(13055, 'koKR', 'Jaskiniowe lekarstwo', 'Dobrze zobaczyć przyjazną twarz. Może to ostatnia, jaką zobaczę.$B$BJeden z tych jormungarów użądlił mnie jakąś toksyną, zanim zdołałem uciec. Czuję, jak całe ciało mi drętwieje, mon.$B$BBędę potrzebował gruczołu toksyn, żeby zrobić odtrutkę. Przydadzą się też jaskiniowe grzyby, które tu rosną... spowolnią działanie toksyny.$B$BPospiesz się, proszę. Nie mam wiele czasu.', 'Tropiciel Val\'zij w Norze Gimoraka chce, żebyś $gzdobył:zdobyła; 1 gruczoł toksyn jormungara i 8 jaskiniowych grzybów.', '', 'Wróć do tropiciela Val\'zija w Norze Gimoraka na Burzowych Szczytach.', '', '', '', '', 0),
(13056, 'koKR', 'Na zemstę zawsze jest czas', 'Na razie jakoś dam radę, $N. Ale chcę cię prosić o jedną przysługę.$B$BNigdy bym nie uległ jednemu z tych robali, ale mojego powietrznego węża, Heeshę, zabił najpodlejszy worg, jakiego od dawna widziałem.$B$BNie martw się teraz o mnie, poczuję się lepiej, gdy ten worg przestanie oddychać. Znajdziesz go głębiej w jaskini.', 'Tropiciel Val\'zij chce, żebyś $gzabił:zabiła; Gimoraka w Norze Gimoraka.', '', 'Wróć do tropiciela Val\'zija w Norze Gimoraka na Burzowych Szczytach.', '', '', '', '', 0),
(13057, 'koKR', 'Taras Twórców', 'Już czas, $N. Jestem gotów stawić czoła Lokenowi.$B$BRuszajmy na Taras Twórców i zmierzmy się z siłami mojego brata. Głupiec pożałuje, że kiedykolwiek wszedł mi w drogę.', 'Odszukaj Thorima na południowo-wschodnim skraju Tarasu Twórców, tuż na północny zachód od Dun Niffelem.', '', '', '', '', '', '', 0),
(13058, 'koKR', 'Zmiana kursu wiatru', 'Nareszcie mamy wszystko, czego potrzeba, by naprawić krzywdy wyrządzone przez Północny Wiatr i jego sługi. $GDostroiłeś:Dostroiłaś; Młot Wiedzy do czasów Burzokopytego i do jego osoby.$B$BWeź znowu młot i udaj się do Świątyni Życia na równinach na północnym zachodzie. Użyj młota, by przyjąć postać Burzokopytego. Zmierz się z Północnym Wiatrem jako Burzokopyty, ale pamiętaj, że aby przywrócić linię czasu, Burzokopyty musi zginąć, gdy Północny Wiatr zacznie słabnąć.$B$BPotem musisz odnaleźć Róg furii żywiołaków i użyć go, by zniszczyć Północny Wiatr.', 'Użyj Młota Wiedzy, by cofnąć się w czasie i zmierzyć się z Północnym Wiatrem jako Burzokopyty. Gdy Burzokopyty padnie i upuści Róg furii żywiołaków, użyj go, by dobić Północny Wiatr, a potem wróć do Xarantaura w Obozie Tunka\'lo.', '', 'Wróć do Xarantaura w Obozie Tunka\'lo na Burzowych Szczytach.', 'Przywrócona prawdziwa linia czasu', '', '', '', 0),
(13060, 'koKR', 'Gdy wszystko inne zawiedzie', 'No więc... chyba nie uda nam się porządnie zadomowić w tych górach.$B$BUwierz mi, nie poddaję się łatwo... ale między zamarzającymi silnikami, paskudnymi wrykulskimi babami, terytorialnymi niby-smokami i z pół tuzina innych paskudztw, które tu osiadły, to po prostu się nie uda.$B$BAle niech cię to nie zniechęca! To, że my nie możemy się tam zadomowić, nie znaczy, że cię tam nie dostarczymy... bilety w jedną stronę to w gruncie rzeczy prosta sprawa.$B$B<Ricket kiwa głową w stronę pobliskich rakiet.>', 'Porozmawiaj z Ricket, aby skorzystać z napędowego urządzenia dostawczego D16 Ricket i przedostać się dalej w głąb Burzowych Szczytów.', '', '', '', '', '', '', 0),
(13061, 'koKR', 'Przygotuj się na chwałę', 'A więc to już. Teraz ja zajmę się twoją niedźwiedzicą, nie będzie ci potrzebna. Twoją następną próbą będzie wielki Drakkensryd.$B$BPożegnaj się z przyjaciółmi i uporządkuj swoje sprawy, bo wrócisz jako $gzwycięzca:zwyciężczyni;... albo nie wrócisz wcale.', 'Porozmawiaj z Lok\'lirą Staruchą w Wiosce Brunnhildar.', '', '', '', '', '', '', 0),
(13062, 'koKR', 'Pożegnalny dar Lok\'liry', '$GByłeś wielkim sojusznikiem:Byłaś wielką sojuszniczką;, $N. Teraz czeka cię prawdziwa próba. Będziesz potrzebować umiejętności, odwagi i odrobiny szczęścia.$B$B<Lok\'lira przywiązuje cienkie pasmo włosów do twoich.>$B$BTeraz nie możesz zawieść, siostro. Porozmawiaj z Grettą Arbiterką. Ona wyprawi cię w drogę.', 'Porozmawiaj z Grettą Arbiterką w Wiosce Brunnhildar.', '', '', '', '', '', '', 0),
(13063, 'koKR', 'Dowód godności', 'Udało ci się tam, gdzie wielu poniosło porażkę, siostro. Czy dzięki sile i odwadze, czy zwykłemu szczęściu – to się jeszcze okaże.$b$bWróć do wioski i odszukaj Astrid Bjornrittar. Opowiedz jej o swoich dokonaniach. Ale uważaj. Niełatwo jej zaimponować.', 'Brijana chce, żebyś $gudał:udała; się do Wioski Brunnhildar i $gporozmawiał:porozmawiała; z Astrid Bjornrittar.', '', '', '', '', '', '', 0),
(13064, 'koKR', 'Rywalizacja rodzeństwa', 'Sif? Czy to naprawdę ty?$b$bNie? To tylko $r? A przez chwilę...$b$bDość tego! Wizje mojej Sif dręczyły mnie o wiele za długo. Czas ją pomścić i oddać cześć jej pamięci.$b$bMój brat musi zapłacić!', 'Thorim chce, żebyś $gwysłuchał:wysłuchała; jego opowieści.', '', 'Wróć do Thorima w Świątyni Burz na Burzowych Szczytach.', 'Wysłuchana historia Thorima', '', '', '', 0),
(13108, 'koKR', 'Za wszelką cenę!', 'Tak czy inaczej, Loken padnie.$b$bNawet jeśli będę musiał sam rozerwać go na strzępy, wkrótce zapłaci za swoje nikczemne czyny.$b$bJeśli spotkasz go przede mną, zaszczyt i chwała jego pokonania przypadną tobie.$b$bWróć do mnie z jego kłamliwym językiem, a zyskasz moje błogosławieństwo i wdzięczność.', 'Król Jokkum z Dun Niffelem chce, żebyś $gwszedł:weszła; do Sal Błyskawic i $gpokonał:pokonała; Lokena. Następnie wróć do króla Jokkuma z językiem Lokena.', '', 'Wróć do króla Jokkuma w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(13109, 'koKR', 'Biegunowe przeciwieństwa', 'Powiem ci wprost, $gmaleńki:maleńka;. Mój lud nie jest już taki sam, odkąd zerwaliśmy więzi z Thorimem.$b$bJako jego przywódca niczego nie pragnę bardziej, niż by ich serca zostały uleczone, a nasza przyjaźń z Władcą Burz odnowiona. Pokonując Fjorna, $gzrobiłeś:zrobiłaś; krok na tej drodze. Chciałbym, abyś $gpoprowadził:poprowadziła; nas o krok dalej...$b$bW Salach Błyskawic zasiada ktoś jeszcze potężniejszy od Fjorna, kto sprzeciwia się samemu naszemu istnieniu. Volkhan nie spocznie, dopóki on albo my nie przestaniemy istnieć.', 'Król Jokkum w Dun Niffelem chce, żebyś $gwszedł:weszła; do Sal Błyskawic i $gpokonał:pokonała; Volkhana.', '', 'Wróć do króla Jokkuma w Dun Niffelem na Burzowych Szczytach.', 'Pokonany Volkhan', '', '', '', 0),
(13273, 'koKR', 'Po rdzeń', 'Skoro mamy już Skorupę Norgannona, zostało do odnalezienia tylko pół klucza do archiwum. Na szczęście zagoniłem Ligę Odkrywców do tropienia wszelkich poszlak co do miejsca, w którym jest Rdzeń Norgannona.$B$BDaleko na południowy wschód od Biblioteki Wynalazcy, na zboczach na północ od Dun Niffelem, jest obóz nazwany moim imieniem. Tam stacjonują przedstawiciele Ligi Odkrywców szukający drugiej połowy klucza. Przynieś mi ich mapy i notatki, a powinniśmy zdołać wytropić drugą połowę klucza.', 'Znajdź notatki poszukiwacza Khrony i mapy poszukiwacza Sorena w Obozie Branna.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z Motehą Zrodzonym z Wiatru w Miejscu Katastrofy Grom\'arsha, aby dostać nowy.', '', '', '', '', 0),
(13274, 'koKR', 'Strażnik rdzenia', 'Według notatek poszukiwacza Sorena Rdzenia Norgannona strzeże wartownik imieniem Athan, jedno z dzieł Mimira.$B$BSoren pisze, że krypta, w której przebywa Athan, nazywa się dziś „Umowa Lokena”.$B$BLoken, co? Ziemni o nim wspominali.$B$BPodobno krypta leży na południowy zachód od zniszczonego obozu Ligi Odkrywców, a jej okrągłe wejście znajduje się na zboczu góry z widokiem na Dolinę Pradawnych Zim.$B$BZnajdź tego Athana i zdobądź od niego rdzeń, ale nie zdziwiłbym się, gdyby doszło do walki.', 'Zdobądź Rdzeń Norgannona.', '', 'Użyj komunikatora Branna, aby skontaktować się z Brannem Miedziobrodym.$B$BJeśli zgubisz komunikator Branna, porozmawiaj z Motehą Zrodzonym z Wiatru w Miejscu Katastrofy Grom\'arsha, aby dostać nowy.', '', '', '', '', 0),
(13285, 'koKR', 'Wykuwanie zwornika', 'Aha! Jest: Świątynia Wynalazków, siedziba samego Opiekuna Mimira! No jasne, właśnie tam należałoby połączyć obie części klucza.$B$BWedług notatek poszukiwacza Świątynia Wynalazków to jeden z najwyżej położonych punktów po zachodniej stronie Tarasu Twórców. To znaczy, że powinna leżeć mniej więcej na wschód od waszego Miejsca Katastrofy Grom\'arsha.$B$BSpotkamy się w świątyni i połączymy części.', 'Brann Miedziobrody chce, żebyś $gspotkał:spotkała; się z nim w Świątyni Wynalazków i $gpomógł:pomogła; mu połączyć Skorupę Norgannona z Rdzeniem Norgannona. Gdy już pomożesz Brannowi, zamelduj się u Boktara Krwawej Furii na Miejscu Katastrofy Grom\'arsha.', '', 'Wróć do Boktara Krwawej Furii w Miejscu Katastrofy Grom\'arsha na Burzowych Szczytach.', 'Pomoc Brannowi w stworzeniu zwornika', '', '', '', 0),
(13415, 'koKR', 'Konsola biblioteki', 'Skorupa Norgannona jest w naszym zasięgu, $N. Zanieś dysk Wynalazcy do wnętrza biblioteki. Powinna tam być konsola, którą uruchomisz za pomocą dysku. Coś mi się zdaje, że Mimir przechowywał tam coś więcej niż tylko Skorupę Norgannona. Pewnie jest tam dość schematów, żeby zająć inżynierów z Żelaznej Kuźni na całe lata!$B$BW każdym razie użyj dysku, żeby odzyskać skorupę. Miejmy nadzieję, że Mimir nie postanowił rzucić nam pod nogi kolejnych przeszkód.', 'Zanieś dysk Wynalazcy do Konsoli Biblioteki Wynalazcy w Bibliotece Wynalazcy.', '', 'Wróć do Konsoli Biblioteki Wynalazcy na Stepach Podnóża na Burzowych Szczytach.', '', '', '', '', 0),
(13416, 'koKR', 'Konsola biblioteki', 'Skorupa Norgannona jest w naszym zasięgu, $N. Zanieś dysk Wynalazcy do wnętrza biblioteki. Powinna tam być konsola, którą uruchomisz za pomocą dysku. Coś mi się zdaje, że Mimir przechowywał tam coś więcej niż tylko Skorupę Norgannona. Pewnie jest tam dość schematów, żeby zająć inżynierów z Żelaznej Kuźni na całe lata!$B$BW każdym razie zanieś dysk do konsoli. Miejmy nadzieję, że Mimir nie postanowił rzucić nam pod nogi kolejnych przeszkód.', 'Zanieś dysk Wynalazcy do Konsoli Biblioteki Wynalazcy w Bibliotece Wynalazcy.', '', 'Wróć do Konsoli Biblioteki Wynalazcy w Bibliotece Wynalazcy na Burzowych Szczytach.', '', '', '', '', 0),
(13417, 'koKR', 'Bracia Miedziobrodzi', 'No i jest! Wreszcie mamy zwornik... Jest piękny! Objechałem świat nie raz, ale przez to cudo znowu aż się trzęsę z podniecenia. Chyba jednak nie pora teraz stać i podziwiać – musimy się stąd zmywać.$B$BWskakuj do mojej fruwającej maszyny i osłaniaj nas przed tymi żelaznymi krasnoludami, kiedy będziemy się stąd wydostawać!', 'Towarzysz Brannowi Miedziobrodemu i jego fruwającej maszynie w drodze do Mroźnej Warowni.', 'Towarzysz Brannowi Miedziobrodemu w drodze do Mroźnej Warowni.', 'Wróć do Veloga Lodowego Ryku w Mroźnej Warowni na Burzowych Szczytach.', '', '', '', '', 0),
(13420, 'koKR', 'Wiecznolód', 'Ten kawałek lodu został poddany ogromnemu ciśnieniu i działaniu naturalnej magii z głębin pod powierzchnią świata. Połączenie tych czynników dało lód, który nigdy nie stopnieje.$b$bNiewiele wiesz o takich sprawach, więc postanawiasz zanieść próbkę do Dun Niffelem. Ktoś tam na pewno zna jego właściwości.', 'Wróć do Dun Niffelem i zapytaj Caldera o kawałek wiecznolodu.', '', '', '', '', '', '', 0),
(13421, 'koKR', 'Pamiętaj o wiecznolodzie!', '', '', '', 'Wróć do Caldera w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(13422, 'koKR', 'Utrzymanie dyscypliny', 'Udało ci się tam, gdzie inni zawiedli. Ale nie możesz spocząć na laurach.$B$BMusisz pokazać innym, co naprawdę znaczą siła i oddanie.$B$BNiepokornych samców w Opuszczonej Kopalni trzeba znowu przywołać do porządku. Pokaż im, siostro... pokaż im, co znaczy nieposłuszeństwo wobec nas.', 'Gretta Arbiterka z Wioski Brunnhildar chce, żebyś $gużył:użyła; pręta dyscyplinującego na 6 wyczerpanych wrykulach w Opuszczonej Kopalni.', '', 'Wróć do Gretty Arbiterki w Wiosce Brunnhildar na Burzowych Szczytach.', 'Zdyscyplinowani wyczerpani wrykule', '', '', '', 0),
(13423, 'koKR', 'Obrona tytułu', 'Wszystkich zachwycają twoje wyczyny, siostro. Ale nie trać czujności – każda nowa pretendentka z manią wielkości ruszy do boju o twój tytuł Hyldskvinnar.$B$BPokaż tym nowicjuszkom, z czego jesteś $gzrobiony:zrobiona;.', 'Gretta Arbiterka z Wioski Brunnhildar chce, żebyś $gpokonał:pokonała; 6 zwycięskich pretendentek.', '', 'Wróć do Gretty Arbiterki w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(13424, 'koKR', 'Z powrotem do Czeluści', 'Żeby naprawdę utrzymać najlepszą formę jeździecką, musisz codziennie mierzyć się z innymi hyldnir.$B$BWróć do Czeluści Kła i pokaż im, na co cię stać. Docenią porażkę z rąk kogoś tak wprawnego jak ty.', 'Gretta Arbiterka z Wioski Brunnhildar chce, żebyś $gużył:użyła; wodzy matriarchy niedźwiedzi bojowych w Czeluści Kła i $gpokonał:pokonała; 6 niedźwiedzi bojowych z Hyldsmeet.', '', 'Wróć do Gretty Arbiterki w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(13425, 'koKR', 'Wynaturzenia muszą zginąć', 'Nie wystarczy wykazać się biegłością wśród równych sobie. Musisz też walczyć z naszymi wrogami, droga siostro.$B$BZdrajczynie z Valkyrionu wciąż drwią z naszych szlachetnych tradycji jazdy na smokowcach, hodując zarażone protosmokowce.$B$BOdbierz im olej mrozu, którego używają, i zamroź nim ich plugawe zarażone jaja.', 'Gretta Arbiterka z Wioski Brunnhildar chce, żebyś $gudał:udała; się do Valkyrionu i $gzdobył:zdobyła; fiolki oleju mrozu od kandydatek z Valkyrionu. Użyj fiolek oleju mrozu, by zniszczyć 30 zarażonych jaj protosmokowców.', '', 'Wróć do Gretty Arbiterki w Wiosce Brunnhildar na Burzowych Szczytach.', '', '', '', '', 0),
(13426, 'koKR', 'Xarantaur Świadek', 'Wygląda na to, że nie jesteśmy jedynymi przybyszami w tej okolicy. Goniec przekazał wiadomość od taurena imieniem Xarantaur, który napisał, że odwiedza wioskę taunka zwaną Obozem Tunka\'lo. Liścik był dość zagadkowy, ale wygląda na to, że ten Xarantaur przybył na Burzowe Szczyty, by poznać historię pewnej legendy taunka.$B$BSpotkaj się z nim, $N. Sprawdź, czy to, co wie, może nam w jakiś sposób pomóc. Z jego opisu wynika, że Obóz Tunka\'lo leży daleko na wschodzie, za Tarasem Twórców i na północ od Dun Niffelem.', 'Porozmawiaj z Xarantaurem w Obozie Tunka\'lo.', '', '', '', '', '', '', 0),
(13559, 'koKR', 'Danina dla Hodira', '', '', '', 'Wróć do Lillehoffa w Dun Niffelem na Burzowych Szczytach.', '', '', '', '', 0),
(13604, 'koKR', 'Dysk danych Archiwum', 'Ten platynowy dysk jest zaskakująco symetryczny, bez jednej rysy czy skazy. Wyraźne runy wyryte wzdłuż jego krawędzi układają się w słowo „ARCHIWUM”.$B$BW Ulduarze musi być urządzenie zdolne odczytać ten dysk.', 'Zanieś Dysk danych Archiwum do Konsoli Archiwum w Ulduarze.', '', 'Wróć do Konsoli Archiwum.', '', '', '', '', 0),
(13614, 'koKR', 'Algalon', 'Naprawdę ci się udało, $N. Zanieś symbole do Konsoli Archiwum i sprawdź, czy zdołasz uzyskać dostęp do Niebiańskiego Planetarium.$B$BLepiej się pospiesz, $gchłopcze:dziewczyno;. Czas nagli.', 'Zanieś Symbole Strażników do Konsoli Archiwum w Ulduarze.', '', 'Wróć do Konsoli Archiwum.', '', '', '', '', 0),
(13622, 'koKR', 'Pradawna historia', 'Fragmenty układają się w elegancki młot. Wygląda na to, że przynajmniej częściowo jest dziełem tytanów.$B$BKonsola w Archiwum może mieć jakieś informacje o tym artefakcie.', 'Zanieś Strzaskane fragmenty Val\'anyr do Konsoli Archiwum w Archiwum w Ulduarze.', '', 'Wróć do Konsoli Archiwum.', '', '', '', '', 0),
(13629, 'koKR', 'Val\'anyr, Młot Pradawnych Królów', 'Konsola Archiwum zasugerowała, jak można by ponownie połączyć fragmenty Val\'anyra: trzeba umieścić je wewnątrz fizycznej postaci istoty znanej jako Yogg-Saron.$B$BSzanse wydają się marne, ale dla artefaktu o takiej mocy ryzyko może być warte podjęcia.', 'Wrzuć strzaskane fragmenty Val\'anyra do paszczy Yogg-Sarona, gdy rzuca Ogłuszający ryk, pokonaj Yogg-Sarona i odzyskaj Przekuty Młot Pradawnych Królów.$B$BZadanie można ukończyć tylko w trybie heroicznym i tylko wtedy, gdy co najmniej jeden obserwator Ulduaru ci nie pomaga.', '', 'Wróć do Konsoli Archiwum.', '', '', '', '', 0),
(13817, 'koKR', 'Heroiczne: Dysk danych Archiwum', 'Ten platynowy dysk jest zaskakująco symetryczny, bez jednej rysy czy skazy. Wyraźne runy wyryte wzdłuż jego krawędzi układają się w słowo „ARCHIWUM”.$B$BW Ulduarze musi być urządzenie zdolne odczytać ten dysk.', 'Zanieś Dysk danych Archiwum do Konsoli Archiwum w Ulduarze.', '', 'Wróć do Konsoli Archiwum.', '', '', '', '', 0),
(13818, 'koKR', 'Heroiczne: Algalon', 'Naprawdę ci się udało, $N. Zanieś symbole do Konsoli Archiwum i sprawdź, czy zdołasz uzyskać dostęp do Niebiańskiego Planetarium.$B$BLepiej się pospiesz, $gchłopcze:dziewczyno;. Czas nagli.', 'Zanieś Symbole Strażników do Konsoli Archiwum w Ulduarze.', '', 'Wróć do Konsoli Archiwum.', '', '', '', '', 0),
(13843, 'koKR', 'Zestaw do budowy złomobota', 'Przeszukując banki danych konsoli prototypu, odkrywasz schematy zestawu do budowy złomobota. Dzięki swojej wiedzy inżynieryjnej możesz nauczyć się tego schematu i samodzielnie wytwarzać zestawy do budowy złomobota.', 'Użyj konsoli prototypu w Bibliotece Wynalazcy.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(12818, 'koKR', 'Świetnie się nadadzą, dzięki!$B$BNie $gwidziałeś:widziałaś; tam przypadkiem Dima? Wysłałem go dawno temu i nie wrócił. Mam nadzieję, że nic mu nie jest.$B$BSkoro o tym mowa... ciekawe, gdzie się podziewa Janks...', 0),
(12819, 'koKR', 'Ha, ha! To one! Serdeczne dzięki. Mam nadzieję, że przejście przez pole nie sprawiło ci zbyt wielu kłopotów.', 0),
(12820, 'koKR', 'No więc... siedzę sobie tutaj, pławiąc się we własnej wspaniałości, i nagle z oddali słyszę: pyk! Potem kolejne! A potem jeszcze tuzin! I na mojej twarzy pojawił się uśmiech na myśl o tych wszystkich magnataurach i snoboldach, które ochoczo pędziły na własną zgubę.$B$BByło wspaniale?', 0),
(12821, 'koKR', 'Doskonale!$B$B<Na twarzy Ricket pojawia się drapieżny uśmiech.>$B$BNiech zacznie się zniszczenie!', 0),
(12822, 'koKR', 'Ha, ha! To nauczy te bydlaki, żeby nie marnowały naszego czasu. Od dziś zielona skóra będzie budzić strach w sercach wszystkich magnataurów!', 0),
(12823, 'koKR', 'Cała góra się zatrzęsła! Wyglądało to cudownie? Założę się, że tak! Jak mogłoby być inaczej?$b$bA Liga Wynalazców mi mówi, że wszystkie moje wynalazki po prostu wybuchają. No pewnie, że wybuchają! Ha!', 0),
(12824, 'koKR', '$GWysadziłeś:Wysadziłaś; całe to miejsce w powietrze? Brawo! Założę się, że Rio miał z tego niezłą frajdę.$b$bNaprawdę doceniamy całą twoją pomoc, $N. Co powiesz na pamiątkę za fatygę?', 0),
(12826, 'koKR', 'No czyż to nie są najsłodsze paczuszki zniszczenia, jakie w życiu $gwidziałeś:widziałaś;?!', 0),
(12827, 'koKR', 'Mam nadzieję, że nie wzbraniały się zbytnio przed dzieleniem się dobrami. Do tej pory byliśmy dość wyrozumiali, kiedy grzebały w naszych resztkach.', 0),
(12828, 'koKR', 'I od razu dobrze wysmażone! Czasem sama siebie przechodzę.$B$BWielkie dzięki, $gprzyjacielu:przyjaciółko;!', 0),
(12829, 'koKR', 'Ha, ha! Dobrze widzieć, że nie boisz się brudnej roboty.$B$BBardzo dziękuję, $gkolego:koleżanko;!', 0),
(12830, 'koKR', 'Łaa! Ależ to cuchnie! $GMusiałeś:Musiałaś; się nieźle wziąć za łby z tymi snoboldami, co?$B$BAle naprawdę to doceniam!', 0),
(12831, 'koKR', 'To powinno wystarczyć... mam nadzieję, że Ricket coś mi z tego wyczaruje. To co, $ggotów:gotowa; do wyjścia stąd?', 0),
(12832, 'koKR', 'Dzięki za pomoc naszemu górnikowi, $N! Bez problemu powinnam zrobić odtrutkę.$B$BJak znowu wpadniesz na Tore, powiedz jej ode mnie, że jest wredna, dobra?', 0),
(12833, 'koKR', 'Lubię cię. Właściwie to jesteś czadowy!$b$bBrawo ty!', 0),
(12836, 'koKR', 'Odlotowo! Jesteś w moim typie.', 0),
(12841, 'koKR', 'Nie byłam pewna, czy wrócisz. Boję się nawet pomyśleć, co się ze mną stanie, jeśli zostanę tu dłużej.', 0),
(12843, 'koKR', 'Udało ci się! Nasi chłopcy wrócili!', 0),
(12844, 'koKR', 'Dzięki, $N! Zobaczymy, co da się uratować z tych części!', 0),
(12846, 'koKR', 'Na pewno nie jesteś z Hyldnir... więc po co tu $gprzyszedłeś:przyszłaś;? Ach... musisz szukać nowego więźnia!', 0),
(12851, 'koKR', 'Może rzeczywiście masz serce wojowniczki.$b$bCzas pokaże...', 0),
(12853, 'koKR', 'Witaj w K3!$B$BPrzybyliśmy tu, żeby przedostać się w głąb tych szczytów i zgarnąć naszą należną część tych niesamowitych maszyn tytanów. Postępy na tym polu są jednak dość mizerne. Gnole, snoboldy, magnataury... kłopotów nie brakuje... nie mówiąc już o tym, że żadna nasza maszyna latająca nie utrzyma się w powietrzu, bo silniki zamarzają.$B$BAle roboty jest mnóstwo – pomożesz, co?', 0),
(12854, 'koKR', '<Archeolog Andorin patrzy na ciebie wyczekująco.>$B$B$GMiałeś:Miałaś; wrócić z Brannem, a nie ze świstkiem papieru. Co tu się dzieje?', 0),
(12855, 'koKR', 'Ty... nie należysz do Ligi Odkrywców, a przynajmniej ja cię nie pamiętam. Ale skoro $godzyskałeś:odzyskałaś; komunikator, to pewnie oni cię przysłali. Dobrze, prawie o to mi chodziło.', 0),
(12856, 'koKR', 'Twoje starania chyba zakończyły się sukcesem, siostro.$b$bPrzyniosłaś chwałę Brunnhildar!', 0),
(12858, 'koKR', 'Wspaniale! Teraz, kiedy mamy dysk, musisz go użyć, żeby otworzyć skarbiec Wynalazcy!', 0),
(12860, 'koKR', '<Brann przygląda się dyskowi, który unosisz.>$b$bNie potrafię stwierdzić, czy coś tam jest zapisane, czy nie! Musisz mi opowiedzieć, co się stało.$b$b<Opisujesz proces pobierania danych.>$b$bCzyli zadziałało? Przynajmniej na Mimira można liczyć, że jest systematyczny. Z tego, co słyszę, tego samego nie da się powiedzieć o reszcie tych Opiekunów...', 0),
(12862, 'koKR', 'Auć! To wyglądało boleśnie. Ale wejście $gmiałeś:miałaś; całkiem okazałe, $gchłopcze:dziewczyno;!$b$bWitaj w Mroźnej Warowni! $GPrzybyłeś:Przybyłaś; pomóc nam znaleźć drogę do Lodowej Korony?', 0),
(12863, 'koKR', 'Środki medyczne? Dziękuję! Prawdę mówiąc, nie bardzo wiem, co z nimi zrobić, ale na pewno się przydadzą.$B$BMiło cię poznać... wasze ludy są tak barwnie różnorodne. Nieczęsto miewamy tu w górach gości – dobrze mieć nowe towarzystwo.', 0),
(12864, 'koKR', 'Kiedy zwiadowca tak długo nie wraca... tego właśnie należało się spodziewać. Harpie, tak?$B$BKról Burzowe Serce każe nam ciężko ćwiczyć przez cały rok... zrobił z nas wspaniałych wojowników. W takich chwilach rozumiem, czemu to konieczne. To najmądrzejszy i najsilniejszy przywódca, jakiego dotąd widziałem wśród naszego ludu... nie daj się zwieść jego brzoskwiniowej skórze.', 0),
(12865, 'koKR', 'Serdecznie dziękuję... a one na pewno też są ci wdzięczne. To potężni sprzymierzeńcy; dobrze na tym wyjdziesz, jeśli będziesz w ich łaskach.', 0),
(12866, 'koKR', 'Wiem, że to brudna robota, ale jesteśmy wdzięczni. A jak to było imię, o którym wspominał zwiadowca... Sirana?', 0),
(12867, 'koKR', 'Dobra robota, $gchłopcze:dziewczyno;. Szybko zdobywasz przyjaciół.$B$BJeśli wkrótce do nas zajrzysz, na pewno znajdziemy takiego, który pozwoli ci na sobie latać... powinny już wiedzieć, że można ci zaufać.', 0),
(12868, 'koKR', 'A więc załatwione. Dziękuję.$B$BRozmawiałem z Fjorlinem – mówi, że jego ludzie wezmą na siebie trzymanie harpii w ryzach. Dopóki znów nie odpuścimy, nie znajdą w sobie odwagi, by myśleć, że mogą atakować naszych.$B$BWiem, że to nie była najprzyjemniejsza robota – przyjmij to w dowód mojej wdzięczności.', 0),
(12869, 'koKR', 'Nie sądzę, żeby smoki dały się tak łatwo zniechęcić. Wpadnij jutro, jeśli uważasz, że możesz poświęcić więcej czasu na pomoc.', 0),
(12870, 'koKR', 'Cudeńko! $gPorządny z ciebie gość:Porządna z ciebie babka;!$B$BWychyl ze mną kufelek! Uczcijmy to wspaniałe znalezisko!', 0),
(12871, 'koKR', 'Na brodę Muradina! Czy to jest to, co myślę?! Brann tym razem naprawdę przeszedł samego siebie... ty zresztą też! Chłopaki w domu nigdy w to nie uwierzą.', 0),
(12872, 'koKR', 'To jest to! Pierwsza połowa zwornika Norgannona. Dobra robota, $N. Kiedy wrócę do Żelaznej Kuźni, dopilnuję, żeby przyjęto cię na honorowego członka Ligi Odkrywców!', 0),
(12873, 'koKR', 'Rdzeń Norgannona? Nigdy o nim nie słyszałem. Ale całkiem możliwe, że znam kogoś, kto słyszał.', 0),
(12874, 'koKR', 'Ha! Wspaniała opowieść, $gchłopcze:dziewczyno;... może masz w sobie odrobinę mroźnorodnej krwi, co? W każdym razie nie tylko gadasz, a to właśnie chciałem usłyszeć.', 0),
(12875, 'koKR', '<Drom odkasłuje trochę krwi.>$b$bRdzeń Norgannona, co? Sam spędziłem sporo dni, próbując dowiedzieć się o nim czegokolwiek, ale wygląda na to, że to jeden z reliktów, których wciąż się strzeże. I pewnie nie bez powodu.$b$bSkoro przysłał cię król Burzowe Serce, na pewno dostrzega w tobie coś szlachetnego... a ja nie jestem z tych, co odmawiają swojemu królowi.', 0),
(12876, 'koKR', 'Ponure wieści, $gchłopcze:dziewczyno;. Tych żelaznych krasnoludów chyba przybywa... widujemy je w całych górach. Czuję, że zbliża się wojna.$b$bDzięki, że $gzałatwiłeś:załatwiłaś; tę bandę... zyskaliśmy trochę czasu.', 0),
(12877, 'koKR', 'Pierścień Droma? Mam zakładać, że Drom nie ma się dobrze, skoro nie przedstawił cię osobiście. Przykro mi to słyszeć. Drom to szlachetny krasnolud, choć ciekawski.$b$bW jakiej zatem sprawie przybywasz?', 0),
(12878, 'koKR', '<Gdy skrzynia się otwiera, do komnaty wdziera się powietrze, niosąc stęchłą woń czegoś, co leżało tu przez niezliczone lata. Na dnie skrzyni spoczywa Rdzeń Norgannona, nietknięty przez wieki.>', 0),
(12879, 'koKR', 'Ktoś używa Kuźni Woli, by stworzyć tę armię... Ulduar nie jest już bezpieczny.$b$b$N, cieszy mnie, że $gzdołałeś:zdołałaś; dotrzeć do rdzenia przed tymi plugastwami.', 0),
(12880, 'koKR', 'Jesteś $ggenialny:genialna;, $gchłopcze:dziewczyno;! $GGenialny:Genialna;! To będzie naprawdę wspaniały dzień.$b$bSzybko, daj mi rdzeń, zanim te żelazne krasnoludy tu zejdą.', 0),
(12882, 'koKR', 'Świetnie się nadadzą! Jestem ci bardzo zobowiązany. Może łyk czegoś za fatygę?', 0),
(12885, 'koKR', 'A więc znasz Branna Miedziobrodego? To nasz najbliższy sojusznik spośród istot z ciała. Jesteśmy jak bracia w walce z Lokenem i jego poplecznikami, w walce o Ulduar.', 0),
(12886, 'koKR', 'Sif... to ty?', 0),
(12888, 'koKR', '<Przeprowadzasz naprawy wskazane przez kartę dostępu. Po ich zakończeniu zamykasz panel serwisowy i przestawiasz włącznik zasilania.>', 0),
(12889, 'koKR', 'Przyglądasz się wyświetlaczowi naprawionej konsoli prototypu. Co najmniej jeden ze schematów Mimira przetrwał najwyraźniej długi okres między cyklami konserwacji. Z diagramów i instrukcji w pliku schematu bez trudu dasz radę zbudować przedstawionego mechagnoma.', 0),
(12895, 'koKR', 'Oczywiście przy naszym szczęściu pewnie mogłem to przewidzieć. Cóż, nie pozwolimy mu tak łatwo się wymknąć. Zobaczmy, co jest w tym liściku.', 0),
(12900, 'koKR', 'Świetnie się nadadzą. Uprząż będzie gotowa w mgnieniu oka.', 0),
(12905, 'koKR', 'Czekałam na zastępstwo dla jednej z moich nadzorczyń. Najwyższy czas, żebyś się zjawiła.$B$BWeźmy cię do roboty.', 0),
(12906, 'koKR', 'Nieźle jak na nową nadzorczynię. Mam dla ciebie kolejne zadanie, jeśli czujesz się dziś odważna.', 0),
(12907, 'koKR', 'Jeśli, kiedy się tu zjawiłaś, miałam jakiekolwiek wątpliwości co do twojego zaangażowania, to już ich nie mam. Jeszcze trochę wysiłku, a mogłabyś na stałe dołączyć do mojej załogi.', 0),
(12908, 'koKR', 'Wiedziałam, że wrócisz! Uwolnij mnie z tych kajdan, a pomogę ci znaleźć goblina.', 0),
(12909, 'koKR', 'Więc Boktar zgłosił Odmrożenie do jakiegoś zadania, co? No, to lepiej, żeby to było coś ważnego. Dobrze wie, że nie próbuje się rozdzielać łowczyni z jej zwierzakiem!', 0),
(12910, 'koKR', '<Gdy włączasz komunikator, pojawia się obraz krasnoluda. To może być tylko Brann Miedziobrody.>$b$b<Sądząc po minie, Brann jest zaskoczony twoim widokiem i zaczyna gorączkowo gestykulować.>', 0),
(12913, 'koKR', 'Bartok nie będzie zadowolony, że nie $gznalazłeś:znalazłaś; Branna, ale przynajmniej nie $gwróciłeś:wróciłaś; z pustymi rękami. A teraz zobaczmy, co da się zrobić z tym bełkoczącym krasnoludem.', 0),
(12915, 'koKR', 'A więc to już się stało.$b$bMiejmy nadzieję, że to wystarczy.', 0),
(12917, 'koKR', 'Teraz powinno ci się udać porozumieć z krasnoludem. Zapytaj Boktara, czego od ciebie potrzebuje. Nie ma czasu do stracenia.', 0),
(12920, 'koKR', '<Boktar słucha, jak opisujesz rozmowę z Brannem.>$b$bW słowach krasnoluda jest prawda. Plan Vor\'takha to nie jest droga Hordy. Jeśli Brann Miedziobrody zna sposób, by powstrzymać te żelazne krasnoludy i ich patrona, to w naszym interesie leży mu pomóc.', 0),
(12921, 'koKR', 'Jesteś – dobrze. Chyba wiem, gdzie jest twój goblin.', 0),
(12922, 'koKR', 'Kładziesz metal na kowadle, a gdy tylko dodajesz iskry, zaczynają zawzięcie obrabiać rudę.$b$bGdy w końcu się wypalają, zostaje ci duży kawał metalu lśniący własnym światłem.', 0),
(12924, 'koKR', 'Wygląda na to, że znacznie udoskonaliłem swoją technikę. Albo prawdziwe są legendy otaczające to kowadło.$b$bTa zbroja przewyższa poprzednią, a do jej wykonania potrzeba było mniej materiału.$b$bZ nadwyżki udało mi się wykuć dla ciebie drobiazg jako zapłatę za pomoc.', 0),
(12925, 'koKR', 'Dziękujemy ci, siostro. Nie możemy pozwolić, by nasze chlubne tradycje zostały splugawione.', 0),
(12926, 'koKR', 'Szybko poszło! Teraz, kiedy mamy dysk, musimy się dowiedzieć, jak go użyć, żeby odblokować pierwszą połowę klucza do archiwum.', 0),
(12927, 'koKR', '<Brann przygląda się dyskowi, który unosisz.>$b$bNie potrafię stwierdzić, czy coś tam jest zapisane, czy nie, $gchłopcze:dziewczyno;. Musisz mi opowiedzieć, co się stało.$b$b<Opisujesz proces pobierania danych.>$b$bCzyli zadziałało? Przynajmniej na Opiekuna Mimira można liczyć, że jest systematyczny.', 0),
(12928, 'koKR', 'To jest to! Pierwsza połowa zwornika Norgannona. Dobra robota, $N. Od dawna kazałem archeologowi Andorinowi wypatrywać wskazówek, gdzie może być skorupa. Nigdy mi nie uwierzy, kiedy mu powiem, że zamiast niego $gznalazł:znalazła; ją jakiś $gnieustraszony śmiałek:nieustraszona śmiałkini;.', 0),
(12929, 'koKR', 'A więc znasz Branna Miedziobrodego? To nasz najbliższy sojusznik spośród istot z ciała. Jesteśmy jak bracia w walce z Lokenem i jego poplecznikami, w walce o Ulduar.', 0),
(12930, 'koKR', 'Dzięki temu opatrzymy więcej poległych. Dziękuję ci, $N, w imieniu wszystkich obrońców schronienia.', 0),
(12931, 'koKR', '$GDałeś:Dałaś; obrońcom powód do radości. Widok wrogów padających z twojej ręki dodał im sił i odwagi.', 0),
(12937, 'koKR', 'Wojownicy, których $guleczyłeś:uleczyłaś;, pomogą nam jeszcze dłużej utrzymać linię obrony. Jeśli naprawdę mamy uwolnić się od żelaznego zagrożenia, musimy znaleźć sposób, by uderzyć w nich na tyłach.', 0),
(12942, 'koKR', 'Val\'kyrie to nic innego jak pieski Króla Lisza. Zostaną zgładzone jak szumowiny, którymi są. Dokonały wyboru, teraz muszą żyć z jego konsekwencjami.', 0),
(12953, 'koKR', 'To się nazywa poświęcenie! Te zdrajczynie mają może teraz nowego pana, ale nigdy nie zapomną pożegnalnego prezentu od swoich sióstr.', 0),
(12956, 'koKR', 'Gdy pokazujesz rudę, zauważasz, że surowe oblicze Thorima rozjaśnia się, jakby ją rozpoznał.', 0),
(12957, 'koKR', 'Miałem nadzieję, że więcej uwolnionych zdecyduje się do nas dołączyć, ale nie mam im tego za złe. Chętni sojusznicy trafiają się rzadko, a my jesteśmy wdzięczni, że $gużyczyłeś:użyczyłaś; ostrza naszej sprawie.', 0),
(12964, 'koKR', '<Bouldercrag wyciąga rękę po rudę, ale zaraz ją cofa.>$B$BTa ruda... Nie mogę jej dotknąć. Kipi od nienaturalnej energii. Żadna istota z kamienia nie jest w stanie jej dotykać. Co oni zamierzają z nią zrobić?', 0),
(12965, 'koKR', '<Bouldercrag ponuro kiwa głową.>$B$BZnacznie $gosłabiłeś:osłabiłaś; burzowiernych, ale będą walczyć dalej. Ich straty nic dla nich nie znaczą, a nasi obrońcy wciąż padają. Nawet jeśli będzie ich to kosztować sto czy tysiąc żelaznych trupów, będą walczyć, dopóki nie zetrą nas na żwir.', 0),
(12966, 'koKR', 'Przekucie zbroi Thorima? Da się zrobić.$b$bNajpierw jednak trzeba się zająć kowadłem...', 0),
(12967, 'koKR', 'Zaszczytna postawa, $N. Powiadomię króla o twojej pomocy.$b$bKowadło już prawie wystygło. Zobaczymy się wkrótce w Dun Niffelem.', 0),
(12968, 'koKR', 'Yulda sobie na to zasłużyła. Nikomu nie uchodzi na sucho znieważanie Hyldsmeet. Nawet jednej z nas.', 0),
(12969, 'koKR', 'Dobra robota, młoda. Wygląda na to, że obie strony wywiązały się z umowy.', 0),
(12970, 'koKR', 'A więc postanowione. Weźmiesz udział w Hyldsmeet i z moją pomocą przywrócisz wielkiego Thorima na należne mu miejsce.', 0),
(12971, 'koKR', 'Udało ci się, $N. Pokonałaś jedne z najzacieklejszych wojowniczek, jakie ma do zaoferowania rasa Hyldnir.', 0),
(12972, 'koKR', 'Myślisz, że ot tak damy ci własnego niedźwiedzia? Najpierw musisz się wykazać, zanim cokolwiek od nas dostaniesz.$B$BNie myśl o sobie zbyt wiele tylko dlatego, że pokonałaś kilka pretendentek w Hyldsmeet.', 0),
(12973, 'koKR', 'Król Burzowe Serce przesyła najszczersze podziękowania za to, że $gpołączyłeś:połączyłaś; go z braćmi. Wygląda na to, że wyruszył wyrównać jakieś porachunki – może spotkasz go znowu u progu Arthasa.', 0),
(12975, 'koKR', 'Kolejny dobry uczynek, którego $gdokonałeś:dokonałaś; w imieniu Thorima, $N.$b$bTo pomoże zmiękczyć serca mojego ludu wobec niego.', 0),
(12976, 'koKR', '<Oczy Njormelda wyraźnie wilgotnieją, gdy wysypuje zawartość worka na kowadło.>$b$bRóg Hodira...$b$bTo był święty dar dla naszego ludu od samego Hodira, $N. To relikwia o wielkim znaczeniu dla nas.$b$bKiedy następnym razem wrócisz do naszej twierdzy, ujrzysz owoce swojej pracy.$b$bBywaj.', 0),
(12977, 'koKR', 'Wypełnia cię poczucie spokoju i zadowolenia, bo wiesz, że niegdyś udręczone dusze z Gromospadu spoczywają teraz w pokoju.', 0),
(12978, 'koKR', 'Może jest jeszcze nadzieja na zwycięstwo, $N. Nigdy nie zdołaliśmy utrzymać natarcia na burzowiernych, ale dzięki twoim wysiłkom Valduran może jeszcze polec!', 0),
(12979, 'koKR', 'Ostrożnie. Trzymaj tę płytę jak najdalej ode mnie. Sama jej bliskość wystarcza, żeby zadać ból.$B$BAle masz rację, $N, to gigantyczne płyty pancerne jak na golema bojowego zwykłych rozmiarów. Do czego burzowierni mogliby ich potrzebować? Jest tylko jeden sposób, żeby się przekonać.', 0),
(12980, 'koKR', '<Bruor słucha, jak opisujesz, czego $gdowiedziałeś:dowiedziałaś; się w warsztacie.>$B$BWięc pan Valdurana dał mu ten złowrogi metal, żeby zbudował gigantyczną broń? To nią zamierza zadać nam ostateczny cios! Musimy go powstrzymać, zanim ją ukończy i spuści na nas.', 0),
(12981, 'koKR', 'Czujesz satysfakcję, gdy uświadamiasz sobie, że twoje wysiłki wciąż umacniają odnowione więzi między Thorimem a Synami Hodira.', 0),
(12983, 'koKR', 'Robi wrażenie. Nie sądziłam, że jeszcze kiedyś zobaczę matriarchę lodopysków. Zwłaszcza tak dużą.', 0),
(12984, 'koKR', 'Nareszcie Valduran nie żyje, a burzowierni są osłabieni, ale jeśli jego przechwałki są prawdziwe, musimy dalej walczyć z burzowiernymi bez niego. Broń, którą budują, może oznaczać nasz koniec.', 0),
(12985, 'koKR', 'To już prawie koniec.$b$bGdy ten artefakt stanie na swoim miejscu, Dun Niffelem zostanie ostrzeżone przed nadciągającymi zagrożeniami, zanim do nas dotrą.', 0),
(12986, 'koKR', 'Wieści, które przynosisz, są doprawdy ponure. Nie znam losu pozostałych strażników, lecz ich nieobecność zwiastuje mroczne czasy dla wszystkich ziem Azeroth.$b$bZbadam wiedzę zawartą w banku danych, który $gprzyniosłeś:przyniosłaś;, i spróbuję w pełni ocenić sytuację. Sądzę jednak, że posiadam wiedzę, którą w tej chwili uważasz za ważniejszą, dlatego pozwolę ci najpierw z niej skorzystać.', 0),
(12987, 'koKR', '<Njormeld spogląda w górę na Hełm Hodira, wyraźnie wzruszony.>$b$bDobra robota, $gmaleńki:maleńka;.$b$bDobra robota...', 0),
(12988, 'koKR', 'Świetna robota! Och, to nie powstrzyma żelaznych krasnoludów, ale odbudowa tych kuźni zajmie im cenny czas. Śmiem twierdzić, że zyskaliśmy przewagę.', 0),
(12989, 'koKR', 'Jormungary to podłe stworzenia. Dobrze $gzrobiłeś:zrobiłaś;, że je $gzniszczyłeś:zniszczyłaś;.', 0),
(12991, 'koKR', 'Były czasy, kiedy nie potrafiłbym poprosić nikogo o to, co $gzrobiłeś:zrobiłaś;, ale doświadczenia z żelaznymi krasnoludami zgasiły we mnie te uczucia. Kupiliśmy sobie czas przed natarciem wroga.', 0),
(12993, 'koKR', '<Bouldercrag zaczyna przeglądać dokumenty, a oczy robią mu się coraz większe.>$B$BNie miałem pojęcia, że żelaźni są do tego zdolni! Nasi nie będą mieli żadnych szans z tym behemotem, jeśli zostanie ukończony. Na szczęście wygląda na to, że wciąż brakuje im kluczowej części.', 0),
(12994, 'koKR', 'Gdy zakładasz łańcuch z powrotem na szyję matki legowiska, ta z aprobatą liże cię po twarzy.', 0),
(12996, 'koKR', 'Nieźle. Liczyłam, że Kirgaraak skręci ci kark i zatrzymam twoją niedźwiedzicę.$B$BŻartuję, siostro. No... pół żartem. Masz naprawdę wspaniałą niedźwiedzicę.', 0),
(12997, 'koKR', 'Naprawdę ci się udało! $GWyszedłeś:Wyszłaś; z tego $gcały i zdrowy:cała i zdrowa;. Szkoda, że nie da się tego powiedzieć o twojej niedźwiedzicy.$B$BTrochę potrwa, zanim dojdzie do siebie. Na szczęście przez jakiś czas nie będzie ci potrzebna.', 0),
(12998, 'koKR', 'Skoro serce trafiło w ręce Narvira, kolos osiągnie pełną moc! Nie będziemy mieli wyboru, trzeba będzie z nim walczyć.', 0),
(13000, 'koKR', 'Te futra są dość... duże. Nie chciałabym spotkać worgów, z którymi $gmusiałeś:musiałaś; się zmierzyć.$b$bWszyscy jesteśmy ci bardzo wdzięczni. Temperatura już zaczyna spadać.', 0),
(13001, 'koKR', 'Odsuń się i patrz, jak spełnia się proroctwo!', 0),
(13003, 'koKR', 'Dokonało się.$b$b$GSpojrzałeś:Spojrzałaś; pewnej śmierci w oczy i $gwyszedłeś:wyszłaś; z tego zwycięsko.$b$bPokonując w pojedynkę tak potężną bestię, $gprzyniosłeś:przyniosłaś; Dun Niffelem wielką chwałę!', 0),
(13005, 'koKR', 'To dobry początek. Ale siły mojego brata szybko się przegrupują. Nasze zwycięstwo musi być rozstrzygające.', 0),
(13006, 'koKR', 'Gdy pokrywasz hełm cienką warstwą oleju, szron odpada, a powierzchnia zaczyna lśnić.', 0),
(13007, 'koKR', 'Udało się, naprawdę się udało! Schronienie ocalało, a burzowierni zostali pokonani! Musimy ostrzec Branna, zanim Lokenowi przyjdzie do głowy odbudować swoje siły. Jedynym sposobem, by utrwalić zwycięstwo, które dziś $godniosłeś:odniosłaś;, jest wejście do Ulduaru i pokonanie Lokena raz na zawsze!', 0),
(13009, 'koKR', '<Gdy wręczasz Thorimowi przekutą zbroję, jej wspaniałość wyraźnie go porusza.>$b$bDobrze się $gspisałeś:spisałaś;, ale wiele jeszcze zostało do zrobienia.', 0),
(13010, 'koKR', 'Słowa nie wyrażą mojej wdzięczności, $N.$b$b$GSłużyłeś:Służyłaś; mi z honorem. Przyjmij, proszę, ten dowód mojej wdzięczności.', 0),
(13011, 'koKR', 'A więc dokonało się.$b$bSłyszeliśmy wrzaski Jormuttar, które niosły się echem przez całą dolinę.$b$b$GOddałeś:Oddałaś; dziś naszemu ludowi przysługę, $gmaleńki:maleńka;.', 0),
(13034, 'koKR', 'Jakie to dziwne... to zupełnie nie przypomina opowieści, którą usłyszałem od poskromicielki wiatru Barah.', 0),
(13035, 'koKR', 'Jeden po drugim słudzy mojego brata padają. Rebelia Lokena wkrótce dobiegnie końca.', 0),
(13037, 'koKR', 'Nawet wódz zaczyna tracić wspomnienia? Przeszłość jest przepisywana na naszych oczach, a jeśli nie odkryjemy, kto za tym stoi, całe dziedzictwo Burzokopytego może przepaść na zawsze.', 0),
(13038, 'koKR', 'Duch wodza kazał ci mi to przynieść?$b$b<Xarantaur ogląda totem.>$b$bAch, rozumiem, o co mu chodziło. Każąc ci zamknąć tym totemem szczeliny w głębi, dał nam wskazówkę, co dzieje się z linią czasu. Mądry z niego wódz, ten Szybka Włócznia – czuwa nad swoim ludem nawet po śmierci.', 0),
(13046, 'koKR', 'Gdy osadzasz ząb w szczęce Arngrima, odnosisz wrażenie, że udało ci się złagodzić napady głodu starego króla... przynajmniej na razie.', 0),
(13047, 'koKR', 'Nie... to niemożliwe...$B$BNikt nie pokona Thorima w pojedynku. Ani olbrzym, ani bestia... nikt! A już na pewno nie ten tchórz, jego brat.$B$BNa imiona moich praojców, przysięgam...$B$BLoken za to zapłaci!', 0),
(13048, 'koKR', '<Xarantaur odbiera od ciebie Młot Wiedzy.>$b$bNareszcie ustaliliśmy, kiedy w dziejach żył Burzokopyty. Dzięki tej wiedzy możemy przywrócić linię czasu.', 0),
(13049, 'koKR', 'Mamy szczęście, że $godzyskałeś:odzyskałaś; je w całości, $N. Dzięki nim mogę użyć Młota Wiedzy, by posłać cię w przeszłość, do chwili, w której Północny Wiatr zaczął wypaczać prawdziwą linię czasu. To jedyny sposób, by przywrócić prawdziwą historię tego miejsca.', 0),
(13050, 'koKR', 'Tak... te się nadadzą. Miejmy nadzieję, że mój plan się powiedzie, $N.$B$BVeranus to wspaniała smoczyca. Nie chciałbym zadowalać się gorszą.', 0),
(13051, 'koKR', 'Dobrze mieć z powrotem starą przyjaciółkę. Wygląda na to, że szczęście w końcu zaczyna mi sprzyjać... a wszystko dzięki tobie, $gmały przyjacielu:mała przyjaciółko;.', 0),
(13054, 'koKR', 'Bardzo boli, mon. Nie wiem, czy z tego wyjdę.', 0),
(13055, 'koKR', 'Dziękuję ci, mon. Teraz może przeżyję kolejny dzień.', 0),
(13056, 'koKR', 'Już czuję się dużo lepiej, mon. Nie wiem, czy to od odtrutki, czy od wieści, że ten parszywy worg dostał, na co zasłużył.', 0),
(13057, 'koKR', 'Jesteśmy na miejscu, $N. Siły mojego brata poznają dziś smak porażki.', 0),
(13058, 'koKR', 'To, czego dziś $gdokonałeś:dokonałaś;, sprawi, że Burzokopyty i jego historia nigdy nie zostaną zapomniani. Co więcej, $gwpisałeś:wpisałaś; się na karty historii Azeroth. Zapamiętam i spiszę twoje dokonania na całą wieczność.', 0),
(13060, 'koKR', '<Olut się krzywi.>$b$bTo wyglądało boleśnie. Ale wejście było całkiem efektowne.$b$bPrzybywasz, żeby pomóc nam znaleźć drogę do Lodowej Korony? Jak widać, nasza pierwsza wyprawa w tamtą stronę nie skończyła się zbyt chwalebnie. Myślę, że lepiej byłoby wedrzeć się tam z innej strony.', 0),
(13061, 'koKR', 'Naprawdę $gzaszedłeś:zaszłaś; tak daleko. Nigdy bym nie pomyślała, że tak szybko zrobisz postępy wśród hyldnir.', 0),
(13062, 'koKR', '$GGotów:Gotowa; do lotu, siostro? Stąd nie ma odwrotu.', 0),
(13063, 'koKR', 'A więc, siostro, myślisz, że wykonanie kilku prostych zadań czyni cię bohaterką?$b$bJeszcze się przekonasz...', 0),
(13064, 'koKR', 'Znasz teraz nieco historii tej krainy... mojej krainy.$b$bWzywam cię, byś $gpomógł:pomogła; mi naprawić te krzywdy.', 0),
(13108, 'koKR', 'Ten podły robak nie żyje?$b$b$GOkazałeś:Okazałaś; się wielkim błogosławieństwem dla mojego ludu, $gmaleńki:maleńka;.$b$bPrzyjmij, proszę, ten dar w podzięce za twoją wierną przyjaźń.', 0),
(13109, 'koKR', 'Volkhan nie będzie już nawiedzał snów mojego ludu.$b$bNie ustawaj w wysiłkach, $gmaleńki:maleńka;. Jestem pewien, że z czasem mój lud przebaczy Thorimowi.', 0),
(13273, 'koKR', 'Zniszczony? Jak to, obóz zniszczony?$B$B<Brann zaciska pięści w gniewie.>$B$BTe żelazne krasnoludy za to zapłacą! Niewiele możemy teraz zrobić, musimy się skupić na ukończeniu klucza. Ale gdy tylko dostanę się do sal Ulduaru, żelaźni i ich panowie odpowiedzą za to, co zrobili!', 0),
(13274, 'koKR', 'To naprawdę to! Klucz jest niemal w naszym zasięgu. Potrzebujemy już tylko sposobu, by połączyć skorupę i rdzeń w jeden klucz. Zobaczmy, co poszukiwacz Soren miał na ten temat do powiedzenia...', 0),
(13285, 'koKR', '<Boktar kiwa głową z aprobatą, gdy opowiadasz mu, jak $gpomogłeś:pomogłaś; Brannowi odzyskać części zwornika i je połączyć.>$B$BBrann może się okazać dokładnie takim sojusznikiem, jakiego potrzebujemy, by odkryć, co naprawdę dzieje się w Ulduarze. Dobrze $gzrobiłeś:zrobiłaś;, pomagając mu. Potrzebujemy każdej pomocy przeciwko temu Lokenowi i jego sługom, żelaznym krasnoludom.', 0),
(13415, 'koKR', '<Wkładasz dysk do konsoli. Nagle na jej powierzchni zapalają się światła i odzywa się mechaniczny głos.>$b$bDysk Wynalazcy uwierzytelniony. Witaj z powrotem, Opiekunie Mimirze.', 0),
(13416, 'koKR', '<Wkładasz dysk do konsoli. Nagle na jej powierzchni zapalają się światła i odzywa się mechaniczny głos.>$b$bDysk Wynalazcy uwierzytelniony. Witaj z powrotem, Opiekunie Mimirze.', 0),
(13420, 'koKR', '<Wiecznolód połyskuje odbiciem w oku Caldera, gdy ten unosi go wysoko.>$b$bAch, wiecznolód. Symbol serca naszego ludu...$b$bNiegdyś wiecznolodu było w tej okolicy pod dostatkiem. Przez wieki jednak jormungary pożarły prawie cały. Teraz jest bardzo rzadki i bardzo cenny dla mojego ludu.$b$bPodczas wędrówek po tych ziemiach wypatruj kolejnych kawałków wiecznolodu. Wróć do mnie z każdym, który znajdziesz, a będziemy ci bardzo wdzięczni.', 0),
(13421, 'koKR', 'Dobra robota, $gmaleńki:maleńka;.$B$BNiegdyś wiecznolodu było w tej okolicy pod dostatkiem. Przez wieki jednak jormungary pożarły prawie cały. Teraz jest bardzo rzadki i bardzo cenny dla mojego ludu.$B$BPodczas wędrówek po tych ziemiach wypatruj kolejnych kawałków wiecznolodu. Wróć do mnie z każdym, który znajdziesz, a będziemy ci bardzo wdzięczni.', 0),
(13422, 'koKR', 'Wciąż dajesz innym przykład. Podziwiamy cię, $gbracie:siostro;.', 0),
(13423, 'koKR', 'Wciąż udowadniasz, że jesteś $ggodny:godna;. Twoja obecność to dla nas zaszczyt.', 0),
(13424, 'koKR', 'Wciąż pokazujesz swoją biegłość. Twoje siostry nie straciły dla ciebie szacunku.', 0),
(13425, 'koKR', 'Przewodzisz nam pod wieloma względami. Dziękujemy ci, $gbracie:siostro;.', 0),
(13426, 'koKR', 'A więc Boktar dostał mój liścik? To wspaniała wiadomość. Wątpiłem, czy goniec taunka, który go niósł, do kogokolwiek dotrze.', 0),
(13446, 'koKR', 'Zbezcześć wielkie ognisko Przymierza na Burzowych Szczytach!', 0),
(13455, 'koKR', 'Zbezcześć wielkie ognisko Hordy na Burzowych Szczytach!', 0),
(13490, 'koKR', 'Uczcij płomień Burzowych Szczytów!', 0),
(13498, 'koKR', 'Uczcij płomień Burzowych Szczytów!', 0),
(13559, 'koKR', 'Synowie Hodira przyjmują twoją daninę, $gmaleńki:maleńka;. Wciąż udowadniasz, że pod wieloma względami jesteś cennym sojusznikiem.', 0),
(13629, 'koKR', 'Potwierdzono integralność obiektu. Proszę czekać na usunięcie zestalonych pozostałości.', 0),
(13843, 'koKR', 'Notujesz informacje przedstawione na schemacie oraz materiały potrzebne do skonstruowania zestawu złomobota.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(10283, 'koKR', 'Kim jesteś?', 0),
(12818, 'koKR', 'Musimy mieć coś, czym zaizolujemy silniki przed tym zimnem... myśl, Jeer, myśl!$B$BO, hej! $GZdobyłeś:Zdobyłaś; dla mnie trochę tego złomu?', 0),
(12819, 'koKR', 'Gdyby Janks tu był, mógłbym po prostu jego wysłać na tę wyprawę. O... chociaż, jak się zastanowić... nie jestem pewien, czy w ogóle mu powiedziałem, gdzie jest bezpieczna ścieżka.$B$BDobrze, że mam pod ręką takich zaradnych poszukiwaczy przygód jak ty, co?', 0),
(12820, 'koKR', 'Mam nadzieję, że $gdorwałeś:dorwałaś; też trochę ich obrzydliwych małych kumpli snoboldów?', 0),
(12821, 'koKR', 'Nawet magnataury powinny wiedzieć, że z goblinami się nie zadziera.', 0),
(12822, 'koKR', 'Nic nie budzi we wrogu takiego strachu jak gobliński saper!', 0),
(12823, 'koKR', 'Ten ładunek to moje dziecko... dopracowywałem go tygodniami. TYGODNIAMI!$B$BTo kawał czasu... no dobra.', 0),
(12826, 'koKR', 'Jeer skończył miny? Pięknie.', 0),
(12827, 'koKR', 'Znowu cześć! Burczy mi w brzuchu... jak poszło?', 0),
(12828, 'koKR', 'Wiem, że mój plan był genialny. Nawet się nie przejmuj.$B$BJak się czujesz w obecności wielkości? Może trochę mrowi?', 0),
(12829, 'koKR', 'Uważaj przy tym dozowniku! To niebezpieczne ustrojstwa.', 0),
(12830, 'koKR', 'Masz dla mnie rudę?', 0),
(12831, 'koKR', '<Ranny gobliński górnik wije się z bólu.>', 0),
(12832, 'koKR', 'Rozumiem, że w pieczarze wszystko poszło dobrze? Tore była dla ciebie miła?', 0),
(12833, 'koKR', 'Bum! Ha, ha!', 0),
(12836, 'koKR', 'Lubię Ricket, bo jest taaaka słodka!$B$BO, znowu cześć! Jak idzie tępienie szkodników?', 0),
(12841, 'koKR', 'Moje runy, $N? Masz je?', 0),
(12843, 'koKR', '$GZnalazłeś:Znalazłaś; naszych mężczyzn, $N?', 0),
(12844, 'koKR', 'Masz szczęście z naszym sprzętem, $N?', 0),
(12851, 'koKR', '$GPrzeżyłeś:Przeżyłaś; bitwę, $N?', 0),
(12854, 'koKR', '$GZnalazłeś:Znalazłaś; obóz Branna?', 0),
(12855, 'koKR', 'Kim jesteś?', 0),
(12856, 'koKR', 'Twoja misja się powiodła, $gbracie:siostro;?', 0),
(12858, 'koKR', '$GUkończyłeś:Ukończyłaś; dysk?', 0),
(12860, 'koKR', '$GUżyłeś:Użyłaś; dysku? Co $gznalazłeś:znalazłaś;?', 0),
(12863, 'koKR', 'Witaj.', 0),
(12865, 'koKR', 'Te ptaki od dawna są nam wierne... całkiem nieźle się dogadujemy.', 0),
(12866, 'koKR', 'Uparte bestie... nigdy nie udaje nam się pozbyć ich wszystkich. Mnożą się jak króliki.', 0),
(12867, 'koKR', 'Rozprawimy się z tym problemem harpii... orły już wkrótce znów będą mogły swobodnie szybować po niebie.', 0),
(12868, 'koKR', 'Jest tu za zimno na zwykłe szkodniki... więc mamy harpie. Szczęściarze z nas.', 0),
(12869, 'koKR', 'To zupełnie wymknęło się spod kontroli.', 0),
(12870, 'koKR', '$GZnalazłeś:Znalazłaś; dla mnie trochę tych reliktów?', 0),
(12872, 'koKR', 'No nie stój tak, pokaż mi skorupę!', 0),
(12874, 'koKR', '$GWróciłeś:Wróciłaś; do mnie. Czy wracasz jako zwycięzca?', 0),
(12876, 'koKR', 'Zwiadowcy mieli rację? Były tam krasnoludy?', 0),
(12877, 'koKR', 'Witaj, $N.$b$bCieszy mnie, że zawierając ze mną znajomość, $gpostanowiłeś:postanowiłaś; posłużyć się językiem, a nie ostrzem. Ostatnio zauważam, że to przymiot coraz rzadszy wśród twoich pobratymców.', 0),
(12879, 'koKR', 'Ktoś używa Kuźni Woli, by stworzyć tę armię... Ulduar nie jest już bezpieczny. $N, czy $godzyskałeś:odzyskałaś; rdzeń?', 0),
(12880, 'koKR', 'Hej, $gchłopcze:dziewczyno;! Miło cię poznać osobiście. $GZnalazłeś:Znalazłaś; go?', 0),
(12882, 'koKR', 'Udało ci się znaleźć relikty, o których mówiłem?', 0),
(12886, 'koKR', 'Precz!', 0),
(12888, 'koKR', '<Otwierasz panel serwisowy ZŁOM-E.>', 0),
(12895, 'koKR', 'Udało ci się znaleźć obóz Miedziobrodego?', 0),
(12900, 'koKR', 'Znalazłaś już skóry? Yeti znajdziesz na wzgórzach poniżej.', 0),
(12906, 'koKR', 'Załatwione? Mam nadzieję, że nie zabiłaś za wielu tych kundli. Potrzebujemy rąk do pracy.', 0),
(12907, 'koKR', 'Wróciłaś. Zabiłaś tę niesubordynowaną świnię?', 0),
(12908, 'koKR', 'Najwyższy czas.', 0),
(12910, 'koKR', 'Kim... kim ty jesteś?', 0),
(12915, 'koKR', 'Czy Fjorn wciąż żyje, $N?', 0),
(12917, 'koKR', '$GPrzyniosłeś:Przyniosłaś; głosy wiatru?', 0),
(12920, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(12922, 'koKR', 'Powierzchnia kowadła jest parząco gorąca, w ostrym kontraście z mroźnym powietrzem.', 0),
(12925, 'koKR', 'Zniszczyłaś zarażone jaja?', 0),
(12926, 'koKR', '$GUkończyłeś:Ukończyłaś; dysk?', 0),
(12927, 'koKR', '$GUżyłeś:Użyłaś; dysku? Co $gznalazłeś:znalazłaś;?', 0),
(12928, 'koKR', '$GZnalazłeś:Znalazłaś; Skorupę Norgannona?', 0),
(12930, 'koKR', 'Udało ci się znaleźć trochę ziemi?', 0),
(12931, 'koKR', 'Jak idzie bitwa?', 0),
(12937, 'koKR', '$GUleczyłeś:Uleczyłaś; poległych obrońców?', 0),
(12942, 'koKR', 'Ukarałaś nasze zbłąkane siostry?', 0),
(12956, 'koKR', 'Co tam masz, maleńki?', 0),
(12957, 'koKR', '$GUwolniłeś:Uwolniłaś; niewolników burzowiernych?', 0),
(12964, 'koKR', 'Czego $gdowiedziałeś:dowiedziałaś; się o tej rudzie?', 0),
(12965, 'koKR', 'Czy to prawda? Valduran ma potężne relikty tytanów? $GZniszczyłeś:Zniszczyłaś; je?', 0),
(12967, 'koKR', 'Udało ci się poprowadzić Snorriego do kolejnego zwycięstwa, $N?', 0),
(12968, 'koKR', 'Znalazłaś Yuldę?', 0),
(12969, 'koKR', 'Wróciłaś.', 0),
(12970, 'koKR', 'Ciszej, bo inne mogą nabrać podejrzeń.', 0),
(12973, 'koKR', 'Wybacz, $gchłopcze:dziewczyno;! Tak mnie ta chwila pochłonęła, że zupełnie o tobie zapomniałem.', 0),
(12975, 'koKR', '$GZnalazłeś:Znalazłaś; kawałki Rogu Hodira?', 0),
(12976, 'koKR', 'Czy $gprzyniosłeś:przyniosłaś; fragmenty Rogu Hodira?', 0),
(12977, 'koKR', 'Wokół rogu wirują silne podmuchy wiatru, a jego dźwięk niesie się echem po okolicznych górach.$B$BPrzypadkowy przechodzień mógłby pomyśleć, że róg dmie sam z siebie...', 0),
(12978, 'koKR', 'Czy $gprzyłożyłeś:przyłożyłaś; młotem żelaznym w Nidavelirze?', 0),
(12980, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(12981, 'koKR', 'Kowadło otacza świetlista, błękitna poświata.', 0),
(12983, 'koKR', '$GZnalazłeś:Znalazłaś; matriarchę?', 0),
(12984, 'koKR', 'Trzeba rozprawić się z Valduranem, zanim schronienie padnie.', 0),
(12985, 'koKR', 'Czy $gzebrałeś:zebrałaś; ostatnie składniki, których szukam?', 0),
(12986, 'koKR', 'Czy przynosisz wiedzę, której szukam?', 0),
(12987, 'koKR', 'Czy $gumieściłeś:umieściłaś; Hełm Hodira?', 0),
(12988, 'koKR', 'Czy $gzdołałeś:zdołałaś; utrudnić im pracę, niszcząc kuźnie?', 0),
(12989, 'koKR', '$GWróciłeś:Wróciłaś;!', 0),
(12991, 'koKR', 'Czy $gprzetrzebiłeś:przetrzebiłaś; robotników pracujących przy żelaznym kolosie?', 0),
(12993, 'koKR', '$GZnalazłeś:Znalazłaś; dokumenty, których szukamy?', 0),
(12994, 'koKR', 'Matka legowiska mroźnych worgów przygląda ci się z zaciekawieniem.', 0),
(12996, 'koKR', 'Jak poszło z yeti?', 0),
(12997, 'koKR', 'Witaj, $Gbracie:siostro;.', 0),
(12998, 'koKR', 'Powiedz mi, że serce nie wpadło w ręce wroga.', 0),
(13000, 'koKR', '$GPrzyniosłeś:Przyniosłaś; futra?', 0),
(13001, 'koKR', 'Czy $gzebrałeś:zebrałaś; materiały na włócznię?', 0),
(13005, 'koKR', 'Witaj, $N! Jakie wieści przynosisz?', 0),
(13006, 'koKR', 'Na twoich oczach szron na hełmie gęstnieje, a wzdłuż jego krawędzi zaczynają tworzyć się sople...', 0),
(13007, 'koKR', 'Czy $gpokonałeś:pokonałaś; żelaznego kolosa i $gocaliłeś:ocaliłaś; schronienie przed zagładą?', 0),
(13009, 'koKR', 'Jak idą twoje wysiłki, $N?', 0),
(13010, 'koKR', 'Znowu tutaj, $gmaleńki:maleńka;?', 0),
(13011, 'koKR', 'Czy $gzabiłeś:zabiłaś; Jormuttar?', 0),
(13034, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś; z zapisków Obozu Tunka\'lo?', 0),
(13035, 'koKR', 'Dobrze cię znowu widzieć, $N.', 0),
(13038, 'koKR', 'Co takiego $gprzyniosłeś:przyniosłaś; z grobowca?', 0),
(13047, 'koKR', 'Ach, $N! Dobrze cię widzieć, $gmaleńki:maleńka;.', 0),
(13048, 'koKR', 'Czy $gdostroiłeś:dostroiłaś; Młot Wiedzy do czasów Burzokopytego?', 0),
(13049, 'koKR', '$GZnalazłeś:Znalazłaś; broń i zbroję Burzokopytego?', 0),
(13050, 'koKR', '$GZdobyłeś:Zdobyłaś; jaja, $N?', 0),
(13055, 'koKR', '$GWróciłeś:Wróciłaś;, mon?', 0),
(13058, 'koKR', 'Udało się? Czy prawdziwa linia czasu została przywrócona?', 0),
(13064, 'koKR', 'Posłuchaj moich słów.', 0),
(13108, 'koKR', 'Czy Loken poniósł sprawiedliwą karę?', 0),
(13109, 'koKR', 'Czy Volkhan został unicestwiony, $gmaleńki:maleńka;?', 0),
(13273, 'koKR', '$GOdzyskałeś:Odzyskałaś; te notatki?', 0),
(13274, 'koKR', 'Czy poszukiwacz Soren miał rację? $GZnalazłeś:Znalazłaś; w końcu Rdzeń Norgannona?', 0),
(13415, 'koKR', 'Konsola ma chyba otwór na dysk Wynalazcy.', 0),
(13416, 'koKR', 'Konsola ma chyba otwór na dysk Wynalazcy.', 0),
(13417, 'koKR', 'Król Burzowe Serce przesyła najszczersze podziękowania za to, że $gpomogłeś:pomogłaś; mu połączyć się z braćmi. Wygląda na to, że wyrusza teraz wyrównać rachunki – może spotkasz go znowu u progu Arthasa.', 0),
(13421, 'koKR', 'Czy $gznalazłeś:znalazłaś; więcej wiecznolodu, $gmaleńki:maleńka;?', 0),
(13422, 'koKR', 'Witaj, $gbracie:siostro;.', 0),
(13425, 'koKR', 'Zniszczyłaś zarażone jaja?', 0),
(13559, 'koKR', 'Dla wielkiego Hodira, gdy chodził wśród mroźnych olbrzymów, zwykłe dary nie były wystarczająco dobre.$B$BMoże już go z nami nie ma, ale zachowaliśmy tradycję składania daniny jego sile i mądrości. Udział w tej tradycji wiele by dodał twojej sławie, $gmaleńki:maleńka;.', 0),
(13622, 'koKR', 'Oczekiwanie na dane wejściowe.', 0),
(13629, 'koKR', 'Oczekiwanie na dane wejściowe.', 0),
(24849, 'koKR', 'Kim jesteś?', 0),
(24851, 'koKR', 'Kim jesteś?', 0);
