(44194, 'koKR', 'Kilt przyjaciela olbrzymów', '', 0),
(44195, 'koKR', 'Naramienniki władców olbrzymów', '', 0),
(44499, 'koKR', 'Odzyskane części żelaznego golema', '', 0),
(44501, 'koKR', 'Gobliński tłok frezowany maszynowo', 'Sprzedawany wyłącznie przez Roxi Ramrocket w K3.', 0),
(44510, 'koKR', 'Wykrój: mamucia torba górnicza', 'Uczy wytwarzania mamuciej torby górniczej.', 0),
(44576, 'koKR', 'Jasna flara', '', 0),
(44681, 'koKR', 'Tytanowa zębatka mózgowa', '', 0),
(44682, 'koKR', 'Talizman przyspieszenia czasu', '', 0),
(44704, 'koKR', 'Naładowany dysk', '', 0),
(44708, 'koKR', 'Nadbudówka Dirkee', '', 0),
(44724, 'koKR', 'Wiecznolodowy odprysk', 'Tak zimny, że parzy...', 0),
(44725, 'koKR', 'Wiecznolodowy odprysk', '', 0),
(44729, 'koKR', 'Wiecznolodowy proszek', '', 0),
(44732, 'koKR', 'Hełm z lazurowej smoczej skóry', '', 0),
(44749, 'koKR', 'Solony ser yeti', '', 0),
(44750, 'koKR', 'Górska woda', '', 0),
