(44756, 'koKR', 'Skrzepły szlam', '', 0),
(44757, 'koKR', 'Rozciągnięte segmenty', '', 0),
(44871, 'koKR', 'Większa inskrypcja topora', '', 0),
(44872, 'koKR', 'Większa inskrypcja turni', '', 0),
(44873, 'koKR', 'Większa inskrypcja szczytu', '', 0),
(44884, 'koKR', 'Arkanum mroźnej duszy', '', 0),
(45896, 'koKR', 'Niezwiązane fragmenty Val\'anyra', 'Z tych fragmentów dałoby się złożyć wspaniały młot, gdyby tylko udało się je znów połączyć.', 0),
(45897, 'koKR', 'Przekuty Młot Pradawnych Królów', 'Kwasy zestaliły się w przejrzyste kryształy, które otaczają legendarny młot.', 0),
(46017, 'koKR', 'Val\'anyr, Młot Pradawnych Królów', 'Przez tę broń płynie moc stworzenia.', 0),
