INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(29345, 'koKR', 'Brać ich!', '', 0),
(29823, 'koKR', '%s szykuje się, by roztrzaskać swoje kruche golemy!', '', 0),
(30125, 'koKR', '', 'Hyldsmeet jest święte. Kto odniesie zwycięstwo, ma zapewnione miejsce u boku Thorima na całe życie.', 0),
(30139, 'koKR', 'Jestem wolny? Jestem wolny!', '', 0),
(30140, 'koKR', 'Nie wierzę! Mogę iść!', '', 0),
(30141, 'koKR', 'Czas brać nogi za pas! Dzięki, $gprzyjacielu:przyjaciółko;!', '', 0),
(30198, 'koKR', 'Czy to prawda?! Ktoś w końcu przyszedł mnie stąd wyciągnąć?', '', 0),
(30199, 'koKR', 'Nie... nie... nie o to chodzi, prawda? Ten bezduszny prostak pewnie przysłał cię po narzędzia, co?', '', 0),
(30200, 'koKR', 'No cóż... to chyba dalej będę pilnował wieżyczek... czy coś.', '', 0),
(30233, 'koKR', 'Stado mechanicznych wiewiórek kopałoby szybciej od was!', '', 0),
(30235, 'koKR', 'Wasz majsterkowicz musiał was zrobić z blachy, wy leniwe kupy żużlu!', '', 0),
(30237, 'koKR', 'Nie jesteście warci złomu, z którego was zrobiono!', '', 0),
(30238, 'koKR', 'Wasza matka była kluczem francuskim, a ojciec cuchnął seaforium!', '', 0),
(30259, 'koKR', '', 'Z Lodowym Kłem przeszłam niezliczone bitwy.$b$bNiech cię nie zwiedzie brak pancerza. To najtwardsza niedźwiedzica, jaką znam.', 0),
(30260, 'koKR', '', 'Nie ociągaj się, dziewko!$b$bCzeka nas walka!', 0),
(30261, 'koKR', '', 'Walczymy ku chwale Brunnhildar!', 0),
(30285, 'koKR', '', 'Lodowy Kieł wykazuje się wielką odwagą, wchodząc na pole bitwy bez pancerza.$b$bMoże jej przykład doda ci trochę odwagi, $n.', 0),
(30286, 'koKR', 'Nie wygląda to dobrze, chłopcze.', '', 0),
(30287, 'koKR', 'Sam nie wiem, Bailey... nie jest tak źle. Stąd moglibyśmy dorzucić kamieniem do narzędzi.', '', 0),
(30288, 'koKR', 'Dziwne... przez chwilę mógłbym przysiąc, że nazwałeś mnie kurduplem.', '', 0),
(30289, 'koKR', 'Tak? To może sam tam podskoczysz tanecznym kroczkiem i je zabierzesz, co?', '', 0),
(30290, 'koKR', 'Rzucić mną?! Dobra, tego już za wiele, gnojku.', '', 0),
(30291, 'koKR', 'Zachowaj to dla siebie.', '', 0),
(30292, 'koKR', 'Lepiej miej nadzieję, że tego nie przeżyją, chłopcze.', '', 0),
(30293, 'koKR', 'Bo ja będę tylko patrzył i się śmiał, jak cię tam wrzucą.', '', 0),
(30294, 'koKR', 'Musi gdzieś być jakieś wejście.', '', 0),
(30295, 'koKR', 'To jak goblin zostawił tam swoje narzędzia?', '', 0),
(30296, 'koKR', 'O to chodzi, chłopcze! Wygląda na całkiem bezpieczne. Śmiało, będę tuż za tobą!', '', 0),
(30297, 'koKR', 'No... tak sobie pomyślałem... jesteś trochę mniejszy, więc raczej nie uruchomisz żadnej z tych min.', '', 0),
(30298, 'koKR', 'Nie, nie, nie! Nie kurduplem... tylko... no... może mógłbym przerzucić cię przez większość?', '', 0),
(30299, 'koKR', 'Mam pomysł, Bailey...', '', 0),
(30300, 'koKR', 'Nie, nie – to może się udać!', '', 0),
(30301, 'koKR', 'Tam jest ścieżka... tylko kilka min na jej końcu dzieli nas od narzędzi.', '', 0),
(30302, 'koKR', 'Poczekamy, aż będzie tędy przechodził następny poszukiwacz przygód, i powiemy mu, że tędy droga... a jak już wysadzi miny, po prostu wejdziemy i zabierzemy narzędzia!', '', 0),
(30303, 'koKR', 'Naprawdę na to nie wygląda, Bailey.', '', 0),
(30304, 'koKR', 'Och... słuszna uwaga. A może tamtędy? Wygląda na czysto... tak jakby.', '', 0),
(30305, 'koKR', 'Eee... nie trzeba. Jeszcze trochę boli od ostatniego razu.', '', 0),
(30306, 'koKR', 'Aaa!', '', 0),
(30311, 'koKR', 'Mało brakowało! Ale mnie wystraszyłeś.', '', 0),
(30312, 'koKR', 'Mięczak.', '', 0),
(30322, 'koKR', 'Znowu te przeklęte żelazne krasnoludy! Jakimś cudem znalazły go przed nami.', '', 0),
(30323, 'koKR', 'Nie spoczną, dopóki go nie znajdą. Nie możemy do tego dopuścić, $n, i Brann o tym wie.', '', 0),
(30324, 'koKR', 'W tym liściku są dość zagadkowe wskazówki. Brann musiał mieć jakiś plan awaryjny, ale nie będzie w nieskończoność wymykał się pościgowi...', '', 0),
(30325, 'koKR', 'Musisz go odnaleźć, zanim zrobią to żelaźni!', '', 0),
(30365, 'koKR', 'Zauważono cię! Użyj sieci i lodowej ślizgawki, by trzymać krasnoludy na dystans!', '', 0),
(30366, 'koKR', '%s węszy przy ziemi, by złapać trop.', '', 0),
(30367, 'koKR', '%s wytropił źródło zapachu.', '', 0),
(30368, 'koKR', 'Mroźny ogar znalazł kryjówkę złodzieja. Stań z nim do walki!', '', 0),
(30373, 'koKR', 'Ocena integralności bazy danych...', '', 0),
(30374, 'koKR', 'Uruchamianie diagnostyki poziomu trzeciego...', '', 0),
(30375, 'koKR', 'Defragmentacja pliku wymiany...', '', 0),
(30376, 'koKR', 'Weryfikacja klucza szyfrującego...', '', 0),
(30377, 'koKR', 'Próba przywrócenia utraconych danych...', '', 0),
(30378, 'koKR', 'Wdrażanie nowych protokołów bezpieczeństwa...', '', 0),
(30420, 'koKR', 'Nic ci nie jest? $GPrzyszedłem:Przyszłam; zabrać cię z powrotem do Mroźnej Warowni, jeśli dasz radę wstać.', 'Nic ci nie jest? $GPrzyszedłem:Przyszłam; zabrać cię z powrotem do Mroźnej Warowni, jeśli dasz radę wstać.', 0),
(30427, 'koKR', '<Mroźnorodny zwiadowca na twój widok próbuje wstać, ale osuwa się z powrotem na ziemię, ściskając wyraźnie bolesną ranę w boku.>', '', 0),
(30428, 'koKR', 'Chyba nic z tego, $gchłopcze:dziewczyno;. Straciłem dużo krwi... nie ma mowy, żebym wrócił.', '', 0),
(30429, 'koKR', 'Przykro mi, że nie $gdotarłem:dotarłam; tu wcześniej. Co się stało?', 'Przykro mi, że nie $gdotarłem:dotarłam; tu wcześniej. Co się stało?', 0),
(30430, 'koKR', 'Z doliny nadleciało stado harpii. Prowadziła je wielka harpia imieniem Sirana... Nie miałem dokąd uciec. Od dawna nie były tak agresywne... nie spodziewałem się tego... straciłem czujność... to moja wina.', '', 0),
(30431, 'koKR', 'Sprowadzę pomoc. Trzymaj się.', 'Sprowadzę pomoc. Trzymaj się.', 0),
(30432, 'koKR', 'Na to... już trochę za późno... $gchłopcze:dziewczyno;.$B$B<Mroźnorodny zwiadowca wykasłuje krew na śnieg.>$B$BDopadnij... za mnie... tę babę, która nimi dowodzi...$B$B<Mroźnorodny zwiadowca osuwa się i wydaje ostatnie tchnienie.>', '', 0),
(30593, 'koKR', 'Przyszły w odwiedziny smakowite kąski! Może upiekę was na waszych własnych bombach?', '', 0),
(30618, 'koKR', '<Brann patrzy na ciebie wyczekująco.>', '', 0),
(30619, 'koKR', 'Wyobraź sobie całą mądrość i wiedzę zamkniętą w Ulduarze. Mogą tam być ukryte same tajemnice życia!', '', 0),
(30621, 'koKR', 'Rozumiesz mnie? Teraz powinniśmy już się rozumieć.', 'Rozumiesz mnie? Teraz powinniśmy już się rozumieć.', 0),
(30622, 'koKR', 'Jeśli Liga Odkrywców przysłała ludzi, nie widziałem po nich śladu. Znalazłem twój liścik zakopany w obozie opanowanym przez żelazne krasnoludy.', 'Jeśli Liga Odkrywców przysłała ludzi, nie widziałem po nich śladu. Znalazłem twój liścik zakopany w obozie opanowanym przez żelazne krasnoludy.', 0),
(30623, 'koKR', 'Zwiadowca znalazł resztki twojego dziennika w Thor Modan. Od tamtej pory cię szukamy.', 'Zwiadowca znalazł resztki twojego dziennika w Thor Modan. Od tamtej pory cię szukamy.', 0),
(30624, 'koKR', 'Ja... teraz cię rozumiem! No cóż, skoro możemy już ze sobą rozmawiać, masz mi to i owo do wyjaśnienia!', '', 0),
(30625, 'koKR', 'Skąd masz mój komunikator od Ligi Odkrywców?', '', 0),
(30626, 'koKR', 'Dziękuję, że $gpozbyłeś:pozbyłaś; się żelaznych krasnoludów. Ale dlaczego Horda miałaby się mną interesować?', '', 0),
(30627, 'koKR', 'Czy to nie zwiadowca Vor\'takh? Nawet ja słyszałem o jego bezwzględności. Zamierza mnie więc porwać?', '', 0),
(30628, 'koKR', 'Skoro $gwidziałeś:widziałaś; dziennik, wiesz, co odkryłem. Dzieła samych tytanów walczą ze sobą!', '', 0),
(30629, 'koKR', 'Loken i jego słudzy, żelazne krasnoludy, wyparli ziemnych z Ulduaru i przejęli miasto.', '', 0),
(30630, 'koKR', 'Jeśli będziemy tracić czas i siły na walkę między sobą, Loken użyje zasobów Ulduaru, by zniszczyć i Hordę, i Przymierze.', '', 0),
(30631, 'koKR', 'Porozmawiaj z dowódcą swojej placówki, $gchłopcze:dziewczyno;, i przekonaj go, żeby porzucił głupi plan Vor\'takha.', '', 0),
(30632, 'koKR', 'Boktar uważa tę katastrofę za niefortunne zdarzenie, ale ja wierzę, że mamy się z niej czegoś nauczyć.', '', 0),
(30643, 'koKR', 'Trucizna... wnętrzności mi się skręcają...', 'Trucizna... wnętrzności mi się skręcają...', 0),
(30644, 'koKR', 'Jestem $ggotów:gotowa; – wyciągnijmy cię stąd.', 'Jestem $ggotów:gotowa; – wyciągnijmy cię stąd.', 0),
(30645, 'koKR', 'Daj znać, kiedy będziesz $ggotów:gotowa;. Wolałbym prędzej niż później... no wiesz, skoro powoli umieram od trucizny i w ogóle.', 'Daj znać, kiedy będziesz $ggotów:gotowa;. Wolałbym prędzej niż później... no wiesz, skoro powoli umieram od trucizny i w ogóle.', 0),
(30646, 'koKR', 'Zaniosę woreczek jadowy Ricket... a potem... no wiesz... padnę. Dzięki, że mi $gpomogłeś:pomogłaś;!', 'Zaniosę woreczek jadowy Ricket... a potem... no wiesz... padnę. Dzięki, że mi $gpomogłeś:pomogłaś;!', 0),
(30661, 'koKR', '', 'Rozerwę cię na strzępy.', 0),
(30662, 'koKR', '', 'Wyzywasz mnie?', 0),
(30663, 'koKR', '', 'Nie wyglądasz groźnie.', 0),
(30664, 'koKR', '', 'Myślisz, że masz to, czego trzeba?', 0),
(30665, 'koKR', 'Zaczynajmy, siostro.', 'Zaczynajmy, siostro.', 0),
(30666, 'koKR', '', 'Witaj, siostro bojowa. Mogę ci pomóc odzyskać zagubionych towarzyszy.', 0),
(30667, 'koKR', '', 'Witaj, siostro bojowa. Mogę przechować twoje zwierzęta w stajni albo pomóc ci odzyskać zagubionych towarzyszy.', 0),
(30669, 'koKR', '', 'Chodź, siostro bojowa.$B$BNajedz się i wyśpij, a będziesz walczyć z całych sił!', 0),
(30720, 'koKR', 'Dziękuję. Myślałem, że już po mnie.', '', 0),
(30721, 'koKR', 'Byłem pewien, że tu zginę.', '', 0),
(30722, 'koKR', 'Pozwól mi walczyć u twego boku.', '', 0),
(30723, 'koKR', 'Walczmy razem z żelaznymi!', '', 0),
(30759, 'koKR', 'Wracaj do pracy, zanim nadzorca nas zobaczy.', '', 0),
(30760, 'koKR', 'Nie jestem tu do pracy. Przybywam, by uwolnić cię z niewoli w kopalniach.', 'Nie jestem tu do pracy. Przybywam, by uwolnić cię z niewoli w kopalniach.', 0),
(30762, 'koKR', 'Znowu wolność? Czeka praca dla Opiekuna Mimira.', '', 0),
(30763, 'koKR', 'Dziękuję. Przyłączę się do twojej walki z burzowiernymi.', '', 0),
(30764, 'koKR', 'Nowa dyrektywa: opuścić kopalnię i wrócić do Biblioteki Wynalazcy.', '', 0),
(30765, 'koKR', 'Nowa dyrektywa: pomóc w pokonaniu żelaznych krasnoludów.', '', 0),
(30766, 'koKR', 'Błąd obliczeń. Jednostka niesprawna. Dyrektywa: wyłączenie.', '', 0),
(30792, 'koKR', 'Ta replika Rogu Hodira stoi ku pamięci króla Arngrima i wszystkich poległych w bitwie pod Gromospadem.', '', 0),
(30793, 'koKR', 'Przeklinam cię! Nie będziesz traktować mnie jak zwierzęcia!', '', 0),
(30794, 'koKR', 'Dość! Nauczę cię manier, dziewko!', '', 0),
(30795, 'koKR', 'Wolę zginąć w walce, niż żyć jak niewolnik!', '', 0),
(30796, 'koKR', 'Z powrotem... do pracy...', '', 0),
(30797, 'koKR', 'Traktujecie nas gorzej niż zwierzęta!', '', 0),
(30798, 'koKR', 'Zemścimy się... pewnego dnia.', '', 0),
(30803, 'koKR', 'Dziękuję, dziękuję! Czas uciekać od tych szalonych niebieskich bab!', '', 0),
(30805, 'koKR', '', 'Ten mizerny zielony szczeniak nie przydał się w kopalniach. Nieważne, posłuży za rozgrzewkę przed walką.', 0),
(30806, 'koKR', 'Daruj sobie rozgrzewkę, siostro... czy boisz się zmierzyć z kimś swoich rozmiarów?', 'Daruj sobie rozgrzewkę, siostro... czy boisz się zmierzyć z kimś swoich rozmiarów?', 0),
(30807, 'koKR', '', 'Niczego się nie boję – dawaj!', 0),
(30808, 'koKR', '', 'Niech wygra lepsza!', 0),
(30809, 'koKR', '', 'Powodzenia... Przyda ci się!', 0),
(30811, 'koKR', '', 'Nie jesteś $ggodny:godna; Thorima!', 0),
(30837, 'koKR', 'Kowadło Fjorna stoi teraz na widocznym miejscu w Dun Niffelem jako symbol zwycięstwa olbrzymów nad Fjornem i jego armiami.$b$bNie możesz powstrzymać uśmiechu, wiedząc, że twoje czyny wywarły tak trwały wpływ na świat.', '', 0),
(30847, 'koKR', 'Wykryto metaliczną próbkę obcego pochodzenia.', '', 0),
(30848, 'koKR', 'Rozpoczynanie analizy...', '', 0),
(30849, 'koKR', 'Próbkę zidentyfikowano jako stop saronitu i żelaza.', '', 0),
(30850, 'koKR', 'Ruda użyta w tej próbce pochodzi z głębi skorupy Azeroth i została niedawno wydobyta.', '', 0),
(30851, 'koKR', 'Saronit w tej próbce jest niemal czysty. Takie rudy nie występują naturalnie na powierzchni Azeroth.', '', 0),
(30854, 'koKR', 'Tę rudę mogła stworzyć jedynie potężna, złowroga siła. Próba dostępu do banków danych w celu uzyskania dalszych informacji...', '', 0),
(30859, 'koKR', 'Odmowa dostępu?!', '', 0),
(30860, 'koKR', 'Dalsze informacje są dostępne wyłącznie w archiwach Ulduaru, na rozkaz Opiekuna Lokena.', '', 0),
(30861, 'koKR', 'Dyrektywa wykonana. Powrót do trybu czuwania.', '', 0),
(30865, 'koKR', 'Witaj, $n. To warsztat Opiekuna Mimira.', '', 0),
(30866, 'koKR', '$GZnalazłem:Znalazłam; tę dziwną płytę pancerną. Możesz mi powiedzieć o niej coś więcej?', '$GZnalazłem:Znalazłam; tę dziwną płytę pancerną. Możesz mi powiedzieć o niej coś więcej?', 0),
(30867, 'koKR', 'Jedno jest jednak pewne: rozmiar, grubość i otwory na śruby tej płyty wskazują, że służy jako pancerz kolosalnej konstrukcji.', '', 0),
(30891, 'koKR', 'Nareszcie tyrania burzowiernych dobiegła końca!', '', 0),
(30892, 'koKR', 'Z rozbitego truchła wysypują się burzowierne krasnoludy!', '', 0),
(30893, 'koKR', 'Twoi słudzy nie będą już napadać na kamienne istoty i ich sojuszników.', '', 0),
(30894, 'koKR', 'Jestem twoją zgubą, Valduranie!', '', 0),
(30895, 'koKR', 'Jakie przewidywalne! Ale czego się spodziewać po kamieniu? Przecież nie będzie myślał inaczej niż kamień.', '', 0),
(30896, 'koKR', 'Skoro tak ci spieszno do walki, spełnię twoje życzenie. Ale wiedz, że nic, co tu zrobisz, nie przeszkodzi w ukończeniu żelaznego kolosa!', '', 0),
(30906, 'koKR', 'Synowie Hodira! Z pokorą przedstawiam wam...', 'Synowie Hodira! Z pokorą przedstawiam wam...', 0),
(30907, 'koKR', 'Hełm Hodira!', 'Hełm Hodira!', 0),
(30916, 'koKR', '$GZnalazłeś:Znalazłaś; mnie, co? To teraz zginiesz!', '', 0),
(30917, 'koKR', 'Giń, $gprzyjacielu:przyjaciółko; mrozu!', '', 0),
(30918, 'koKR', 'Nie przeżyjesz, żeby o tym opowiedzieć!', '', 0),
(30936, 'koKR', 'Gdzie mroźnorodni, tam i orły. Są naszymi sojusznikami dłużej, niż chodzę po tym świecie... a nie jestem już taki młody, $gchłopcze:dziewczyno;.', '', 0),
(30942, 'koKR', 'Król Burzowe Serce wystawia cię na próbę, co? Musi coś w tobie widzieć, inaczej wątpię, by poddał cię tak świętemu rytuałowi.', '', 0),
(30943, 'koKR', 'Wiem, że dopiero poznajesz nasz lud, więc po drodze trochę cię wprowadzę.', '', 0),
(30944, 'koKR', 'Przed laty mój ojciec i kilku innych mroźnorodnych wracali z wyprawy przez Smocze Pustkowia. Szalała straszna zamieć... o wiele gorsza niż wszystkie, jakie widzieliśmy od tamtej pory.', '', 0),
(30945, 'koKR', 'Natknęli się na ślad zbroczonego krwią śniegu i poszli nim, aż znaleźli błąkającego się krasnoluda, który mówił w dialekcie, jakiego nie rozumieli... i to, uważaj, nie krasnoluda naszego rodu, ale krasnoluda górskiego – kogoś, kogo nasi nigdy wcześniej nie widzieli.', '', 0),
(30946, 'koKR', 'Krasnolud wyglądał na zagubionego, nie pamiętał, skąd przybył, ani nawet własnego imienia. Ojciec i jego towarzysze nie należeli do tych, którzy zostawiają krasnoludzkiego kuzyna na śmierć w śniegu, więc wzięli go ze sobą i ruszyli dalej w stronę Mroźnej Warowni.', '', 0),
(30947, 'koKR', 'Niedługo potem, zupełnie znikąd, śnieg przed nimi wybuchł i spadł na nich jormungar wielkości samej Veranus... jednego z nich połknął w całości, zanim ktokolwiek zdążył zareagować.', '', 0),
(30948, 'koKR', 'Ojciec myślał, że wszyscy zginą... ale za nim po śniegu przetoczył się wściekły ryk. Odwrócił się i zobaczył, że górski krasnolud rośnie, jego skóra nabiera faktury kamienia, a w dłoniach trzeszczą mu błyskawice.', '', 0),
(30949, 'koKR', 'Krasnolud runął naprzód z hukiem jak przetaczający się grom i cisnął lśniącym metalowym młotem, po którym przebiegały błyskawice, prosto w gardło jormungara.', '', 0),
(30950, 'koKR', 'Jormungar padł w jednej chwili, a jego głowa ledwie trzymała się drgającego ciała. Ojciec z podziwem odwrócił się do krasnoluda i uniósł pięść w geście uznania...', '', 0),
(30952, 'koKR', 'Skoro obcy nie miał własnego imienia, ojciec nazwał go „Yorg” – tym imieniem nazywa się tylko legendarnych czempionów. Wiele lat później stoi przed nami jako Yorg Burzowe Serce, Król Mroźnorodnych.', '', 0),
(30953, 'koKR', 'Król Burzowe Serce dobrze nas wyszkolił... uczynił z nas jeszcze groźniejszych wojowników, niż byliśmy w czasach wojny z mroźnymi olbrzymami.', '', 0),
(30955, 'koKR', 'Jedną z najcięższych prób, jakim poddaje się wojownika mroźnorodnych, jest walka ze stworzeniem znacznie większym od nas – olbrzymem, smokiem, jormungarem – na dowód, że rozmiar nigdy nie będzie naszą słabością.', '', 0),
(30956, 'koKR', 'Tę właśnie próbę masz dziś przed sobą. Wróć do nas dopiero wtedy, gdy Żelazny Obserwator będzie martwy, a zyskasz szacunek jako $gwojownik:wojowniczka; mroźnorodnych.', '', 0),
(30969, 'koKR', 'Żelazny Obserwator zatacza się, sięga do bezużytecznych już oczu i szarżuje na oślep.', '', 0),
(30972, 'koKR', 'Chyba nie $gmyślałeś:myślałaś;, że pozwolę ci tu wejść i zabrać Serce Burzy?', '', 0),
(30973, 'koKR', 'Może i $gzabiłeś:zabiłaś; Valdurana, ale to nie powstrzyma mnie przed ukończeniem kolosa.', '', 0),
(30974, 'koKR', 'Jesteś tu mile $gwidziany:widziana; jako $gprzyjaciel:przyjaciółka; i $gsojusznik:sojuszniczka; ziemnych.', '', 0),
(30981, 'koKR', 'Wolno ci odwiedzać naszą twierdzę, $gmaleńki:maleńka;.$b$bNie przynieś nam hańby!', '', 0),
(30982, 'koKR', 'Jeśli łaska, królu Jokkumie, czy mogę się dowiedzieć, co się stało z Krolmirem?', 'Jeśli łaska, królu Jokkumie, czy mogę się dowiedzieć, co się stało z Krolmirem?', 0),
(30984, 'koKR', 'Dobrze, $gmaleńki:maleńka;.$b$bChoć wiele jeszcze musisz zrobić, by naprawić nasze stosunki z Thorimem, czuję się w obowiązku zdradzić ci tę jedną tajemnicę.$b$bPrzemów do mnie ponownie, gdy będziesz $ggotów:gotowa; ujrzeć to, czego szukasz.', '', 0),
(30985, 'koKR', 'Jestem $ggotów:gotowa; poznać los Krolmira.', 'Jestem $ggotów:gotowa; poznać los Krolmira.', 0),
(30986, 'koKR', 'Udziec tego niedźwiedzia jest zamarznięty na kość... spróbuj jeszcze raz.', 'Udziec tego niedźwiedzia jest zamarznięty na kość... spróbuj jeszcze raz.', 0),
(31001, 'koKR', 'Królu Jokkumie, wzywałeś mnie?', '', 0),
(31003, 'koKR', 'Jokkumie, synu Arngrima, zawsze żałowałem tego, co tu zrobiłem. W żałobie wyrządziłem wielką krzywdę najbliższym.', '', 0),
(31041, 'koKR', 'Coś tu się zupełnie nie zgadza, $n. W opowieści poskromicielki wiatru Barah Burzokopyty był bohaterem, a nie złoczyńcą.', '', 0),
(31044, 'koKR', 'Północny Wiatr to odwieczny wróg taunka, władca wśród żywiołów i ta sama siła, która wysysa życie z tego pradawnego ludu.', '', 0),
(31046, 'koKR', 'Taunka woleliby zginąć, niż pokłonić się Północnemu Wiatrowi. Coś tu jest nie tak.', '', 0),
(31049, 'koKR', 'Młot Wiedzy...', '', 0),
(31050, 'koKR', 'To potwierdza nasze podejrzenia. Nici czasu zostały przecięte i utkane na nowo w niewłaściwy wzór. Ale jak?', '', 0),
(31062, 'koKR', 'Proszę cię o przebaczenie za cierpienie, jakie sprowadziłem na ciebie i twój lud.', '', 0),
(31063, 'koKR', 'Krolmir... Dziękuję ci, Jokkumie. Nie śmiałem mieć nadziei, że wciąż istnieje. Wkrótce znów zazna chwalebnej bitwy!', '', 0),
(31078, 'koKR', 'Czas położyć kres szaleństwu mojego brata.', '', 0),
(31079, 'koKR', 'Lokenie!!', '', 0),
(31080, 'koKR', 'Wstań i walcz ze mną, ty nędzny zdrajco!', '', 0),
(31081, 'koKR', 'Dobrze cię znowu widzieć!$B$BKról Burzowe Serce oznajmił mi, że na jakiś czas nas opuści... wygląda na to, że powróciło do niego jakieś ponure wspomnienie i ma rachunki do wyrównania. Bardzo nalegał, żebyśmy mu nie towarzyszyli, więc uszanowaliśmy jego wolę, jak zawsze.$B$BNa ten czas przejąłem odpowiedzialność za nasz klan. Oczywiście nadal jesteś u nas mile $gwidziany:widziana;.', '', 0),
(31082, 'koKR', 'Chyba bardzo ci spieszno do ukochanej Sif, bracie.', '', 0),
(31083, 'koKR', 'Nie waż się...', '', 0),
(31110, 'koKR', 'Wygląda na to, że w uczciwej walce wciąż potrafisz mnie pokonać, braciszku.', '', 0),
(31111, 'koKR', 'Na twoje nieszczęście... ta walka wcale nie jest uczciwa!', '', 0),
(31112, 'koKR', 'Dzięki $gtwojemu małemu przyjacielowi:twojej małej przyjaciółce; opuściłeś Świątynię Burz, gdzie byłeś najsilniejszy. Walczymy za to bliżej mocy mojego pana.', '', 0),
(31116, 'koKR', 'Mów...', '', 0),
(31117, 'koKR', 'Jej imię!!', '', 0),
(31127, 'koKR', 'Co do twojego życia, $gśmiertelniku:śmiertelniczko;... będę wspaniałomyślny. W końcu... po co miałbym niszczyć tak użyteczne narzędzie? Czekałem na ciebie całymi tygodniami w tej kopalni Hyldnir.', '', 0),
(31128, 'koKR', 'Sługi! Zabierzcie mojego brata i jego smoczycę do ich nowego domu. Dopilnujcie, żeby bestia dotarła żywa. Mam szczególne plany wobec tej matki lęgu.', '', 0),
(31133, 'koKR', 'Rzecz jasna, nie była to moja postać. A gdybyś nie był tak lekkomyślny, przejrzałbyś moją iluzję. Ale nie zawiodłeś mnie, i za to... muszę ci podziękować!', '', 0),
(31149, 'koKR', 'Nie jesteś taunka. Dlaczego $gprzyszedłeś:przyszłaś; na święte cmentarzysko naszych wojowników?', '', 0),
(31150, 'koKR', 'Przepraszam, że zakłócam twój spoczynek, wodzu, ale duch twojego brata może być w niebezpieczeństwie. Czy powiesz mi, co o nim pamiętasz?', 'Przepraszam, że zakłócam twój spoczynek, wodzu, ale duch twojego brata może być w niebezpieczeństwie. Czy powiesz mi, co o nim pamiętasz?', 0),
(31151, 'koKR', 'Mój brat, Burzokopyty, był o wiele większym wojownikiem niż ja. Gdy ja szkoliłem się na wodza naszego klanu, on przygotowywał się do większej wyprawy.', '', 0),
(31152, 'koKR', 'Jak mógłby być w niebezpieczeństwie? Chciał tylko dać nam władzę nad żywiołami, które uprzykrzały nam tu życie.', '', 0),
(31153, 'koKR', 'Szukał artefaktu... chyba rogu. Opuścił wioskę i wyruszył na długą wędrówkę, by go odnaleźć.', '', 0),
(31154, 'koKR', 'Wiem, że po zdobyciu rogu ścigał go straszliwy wróg, ale ja... nie pamiętam... co było... dalej.', '', 0),
(31155, 'koKR', 'Moje wspomnienia jakby spowijała mgła. Nie pamiętam nawet, co stało się z moim bratem. Czy to masz na myśli, mówiąc, że jest w niebezpieczeństwie?', '', 0),
(31156, 'koKR', 'Te zakłócenia w grobowcu – to muszą być one. Rozejrzyj się, $n. Widzisz je?', '', 0),
(31157, 'koKR', 'Tak, to ich wina, ale nie mam mocy, by je powstrzymać. Czy ostrzeżesz mieszkańców Tunka\'lo, $gprzybyszu:przybyszko;, że ich przeszłość i przodkowie są w niebezpieczeństwie?', '', 0),
(31158, 'koKR', '%s wydaje z siebie donośny ryk, spadając na gniazdo.', '', 0),
(31163, 'koKR', '', 'Spójrz na nie... obchodzi je tylko prześciganie jedna drugiej.', 0),
(31164, 'koKR', 'Opowiedz mi o tej propozycji.', 'Opowiedz mi o tej propozycji.', 0),
(31165, 'koKR', '', 'Widzisz, Thorim nie jest taki jak te harpie. To czcigodna istota, niemal równa bogom.$B$BSłużył tytanom jako strażnik Ulduaru i Tarasu Twórców.$B$BDopóki jego żona, Sif, nie została tchórzliwie zamordowana przez jego brata.', 0),
(31167, 'koKR', '', 'Thorimowi odbiło. Obrócił się przeciwko swoim najukochańszym sojusznikom, mroźnym olbrzymom.$B$BTo jeden z powodów, dla których po dziś dzień tę krainę rozdziera wojna między Hyldnir a Synami Hodira... i dla których Thorim sam skazał się na wygnanie w Świątyni Burz.', 0),
(31168, 'koKR', 'Chcesz, żebym $gwziął:wzięła; udział w Hyldsmeet, żeby zakończyć wojnę?', 'Chcesz, żebym $gwziął:wzięła; udział w Hyldsmeet, żeby zakończyć wojnę?', 0),
(31169, 'koKR', '', 'Co mnie obchodzi, czy te wilczyce i mroźne olbrzymy wybijają się nawzajem każdego dnia?$B$BNie, nie... chcę, żeby Thorim otrząsnął się z odrętwienia i zebrał wszystkich sojuszników, by odbić Ulduar.$B$BJeśli mu się to nie uda, świat zostanie rozdarty na strzępy!$B$BI oczywiście odpowiednio cię wynagrodzę.', 0),
(31170, 'koKR', 'Dobrze. Wezmę udział w tych zawodach.', 'Dobrze. Wezmę udział w tych zawodach.', 0),
(31175, 'koKR', '', 'Faceci – ani z nimi, ani bez nich. No, właściwie bez nich się da... tylko strasznie nudno.', 0),
(31176, 'koKR', '', 'Te kopalnie to okropne miejsce. Na szczęście nie zamierzam tu długo zostać.', 0),
(31177, 'koKR', '', 'Niedźwiedzie to piękne stworzenia. Dzikie, silne i zaciekłe w walce... całkiem jak my, siostro.', 0),
(31180, 'koKR', 'Głupcze! Nigdy mnie nie pokonasz!', '', 0),
(31181, 'koKR', 'Nigdy nie pozwolę ci użyć Rogu furii żywiołaków przeciwko nam! Giń, słabeuszu!', '', 0),
(31201, 'koKR', 'Witam, witam!', '', 0),
(31202, 'koKR', '', 'Cześć, złotko – miło, że wpadasz!', 0),
(31203, 'koKR', '', 'Cześć, złotko – miło, że wpadasz!', 0),
(31205, 'koKR', 'Te góry są pełne historii... nie zapomnij się czasem zatrzymać i wszystkiemu przyjrzeć, $N.', '', 0),
(31217, 'koKR', 'Mów, $N.', '', 0),
(31218, 'koKR', 'Zbyt długo ukrywałem się przed swoim przeznaczeniem. To, co muszę zrobić, nigdy nie było jaśniejsze.$B$BLoken musi zginąć z mojej ręki.', '', 0),
(31219, 'koKR', 'Możesz mi powiedzieć, co się stało z Sif?', 'Możesz mi powiedzieć, co się stało z Sif?', 0),
(31220, 'koKR', 'Przez chwilę myślałem, że jesteś moją ukochaną Sif... to pasmo włosów... ale nie! To niemożliwe... Sif nie żyje...$B$BMój... mój brat... zabił ją!', '', 0),
(31221, 'koKR', 'Zrobił coś więcej, Thorimie. Teraz to on włada Ulduarem.', 'Zrobił coś więcej, Thorimie. Teraz to on włada Ulduarem.', 0),
(31222, 'koKR', 'Ulduar... przysięgałem chronić Ulduar.$B$BPrzysięgałem chronić Taras Twórców.$B$BPrzysięgałem strzec paktów między rasami mrozu.$B$BAle zawiodłem! Pozwoliłem, by brat mnie oszukał. Pozwoliłem, by obrócił mnie przeciw moim sojusznikom. Podstępem sprawił, że o śmierć Sif obwiniłem drogiego przyjaciela, Arngrima, króla mroźnych olbrzymów.$B$BGdy zrozumiałem, co zrobiłem... poddałem się rozpaczy.', '', 0),
(31223, 'koKR', 'To nie musi się tak skończyć.', 'To nie musi się tak skończyć.', 0),
(31224, 'koKR', 'Kim jesteś, $gmaleńki:maleńka;? Jak śmiesz przychodzić z takimi słowami do potężnego Thorima...$B$BPowinienem... cię zmiażdżyć!$B$BA jednak $gwyrwałeś:wyrwałaś; mnie z odrętwienia. Twoja obecność tutaj to znak!$B$BTo nie przypadek, że wziąłem cię za Sif. Co by o mnie pomyślała? Muszę przygotować się do bitwy.$B$BMuszę pomścić jej śmierć i uwolnić święte ziemie tytanów od szaleństwa mojego brata!', '', 0),
(31225, 'koKR', 'Jestem z tobą, Thorimie.', 'Jestem z tobą, Thorimie.', 0),
(31228, 'koKR', 'Witaj na Burzowych Szczytach.', '', 0),
(31259, 'koKR', 'Nie ma wątpliwości, że coś wypaczyło prawdziwą historię Burzokopytego i wojowników z Obozu Tunka\'lo. Ale co?', '', 0),
(31263, 'koKR', 'Nie! Prawdziwy głos historii zwycięży. Przywrócimy wszystko, co zniszczyłeś!', '', 0),
(31264, 'koKR', '$n, musimy się pospieszyć i odkryć, kiedy Północny Wiatr zaczął wypaczać linię czasu. Tylko wtedy zdołamy go pokonać i ją naprawić.', '', 0),
(31306, 'koKR', 'Gdzie jest Nestor Fargal?', 'Gdzie jest Nestor Fargal?', 0),
(31307, 'koKR', 'Nestor Fargal czuwa nad Mroźną Warownią na Burzowych Szczytach.', 'Nestor Fargal czuwa nad Mroźną Warownią na Burzowych Szczytach.', 0),
(31308, 'koKR', 'Gdzie jest Nestor Kamiennobrody?', 'Gdzie jest Nestor Kamiennobrody?', 0),
(31309, 'koKR', 'Nestor Kamiennobrody mieszka w Schronieniu Bouldercraga na Burzowych Szczytach.', 'Nestor Kamiennobrody mieszka w Schronieniu Bouldercraga na Burzowych Szczytach.', 0),
(31310, 'koKR', 'Gdzie jest Nestor Yurauk?', 'Gdzie jest Nestor Yurauk?', 0),
(31311, 'koKR', 'Nestor Yurauk przebywa w Salach Kamienia.', 'Nestor Yurauk przebywa w Salach Kamienia.', 0),
(31343, 'koKR', 'Jest powolny, zardzewiały przez wieki... bądź $gzwinny:zwinna;, a nie pokona cię. Masz przychylność króla Burzowe Serce – nie zawiedź go.', '', 0),
(31365, 'koKR', '', 'Służymy Thorimowi, siostro.', 0),
(31415, 'koKR', 'To wy zniszczyliście moje dzieci? Za... to... zapłacicie!', '', 0),
(31416, 'koKR', 'Życie z martwoty... śmierć dla was.', '', 0),
(31417, 'koKR', 'W tym procesie nic się nie marnuje. Zobaczycie...', '', 0),
(31418, 'koKR', 'Zmiażdżę was pod butami!', '', 0),
(31419, 'koKR', 'Cała moja praca... zniweczona!', '', 0),
(31420, 'koKR', 'Armie żelaza podbiją wszystko!', '', 0),
(31421, 'koKR', 'Pfe! Żałosne!', '', 0),
(31422, 'koKR', 'Kosztowaliście mnie zbyt wiele pracy!', '', 0),
(31423, 'koKR', 'Pan miał rację... że się niepokoił.', '', 0),
(31604, 'koKR', 'Wracaj do Wioski Brunnhildar!', '', 0),
(32214, 'koKR', '%s biegnie do swojego kowadła!', '', 0),
(32253, 'koKR', '', 'Nasza droga jest święta. Wybierzemy śmierć, zanim porzucimy Thorima i przyłączymy się do takich jak Król Lisz.', 0),
(32254, 'koKR', 'Zbyt długo tolerowałem mojego brata. Czas to naprawić. Czas zniszczyć jego i jego zwolenników.', '', 0),
(32371, 'koKR', 'Jestem $ggotów:gotowa;, Brannie. Zróbmy zwornik.', 'Jestem $ggotów:gotowa;, Brannie. Zróbmy zwornik.', 0),
(32385, 'koKR', 'Dobra. Zobaczmy, czy uda nam się dokończyć ten zwornik.', '', 0),
(32391, 'koKR', 'Zwornik gotowy! Udało się, $n!', '', 0),
(32393, 'koKR', 'Kto wie, jakie tajemnice czekają w archiwach Ulduaru? Idę je odkryć. Jeszcze raz dziękuję za pomoc, $n. Bez niej wciąż szukałbym tego klucza.', '', 0),
(32562, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko;. Mogę coś dla ciebie zrobić?', '', 0),
(32563, 'koKR', 'Hej, zaczekaj chwilkę. Widzę, że nie masz własnego latającego wierzchowca.$B$BPewnie nie na wiele się przydasz tutejszym goblinom, jeśli nie możesz się swobodnie przemieszczać. Zapłacili mi, żebym wypożyczał swoje używane wierzchowce takim jak ty – ty nic nie płacisz.$B$B$GZainteresowany:Zainteresowana;?', '', 0),
(32566, 'koKR', 'Chętnie skorzystam.', 'Chętnie skorzystam.', 0),
(32576, 'koKR', 'Jakiej pomocy potrzebujesz?', 'Jakiej pomocy potrzebujesz?', 0),
(32577, 'koKR', 'Mam trop zwornika Norgannona, który strzeże dostępu do archiwów Ulduaru, ale tytani podzielili go na dwie części i ukryli.$B$BJedna z części, skorupa zwornika, znajduje się w Bibliotece Wynalazcy na północnym wybrzeżu, na południe od samego Ulduaru. Najpierw musisz odebrać strażnikom biblioteki fragmenty dysku dostępu.', '', 0),
(32737, 'koKR', 'Jestem Xarantaur, Świadek.', '', 0),
(32738, 'koKR', 'Chcesz usłyszeć opowieść?', '', 0),
(32739, 'koKR', 'Masz dla mnie jakąś opowieść?', '', 0),
(32740, 'koKR', 'Ach tak, czytałem o tobie, $n.', '', 0),
(32741, 'koKR', 'Opowiedz mi o sobie, Xarantaurze. Dlaczego nazywają cię Świadkiem?', 'Opowiedz mi o sobie, Xarantaurze. Dlaczego nazywają cię Świadkiem?', 0),
(32742, 'koKR', 'Byłem jednym z pierwszych taureńskich druidów, z ostatniego pokolenia uczonego przez shan\'do Cenariusa, przed Legionem, przed Rozłamem, gdy świat był jeszcze młody. Zanim wszystko się zmieniło.$B$BGdy moi bracia polowali na wielkie bestie, ja polowałem na opowieści. Do sztuki druidów przywiódł mnie właśnie ten głód, ta żądza wiedzy. Przez jakiś czas był zaspokojony, gdy uczyłem się rozmawiać z drzewami, skałami i zwierzętami i słuchałem ich opowieści.$B$BAle potem nadszedł czas, gdy Cenarius przestał chodzić wśród nas, a moi bracia zaczęli zapominać, czego nas nauczył. Ja jednak nie potrafiłem zapomnieć i wciąż musiałem dowiedzieć się więcej o naszym świecie.$B$BPożegnałem się więc i wyruszyłem poza ziemie mojego ludu.', '', 0),
(32744, 'koKR', 'Przez resztę naturalnego życia wędrowałem w poszukiwaniu wiedzy, widząc więcej cudów i spotykając więcej dziwnych i tajemniczych ras niż ktokolwiek z mojego ludu przede mną. Przemierzyłem pradawny Kalimdor wzdłuż i wszerz, aż nie zostało nic do zobaczenia, żadnych nowych ziem za horyzontem.$B$BA jednak... wciąż tak wiele nie wiedziałem, gdy poczułem, że zbliża się moja ostatnia podróż, i płakałem nad tym, czego nigdy się nie dowiem.$B$BGdy upadłem u kresu życia, właśnie wtedy mnie znaleźli.', '', 0),
(32745, 'koKR', 'Oni?', 'Oni?', 0),
(32746, 'koKR', 'Brązowe Stado. Wyrwali mnie z objęć śmierci i zabrali przed oblicze swojego pana, Nozdormu. Powiedział, że mnie obserwowali i chcieli, żebym kontynuował swoje łowy. Obdarzył mnie nieśmiertelnością obserwatora, którego zadaniem jest być świadkiem historii Azeroth jako jeden z jego wysłanników.$B$BJestem Xarantaur Świadek, a moim obowiązkiem jest strzec prawdziwej historii Azeroth, by nie popadła w zapomnienie.', '', 0),
(32748, 'koKR', 'A historia omal o tobie nie zapomniała. $n $gwalczył:walczyła; dzielnie z Północnym Wiatrem, by ocalić twoją opowieść.', '', 0),
(32750, 'koKR', 'Twoja walka z wiatrem rozegrała się setki lat temu, Burzokopyty. Tak go osłabiłeś, że przez wszystkie te lata milczał.', '', 0),
(32751, 'koKR', 'Ale Północny Wiatr nie pogodził się w milczeniu z porażką. Zamiast tego gromadził moc i czekał na swoją chwilę, uznawszy, że najlepszą zemstą będzie zniszczenie pamięci o tobie, a wraz z nią twojej wioski.', '', 0),
(32752, 'koKR', 'Wiatr posłużył się swoimi sługami, by wypaczyć historię tego miejsca, zmieniając opowieści twojego ludu i niszcząc duchy czcigodnych zmarłych.', '', 0),
(32754, 'koKR', 'Udałoby mu się, gdyby nie to, że $n i ja wytropiliśmy źródło wypaczeń historii, których dopuścił się Północny Wiatr: twoją pradawną bitwę.', '', 0),
(32755, 'koKR', 'Z moją pomocą $n $gcofnął:cofnęła; się w czasie do twojej bitwy i $gdopilnował:dopilnowała;, by historia potoczyła się właściwie. Los Północnego Wiatru został przypieczętowany, a twoja opowieść przywrócona.', '', 0),
(32762, 'koKR', 'Spoczywaj w pokoju, bohaterze.', '', 0),
(32763, 'koKR', '%s tnie cię pazurami!', '', 0),
(32784, 'koKR', 'Twój uchwyt słabnie!', '', 0),
(32794, 'koKR', 'UNIK!', '', 0),
(32795, 'koKR', 'ŚMIERTELNY CIOS CHYBIONY! PODWAŻAJ DALEJ!', '', 0),
(32813, 'koKR', '%s skrzeczy z bólu, wykręca się i chwyta cię paszczą!', '', 0),
(32819, 'koKR', '', 'Straciliśmy już tu na górze kilka dobrych osób. Zaczynam wątpić, czy to miejsce jest warte naszej uwagi.', 0),
(32890, 'koKR', 'Jestem $ggotów:gotowa; wyruszyć dalej w Burzowe Szczyty.', 'Jestem $ggotów:gotowa; wyruszyć dalej w Burzowe Szczyty.', 0),
(32929, 'koKR', 'Król Burzowe Serce przysłał mnie, żebym $gprzeszedł:przeszła; próbę jak mroźnorodny. Jestem $ggotów:gotowa; na próbę, Fjorlinie.', 'Król Burzowe Serce przysłał mnie, żebym $gprzeszedł:przeszła; próbę jak mroźnorodny. Jestem $ggotów:gotowa; na próbę, Fjorlinie.', 0),
(32930, 'koKR', 'Jestem $ggotów:gotowa; dołączyć do walki z żmijami. Masz dla mnie gotowego orła, Fjorlinie?', 'Jestem $ggotów:gotowa; dołączyć do walki z żmijami. Masz dla mnie gotowego orła, Fjorlinie?', 0),
(32956, 'koKR', 'Protosmokowiec czuje wolność i odlatuje do domu!', '', 0),
(33007, 'koKR', 'Witaj, $gmaleńki:maleńka;.', '', 0),
(33008, 'koKR', '', 'To, że coś nie jest zepsute, nie znaczy, że nie można tego naprawić. Czegoś szukasz, skarbie?', 0),
(33009, 'koKR', 'Jak latać w tak mroźnym klimacie?', 'Jak latać w tak mroźnym klimacie?', 0),
(33012, 'koKR', 'Dozownik U.D.E.D. wyczekująco dudni.', '', 0),
(33013, 'koKR', '<Wyjmij bombę z dozownika.>', '<Wyjmij bombę z dozownika.>', 0),
(33042, 'koKR', 'Poszukiwanie skarbów i porządne piwo – lepiej być nie może, $gchłopcze:dziewczyno;.', '', 0),
(33051, 'koKR', 'Młoty ziemnych stoją zjednoczone za Bouldercragiem. Będziemy walczyć ze sługami Lokena do końca.', '', 0),
(33052, 'koKR', 'Pokonaliśmy Valdurana i powalimy jego kolosa.', '', 0),
(33053, 'koKR', 'Dobra walka! Dzień należy do nas, ale wojna trwa!', '', 0),
(33076, 'koKR', 'Tak, $gmaleńki:maleńka;?', '', 0),
(33230, 'koKR', 'Nie oceniam innych po wzroście, lecz po odwadze i lojalności.', '', 0),
(35154, 'koKR', 'Ty nie brać... mnie!', '', 0),
(35155, 'koKR', 'Nie!', '', 0),
(35157, 'koKR', 'Nie zabijać mnie!', '', 0),
(35158, 'koKR', 'Sieć nie zatrzymać mnie! Nie... sieć zatrzymać mnie.', '', 0),
(35159, 'koKR', 'Ja nie bać się!', '', 0),
(68596, 'koKR', 'Nie pokonasz mnie!', '', 0);
